window.QUIZ_BANK={
 id:'higher', title:'Higher Chemistry', subtitle:'Periodicity, structure, rates, enthalpy, equilibrium, redox, organic chemistry, acids and bases, calculations and practical analysis for SQA Higher.',
unitLabel:"Area", topicLabel:"Topic",
 units:[{"id":"ccs","name":"Chemical changes and structure"},{"id":"nc","name":"Nature's chemistry"},{"id":"cis","name":"Chemistry in society"},{"id":"rc","name":"Researching chemistry"}],
 topics:[{"id":"rate","name":"Controlling the rate","unit":"ccs"},{"id":"periodicity","name":"Periodicity","unit":"ccs"},{"id":"structure","name":"Structure and bonding","unit":"ccs"},{"id":"redox","name":"Oxidising and reducing agents","unit":"ccs"},{"id":"systematic","name":"Systematic carbon chemistry","unit":"nc"},{"id":"alcohols","name":"Alcohols","unit":"nc"},{"id":"acids-c","name":"Carboxylic acids","unit":"nc"},{"id":"esters","name":"Esters","unit":"nc"},{"id":"fats","name":"Fats and oils","unit":"nc"},{"id":"soaps","name":"Soaps, detergents and emulsions","unit":"nc"},{"id":"proteins","name":"Proteins","unit":"nc"},{"id":"oxfood","name":"Oxidation of food","unit":"nc"},{"id":"fragrances","name":"Fragrances","unit":"nc"},{"id":"skin","name":"Skin care","unit":"nc"},{"id":"reactants","name":"Getting the most from reactants","unit":"cis"},{"id":"energy","name":"Chemical energy","unit":"cis"},{"id":"equilibria","name":"Equilibria","unit":"cis"},{"id":"analysis","name":"Chemical analysis","unit":"cis"},{"id":"apparatus","name":"Common chemical apparatus","unit":"rc"},{"id":"techniques","name":"General practical techniques","unit":"rc"},{"id":"reporting","name":"Reporting experimental work","unit":"rc"}],
 questions:[
 {id:'bonding-01',topic:'periodicity',q:'Electronegativity increases from sodium to chlorine across Period 3. What is the best explanation?',options:['Nuclear charge increases while atomic size decreases, so bonding electrons are attracted more strongly','The number of occupied electron shells increases, so shielding of the outer electrons increases','The number of outer electrons decreases, so each atom needs to gain fewer electrons','Atoms get larger across the period, so the outer electrons are held less tightly'],answer:0,explanation:'Across a period the nuclear charge rises while the electrons are added to the same shell, so atoms shrink and attract bonding electrons more strongly. The number of shells stays the same across a period.'},
 {id:'bonding-02',topic:'structure',q:'Which of the following bonds is the most polar?',options:['C–N','C–F','C–O','C–Cl'],answer:1,explanation:'Polarity increases with the electronegativity difference. Fluorine is the most electronegative element, so C–F has the largest difference (about 1.5). C–O is the next most polar.'},
 {id:'bonding-03',topic:'structure',q:'Which statement correctly describes a hydrogen bond?',options:['A covalent bond in which hydrogen shares a pair of electrons with oxygen','An attraction between temporary dipoles caused by movement of electrons in neighbouring molecules','An attraction between a δ+ hydrogen bonded to N, O or F and a lone pair on N, O or F in a neighbouring molecule','An attraction between a hydrogen ion and a negative ion in an ionic lattice'],answer:2,explanation:'Hydrogen bonding is a strong type of permanent dipole–dipole attraction between molecules. It is an intermolecular force, not the covalent bond within the molecule.'},
 {id:'bonding-04',topic:'structure',q:'Chlorine is a gas at room temperature but bromine is a liquid. Why?',options:['The covalent bond in Br₂ is stronger than the covalent bond in Cl₂','Br₂ molecules are polar and Cl₂ molecules are non-polar','Bromine forms hydrogen bonds between its molecules but chlorine does not','Br₂ molecules have more electrons, so the London dispersion forces between them are stronger'],answer:3,explanation:'Both are non-polar diatomic molecules, so only London dispersion forces act between them. These increase with the number of electrons, so more energy is needed to separate Br₂ molecules. Melting and boiling do not break the covalent bonds.'},
 {id:'bonding-05',topic:'periodicity',q:'Why is the first ionisation energy of potassium lower than that of sodium?',options:['Potassium has a greater nuclear charge, which pulls its outer electron more strongly towards the nucleus','Potassium has more outer electrons than sodium, so they repel each other and are lost more easily','The outer electron in potassium is further from the nucleus and more shielded by inner electrons','Potassium atoms are smaller than sodium atoms, so the outer electron is lost more easily than from sodium'],answer:2,explanation:'Down a group the outer electron is in a shell further from the nucleus and is screened by more inner shells. The increased nuclear charge is outweighed by these two effects.'},
 {id:'bonding-06',topic:'structure',q:'Which molecule is polar?',options:['CO₂','CH₄','CCl₄','NH₃'],answer:3,explanation:'Ammonia is pyramidal, so its polar N–H bonds do not cancel and the molecule has a permanent dipole. CO₂, CH₄ and CCl₄ are symmetrical, so any bond dipoles cancel (and C–H is almost non-polar).'},
 {id:'structure-01',topic:'structure',q:'Solid sodium chloride does not conduct electricity but molten sodium chloride does. Why?',options:['In the solid the ions are fixed in position, but when molten they are free to move','In the solid there are no charged particles, but melting produces ions from the neutral atoms','Melting releases delocalised electrons that were trapped in the ionic lattice of the solid','Melting breaks the covalent bonds within sodium chloride so electrons can then flow'],answer:0,explanation:'Sodium chloride is made of Na⁺ and Cl⁻ ions at all times. Conduction needs mobile charged particles, which the ions become only when they are free to move in the liquid (or in solution).'},
 {id:'structure-02',topic:'structure',q:'Silicon dioxide has a very high melting point. What is the reason?',options:['Strong London dispersion forces between the many SiO₂ molecules must be overcome','Many strong covalent bonds must be broken throughout the network','Strong ionic attractions between Si⁴⁺ and O²⁻ ions throughout the lattice must be overcome','Delocalised electrons hold the silicon and oxygen atoms together very strongly'],answer:1,explanation:'Silicon dioxide is a covalent network, a continuous lattice of covalently bonded atoms. Melting requires breaking these bonds, not weak forces between discrete molecules.'},
 {id:'structure-03',topic:'structure',q:'Which element exists as a covalent network at room temperature?',options:['Sulfur','Silicon','Phosphorus','Argon'],answer:1,explanation:'Silicon is a covalent network solid with a high melting point. Sulfur (S₈) and phosphorus (P₄) are discrete molecules, and argon is a monatomic gas.'},
 {id:'structure-04',topic:'structure',q:'Which statement best explains why metals conduct electricity?',options:['Delocalised outer electrons are free to move through the lattice','Metal atoms are held together by ionic bonds, so the ions are free to move through the metal','Metal atoms share pairs of electrons in covalent bonds that can be passed along the lattice','Positive ions are free to move through a fixed sea of negative charge, carrying the current'],answer:0,explanation:'In a metallic lattice the outer electrons are delocalised and mobile, so they carry charge when a voltage is applied. The positive ions stay in fixed positions.'},
 {id:'structure-05',topic:'structure',q:'Ethanol (C₂H₅OH) boils at 78 °C but its isomer methoxymethane (CH₃OCH₃) boils at −25 °C. Why is the boiling point of ethanol much higher?',options:['Ethanol molecules have more electrons than methoxymethane molecules, so London dispersion forces are much stronger','The covalent bonds within ethanol molecules are much stronger than those within methoxymethane molecules','Methoxymethane is non-polar, whereas ethanol is polar and so has dipole–dipole forces','Ethanol molecules form hydrogen bonds with each other, but methoxymethane molecules cannot'],answer:3,explanation:'The isomers have the same number of electrons, so London forces are similar. Only ethanol has an O–H bond, so only ethanol can hydrogen bond. Methoxymethane is slightly polar, but its dipole–dipole attractions are much weaker.'},
 {id:'structure-06',topic:'structure',q:'Iodine dissolves readily in hexane but is almost insoluble in water. What is the best explanation?',options:['Iodine reacts with hexane to form a new compound, but it does not react with water at all','Iodine is ionic and so dissolves only in non-polar solvents such as hexane','Iodine and hexane are both non-polar so they mix, but water prefers to hydrogen bond to itself','Hexane is polar and so attracts the non-polar iodine molecules strongly, unlike water'],answer:2,explanation:'Non-polar substances dissolve in non-polar solvents because London forces between I₂ and hexane are similar to those in the pure substances. Water’s strong hydrogen bonding is not replaced by anything comparable.'},
 {id:'rates-01',topic:'rate',q:'Why does increasing the temperature greatly increase the rate of a reaction?',options:['The activation energy of the reaction decreases as the temperature is raised','Particles collide more often, which is the only effect that temperature has on the rate','The enthalpy change of the reaction becomes more negative at higher temperature','A larger fraction of collisions have at least the activation energy'],answer:3,explanation:'At higher temperature more particles have energy ≥ the activation energy, so a greater proportion of collisions are successful. Collision frequency rises slightly, but this alone cannot explain the large effect, and activation energy does not change.'},
 {id:'rates-02',topic:'rate',q:'How does a catalyst increase the rate of a reaction?',options:['It increases the kinetic energy of the colliding particles at a given temperature','It makes the reaction more exothermic, so more energy is available','It provides an alternative pathway with a lower activation energy','It raises the activation energy so that fewer, more energetic collisions occur'],answer:2,explanation:'A catalyst lowers the activation energy so a greater fraction of collisions are successful at the same temperature. It does not change the enthalpy change.'},
 {id:'rates-03',topic:'rate',q:'In an experiment the total volume of carbon dioxide collected is 30 cm³ after 20 s and 66 cm³ after 50 s. What is the average rate of reaction between 20 s and 50 s?',options:['1.3 cm³ s⁻¹','1.2 cm³ s⁻¹','1.5 cm³ s⁻¹','0.83 cm³ s⁻¹'],answer:1,explanation:'Average rate = change in volume ÷ change in time = (66 − 30) ÷ (50 − 20) = 36 ÷ 30 = 1.2 cm³ s⁻¹. Dividing 66 by 50 would give the rate from the start, not for this interval.'},
 {id:'rates-04',topic:'rate',q:'What happens to the distribution of kinetic energies of the molecules in a gas when the temperature is raised?',options:['The peak moves to higher energy and more molecules have energy above the activation energy','The peak moves to lower energy and fewer molecules have energy above the activation energy','The peak stays in the same place but the activation energy moves to a lower value','The curve is unchanged but the molecules collide more frequently'],answer:0,explanation:'Raising the temperature increases the average kinetic energy, so the distribution flattens and shifts to higher energy. The activation energy is fixed, so a greater proportion of molecules exceed it.'},
 {id:'rates-05',topic:'rate',q:'The forward reaction in an equilibrium has an activation energy of 80 kJ mol⁻¹ and an enthalpy change of −30 kJ mol⁻¹. What is the activation energy of the reverse reaction?',options:['50 kJ mol⁻¹','110 kJ mol⁻¹','80 kJ mol⁻¹','30 kJ mol⁻¹'],answer:1,explanation:'The forward reaction is exothermic, so the products are 30 kJ mol⁻¹ lower in enthalpy than the reactants. The reverse reaction must climb the same barrier from a lower start: 80 + 30 = 110 kJ mol⁻¹.'},
 {id:'rates-06',topic:'rate',q:'The same mass of zinc reacts faster with excess dilute acid as powder than as granules. What is the reason?',options:['The powder lowers the activation energy of the reaction between zinc and acid','Collisions with the powder are more energetic than collisions with the granules at the same temperature','The powder has a greater surface area, so collisions between zinc and acid are more frequent','The powder contains more zinc atoms than the same mass of granules, so more can react'],answer:2,explanation:'Surface area affects only how often particles collide, not their energy or the activation energy. The same mass contains the same number of atoms, so the powder simply exposes more of them.'},
 {id:'enthalpy-01',topic:'energy',q:'The temperature of the solution rises when two solutions are mixed and react. Which statement is correct?',options:['The reaction is endothermic and the enthalpy change has a negative value','The reaction is exothermic and the enthalpy change has a positive value','The reaction is endothermic and the enthalpy change has a positive value','The reaction is exothermic and the enthalpy change has a negative value'],answer:3,explanation:'Heat released to the surroundings makes the temperature rise. The products have lower enthalpy than the reactants, so ΔH is negative.'},
 {id:'enthalpy-02',topic:'energy',q:'Burning 0.46 g of ethanol (gram formula mass 46 g) raises the temperature of 250 g of water by 10.0 °C. What is the enthalpy of combustion of ethanol? (c = 4.18 kJ kg⁻¹ °C⁻¹)',options:['−1045 kJ mol⁻¹','−10.45 kJ mol⁻¹','−104.5 kJ mol⁻¹','+1045 kJ mol⁻¹'],answer:0,explanation:'Heat = cmΔT = 4.18 × 0.250 × 10.0 = 10.45 kJ. Moles of ethanol = 0.46 ÷ 46 = 0.0100 mol, so 10.45 ÷ 0.0100 = 1045 kJ mol⁻¹, and the sign is negative because heat is released.'},
 {id:'enthalpy-03',topic:'energy',q:'C(s) + O₂(g) → CO₂(g) has ΔH = −394 kJ mol⁻¹ and CO(g) + ½O₂(g) → CO₂(g) has ΔH = −283 kJ mol⁻¹. What is ΔH for C(s) + ½O₂(g) → CO(g)?',options:['−677 kJ mol⁻¹','+111 kJ mol⁻¹','+677 kJ mol⁻¹','−111 kJ mol⁻¹'],answer:3,explanation:'By Hess’s law, ΔH(C → CO) = ΔH(C → CO₂) − ΔH(CO → CO₂) = −394 − (−283) = −111 kJ mol⁻¹. Adding the two values would be incorrect because CO₂ must cancel.'},
 {id:'enthalpy-04',topic:'energy',q:'Mean bond enthalpies (kJ mol⁻¹): N≡N 945, H–H 436, N–H 391. Use these to calculate ΔH for N₂ + 3H₂ → 2NH₃.',options:['−93 kJ mol⁻¹','+93 kJ mol⁻¹','−186 kJ mol⁻¹','−2346 kJ mol⁻¹'],answer:0,explanation:'Bonds broken: 945 + 3(436) = 2253 kJ. Bonds made: 6(391) = 2346 kJ. ΔH = 2253 − 2346 = −93 kJ mol⁻¹; more energy is released making bonds than is absorbed breaking them.'},
 {id:'enthalpy-05',topic:'energy',q:'Which equation represents the enthalpy of formation of ethanol?',options:['C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l)','2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l)','2C(g) + 6H(g) + O(g) → C₂H₅OH(l)','C₂H₄(g) + H₂O(l) → C₂H₅OH(l)'],answer:1,explanation:'Enthalpy of formation is the enthalpy change when one mole of a compound is formed from its elements in their standard states. The third equation starts from gaseous atoms and the fourth from compounds; the first is combustion.'},
 {id:'enthalpy-06',topic:'energy',q:'A reaction is exothermic overall. What does this tell you about the bonds in the reaction?',options:['Fewer bonds are broken in the reactants than are made in the products','Energy is released when the bonds in the reactants are broken','More energy is released making the bonds in the products than is absorbed breaking the bonds in the reactants','The bonds in the reactants are weaker than the bonds in the products, so the reaction needs no activation energy'],answer:2,explanation:'Bond breaking absorbs energy and bond making releases it. The net result is exothermic when the energy released exceeds the energy absorbed. Bond breaking is always endothermic, and activation energy is still required.'},
 {id:'equilibrium-01',topic:'equilibria',q:'Which statement describes a system at dynamic equilibrium?',options:['The forward and reverse reactions have both stopped','The concentrations of reactants and products are equal','The rates of the forward and reverse reactions are equal and the concentrations stay constant','The forward reaction has a faster rate than the reverse reaction'],answer:2,explanation:'At equilibrium the reactions continue in both directions at the same rate, so there is no overall change. The concentrations are constant but not necessarily equal.'},
 {id:'equilibrium-02',topic:'equilibria',q:'N₂(g) + 3H₂(g) ⇌ 2NH₃(g) is exothermic in the forward direction. What is the effect of increasing the pressure at constant temperature?',options:['The equilibrium shifts to the left and the yield of ammonia decreases','The equilibrium shifts to the right and the yield of ammonia increases','The equilibrium is unchanged because pressure has no effect on gases','The equilibrium shifts to the right because the reaction becomes exothermic'],answer:1,explanation:'There are 4 moles of gas on the left and 2 on the right. Higher pressure favours the side with fewer gas molecules, which is the product side.'},
 {id:'equilibrium-03',topic:'equilibria',q:'The Haber process is carried out at about 450 °C, although the forward reaction is exothermic and a lower temperature would give a higher yield. Why is 450 °C used?',options:['It is a compromise that gives an acceptable rate while still giving a reasonable yield','A higher temperature increases both the yield and the rate of reaction, so 450 °C is best','The iron catalyst only works at temperatures below the boiling point of ammonia','The reaction is endothermic overall and needs continuous heat to proceed'],answer:0,explanation:'A lower temperature favours the exothermic forward reaction but is too slow to be economic. A higher temperature gives a faster rate but a lower yield, so a moderate temperature is chosen.'},
 {id:'equilibrium-04',topic:'equilibria',q:'What is the effect of adding a catalyst to a reaction at equilibrium?',options:['The position of equilibrium shifts to the right and the yield increases','The position of equilibrium shifts to the left and the yield decreases','The forward rate increases but the reverse rate is unaffected','The position of equilibrium is unchanged and equilibrium is reached sooner'],answer:3,explanation:'A catalyst speeds up the forward and reverse reactions equally. It therefore changes how fast equilibrium is reached but not the equilibrium concentrations.'},
 {id:'equilibrium-05',topic:'equilibria',q:'2SO₂(g) + O₂(g) ⇌ 2SO₃(g). More oxygen is added to the mixture at equilibrium at constant temperature. What happens when a new equilibrium is established?',options:['The concentration of SO₂ is lower and the concentration of SO₃ is higher','The concentration of SO₂ is higher and the concentration of SO₃ is lower','The concentrations of both SO₂ and SO₃ are higher','The concentrations of SO₂ and SO₃ are unchanged'],answer:0,explanation:'Adding a reactant causes the equilibrium to shift to the right to use up some of the extra oxygen. This consumes SO₂ and produces more SO₃.'},
 {id:'equilibrium-06',topic:'equilibria',q:'The equilibrium Cr₂O₇²⁻(aq) + H₂O(l) ⇌ 2CrO₄²⁻(aq) + 2H⁺(aq) has orange dichromate on the left and yellow chromate on the right. Why does an orange solution turn yellow when sodium hydroxide solution is added?',options:['Hydroxide ions react with chromate ions, so the equilibrium shifts to the left','Sodium ions react with dichromate ions to form a yellow compound','Hydroxide ions increase the H⁺ concentration, shifting the equilibrium to the right','Hydroxide ions react with H⁺ ions, so the equilibrium shifts to the right'],answer:3,explanation:'OH⁻ reacts with H⁺ to form water, lowering the H⁺ concentration. The equilibrium shifts to the right to replace the H⁺, producing more yellow chromate.'},
 {id:'redox-01',topic:'redox',q:'In the reaction Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s), which statement is correct?',options:['Cu²⁺ is the reducing agent because it gains electrons','Zn is the oxidising agent because it loses electrons','Cu²⁺ is the oxidising agent because it gains electrons','Zn is the oxidising agent because it is reduced'],answer:2,explanation:'Zn loses electrons (is oxidised) so it is the reducing agent. Cu²⁺ gains electrons (is reduced) so it is the oxidising agent.'},
 {id:'redox-02',topic:'redox',q:'Which ion-electron equation correctly represents the reduction of permanganate ions to manganese(II) ions in acid solution?',options:['MnO₄⁻ + 4H⁺ + 3e⁻ → Mn²⁺ + 2H₂O','MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O','MnO₄⁻ + 8H⁺ → Mn²⁺ + 4H₂O + 5e⁻','MnO₄⁻ + 8H⁺ + 7e⁻ → Mn²⁺ + 4H₂O'],answer:1,explanation:'Mn goes from +7 to +2, so 5 electrons are gained on the left. 4 oxygen atoms need 4H₂O, which needs 8H⁺. The charge is (−1 + 8 − 5) = +2 on each side. Electrons on the right would be oxidation.'},
 {id:'redox-03',topic:'redox',q:'Molten sodium chloride is electrolysed using inert electrodes. What forms at the positive electrode?',options:['Sodium metal, by Na⁺ + e⁻ → Na','Chlorine gas, by Cl₂ + 2e⁻ → 2Cl⁻','Oxygen gas, by 4OH⁻ → O₂ + 2H₂O + 4e⁻','Chlorine gas, by 2Cl⁻ → Cl₂ + 2e⁻'],answer:3,explanation:'Negative chloride ions are attracted to the positive electrode, where they lose electrons (oxidation) to form chlorine. Sodium forms at the negative electrode, and there is no water or hydroxide in the molten salt.'},
 {id:'redox-04',topic:'redox',q:'Acidified potassium dichromate solution is warmed with an excess of an aqueous solution of iron(II) sulfate. What is observed, and what is the reason?',options:['The solution turns from orange to green because dichromate ions are reduced','The solution turns from green to orange because dichromate ions are oxidised by the iron(II) ions','The solution turns from orange to green because iron(II) ions are reduced to iron metal','The solution stays orange because iron(II) ions cannot be oxidised by dichromate ions at all'],answer:0,explanation:'Dichromate (Cr₂O₇²⁻, orange) is a strong oxidising agent. It gains electrons and is reduced to green Cr³⁺, while Fe²⁺ is oxidised to Fe³⁺. Dichromate is the oxidising agent, so it is reduced, not oxidised.'},
 {id:'redox-05',topic:'redox',q:'In a titration, 20.0 cm³ of acidified iron(II) solution requires 15.0 cm³ of 0.0200 mol l⁻¹ potassium permanganate for complete reaction. MnO₄⁻ + 8H⁺ + 5Fe²⁺ → Mn²⁺ + 4H₂O + 5Fe³⁺. What is the concentration of the iron(II) solution?',options:['0.0750 mol l⁻¹','0.0150 mol l⁻¹','0.375 mol l⁻¹','0.00750 mol l⁻¹'],answer:0,explanation:'Moles of MnO₄⁻ = 0.0200 × 0.0150 = 3.00 × 10⁻⁴. The mole ratio is 1 : 5, so moles of Fe²⁺ = 1.50 × 10⁻³. Concentration = 1.50 × 10⁻³ ÷ 0.0200 = 0.0750 mol l⁻¹. Ignoring the 1 : 5 ratio gives 0.0150.'},
 {id:'redox-06',topic:'redox',q:'Which of the following metals is the strongest reducing agent?',options:['Zinc','Iron','Magnesium','Copper'],answer:2,explanation:'Metals higher in the electrochemical series lose electrons more readily, so they are stronger reducing agents. Magnesium is above zinc, iron and copper.'},
 {id:'organic-01',topic:'systematic',q:'Ethene reacts with bromine to form 1,2-dibromoethane. What type of reaction is this?',options:['Substitution','Addition','Condensation','Hydrolysis'],answer:1,explanation:'The C=C double bond opens and a bromine atom adds to each carbon, giving a single product. Substitution would replace an atom or group and release a second product.'},
 {id:'organic-02',topic:'systematic',q:'How many structural isomers are there of pentane, C₅H₁₂ (including pentane itself)?',options:['2','4','5','3'],answer:3,explanation:'The isomers are pentane, 2-methylbutane and 2,2-dimethylpropane. Each has the same molecular formula but a different arrangement of carbon atoms.'},
 {id:'organic-03',topic:'esters',q:'What is the name of the ester made from propanoic acid and methanol?',options:['Propyl methanoate','Methyl ethanoate','Methyl propanoate','Propyl ethanoate'],answer:2,explanation:'The alcohol gives the first part of the name (methyl) and the carboxylic acid gives the second (propanoate). Propyl methanoate would come from methanoic acid and propan-1-ol.'},
 {id:'organic-04',topic:'fats',q:'Why do oils have lower melting points than fats?',options:['Oil molecules contain more C=C bonds, so they pack less closely and have weaker London dispersion forces','Oil molecules are shorter than fat molecules, so they have fewer electrons and weaker covalent bonds','Oils contain hydroxyl groups that form fewer hydrogen bonds than fats','Oil molecules are saturated and so have weaker covalent bonds'],answer:0,explanation:'Oils contain more unsaturated fatty acid chains. The kinks around C=C bonds stop molecules packing closely, so the London forces are weaker and less energy is needed to melt them.'},
 {id:'organic-05',topic:'proteins',q:'Two amino acids join together to form a dipeptide. Which statement is correct?',options:['A peptide link forms and a molecule of water is released','A peptide link forms and a molecule of carbon dioxide is released','An ester link forms and a molecule of water is released','A peptide link forms and no other product is formed'],answer:0,explanation:'The amine group of one amino acid reacts with the carboxyl group of the other in a condensation reaction, forming an amide (peptide) link, –CONH–, and water.'},
 {id:'organic-06',topic:'alcohols',q:'Which alcohol cannot be oxidised by acidified potassium dichromate solution?',options:['Propan-2-ol','Butan-1-ol','2-methylpropan-2-ol','2-methylpropan-1-ol'],answer:2,explanation:'Tertiary alcohols have no hydrogen on the carbon bearing the –OH group, so they cannot be oxidised. Propan-2-ol is oxidised to a ketone, and primary alcohols to aldehydes and then carboxylic acids.'},
 {id:'acids-01',topic:'equilibria',q:'What is the pH of a 0.01 mol l⁻¹ solution of hydrochloric acid?',options:['1','12','0.01','2'],answer:3,explanation:'HCl is a strong acid and so fully ionised: [H⁺] = 0.01 = 10⁻² mol l⁻¹, so pH = 2. The pH value is not the concentration.'},
 {id:'acids-02',topic:'equilibria',q:'What is the pH of a 0.001 mol l⁻¹ solution of sodium hydroxide at 25 °C?',options:['3','11','10','14'],answer:1,explanation:'[OH⁻] = 10⁻³ mol l⁻¹, and [H⁺][OH⁻] = 10⁻¹⁴, so [H⁺] = 10⁻¹¹ mol l⁻¹ and pH = 11. A pH of 3 would be an acid.'},
 {id:'acids-03',topic:'equilibria',q:'25 cm³ of 0.1 mol l⁻¹ hydrochloric acid and 25 cm³ of 0.1 mol l⁻¹ ethanoic acid are each neutralised by sodium hydroxide. Which statement is correct?',options:['More sodium hydroxide is needed for hydrochloric acid because it is a stronger acid with more H⁺','More sodium hydroxide is needed for ethanoic acid because it is only partly ionised','The same volume of sodium hydroxide is needed for each, but the hydrochloric acid has the lower pH','The same volume is needed for each acid and both solutions have the same pH'],answer:2,explanation:'Both acids are monoprotic and contain the same number of moles, so they react with the same amount of alkali. Ethanoic acid is only partially ionised, so its [H⁺] is lower and its pH is higher.'},
 {id:'acids-04',topic:'equilibria',q:'The pH of a solution is increased from 3 to 5. How does the hydrogen ion concentration change?',options:['It decreases by a factor of 100','It decreases by a factor of 2','It increases by a factor of 100','It increases by a factor of 2'],answer:0,explanation:'[H⁺] = 10⁻ᵖᴴ. At pH 3 it is 10⁻³ and at pH 5 it is 10⁻⁵ mol l⁻¹, so it falls to one hundredth of its value.'},
 {id:'acids-05',topic:'equilibria',q:'Which solution has a pH greater than 7?',options:['Ammonium chloride','Sodium ethanoate','Sodium chloride','Potassium nitrate'],answer:1,explanation:'Sodium ethanoate is the salt of a strong base and a weak acid. Ethanoate ions react with water to form ethanoic acid and OH⁻, so the solution is alkaline. Ammonium chloride gives an acidic solution and the others are neutral.'},
 {id:'acids-06',topic:'equilibria',q:'10.0 cm³ of 0.100 mol l⁻¹ hydrochloric acid is diluted with water to a total volume of 1000 cm³. What is the pH of the diluted solution?',options:['1','2','5','3'],answer:3,explanation:'Moles of HCl = 0.100 × 0.0100 = 1.00 × 10⁻³ mol in 1.00 litre, so [H⁺] = 10⁻³ mol l⁻¹ and pH = 3. The dilution factor is 100, so the pH rises by 2 from the original 1.'},
 {id:'calcs-01',topic:'reactants',q:'What mass of anhydrous sodium carbonate, Na₂CO₃, is 0.25 mol? (GFM = 106 g)',options:['53 g','106 g','26.5 g','424 g'],answer:2,explanation:'Mass = moles × gram formula mass = 0.25 × 106 = 26.5 g.'},
 {id:'calcs-02',topic:'reactants',q:'4.0 g of sodium hydroxide (GFM 40 g) is dissolved in water and made up to 500 cm³ of solution. What is the concentration?',options:['0.10 mol l⁻¹','0.080 mol l⁻¹','8.0 mol l⁻¹','0.20 mol l⁻¹'],answer:3,explanation:'Moles = 4.0 ÷ 40 = 0.10 mol. Concentration = 0.10 ÷ 0.500 = 0.20 mol l⁻¹. The volume must be converted from cm³ to litres.'},
 {id:'calcs-03',topic:'reactants',q:'Iron and sulfur react as Fe + S → FeS. 5.6 g of iron (GFM 56 g) is heated with 4.0 g of sulfur (GFM 32 g). What is the maximum mass of iron(II) sulfide (GFM 88 g) formed?',options:['4.4 g','8.8 g','9.6 g','11.0 g'],answer:1,explanation:'Moles: Fe = 0.100 mol, S = 0.125 mol. They react 1 : 1, so iron is limiting and 0.100 mol of FeS forms: 0.100 × 88 = 8.8 g. 9.6 g is the sum of the masses, but some sulfur is left over.'},
 {id:'calcs-04',topic:'reactants',q:'Magnesium burns in oxygen: 2Mg + O₂ → 2MgO. Burning 4.8 g of magnesium (GFM 24 g) gives 6.4 g of magnesium oxide (GFM 40 g). What is the percentage yield?',options:['80%','75%','125%','40%'],answer:0,explanation:'0.20 mol of Mg should give 0.20 mol of MgO = 8.0 g (theoretical). Percentage yield = 6.4 ÷ 8.0 × 100 = 80%. Inverting the fraction would give an impossible 125%.'},
 {id:'calcs-05',topic:'reactants',q:'Calcium oxide is made by heating calcium carbonate: CaCO₃ → CaO + CO₂. What is the atom economy for making calcium oxide? (GFMs: CaCO₃ 100 g, CaO 56 g, CO₂ 44 g)',options:['56%','44%','78%','100%'],answer:0,explanation:'Atom economy = mass of desired product ÷ total mass of reactants × 100 = 56 ÷ 100 × 100 = 56%. The remaining 44% of the mass ends up as carbon dioxide.'},
 {id:'calcs-06',topic:'analysis',q:'25.0 cm³ of sodium hydroxide solution is neutralised by 20.0 cm³ of 0.100 mol l⁻¹ sulfuric acid. 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. What is the concentration of the sodium hydroxide?',options:['0.0800 mol l⁻¹','0.160 mol l⁻¹','0.125 mol l⁻¹','0.320 mol l⁻¹'],answer:1,explanation:'Moles of H₂SO₄ = 0.100 × 0.0200 = 2.00 × 10⁻³. The ratio is 2 : 1, so moles NaOH = 4.00 × 10⁻³. Concentration = 4.00 × 10⁻³ ÷ 0.0250 = 0.160 mol l⁻¹. Forgetting the ratio gives 0.0800.'},
 {id:'analysis-01',topic:'analysis',q:'In paper chromatography, one substance travels further up the paper than another. What does this show?',options:['It has a higher boiling point than the other substance','It is held more strongly by the paper and less soluble in the solvent','It is ionic, whereas the other substance is covalent','It is more soluble in the solvent and is held less strongly by the paper'],answer:3,explanation:'Separation depends on the balance of attraction to the mobile phase (solvent) and to the stationary phase (paper). A component that prefers the solvent is carried further.'},
 {id:'analysis-02',topic:'apparatus',q:'Before a titration, which piece of apparatus may be rinsed with distilled water only and left wet?',options:['The burette','The pipette','The conical flask','The funnel used to fill the burette with the solution'],answer:2,explanation:'The burette and pipette must be rinsed with the solution they will contain, because water left inside would dilute it. Water in the flask does not change the number of moles of reactant added to it.'},
 {id:'analysis-03',topic:'analysis',q:'2.50 g of hydrated copper(II) sulfate, CuSO₄·xH₂O, is heated until it reaches constant mass, leaving 1.60 g of anhydrous CuSO₄ (GFM 160 g). What is the value of x? (GFM of H₂O = 18 g)',options:['2','4','10','5'],answer:3,explanation:'Moles of CuSO₄ = 1.60 ÷ 160 = 0.0100. Mass of water lost = 0.90 g, which is 0.90 ÷ 18 = 0.0500 mol. Ratio water : CuSO₄ = 5 : 1, so x = 5. Heating to constant mass ensures all the water has been removed.'},
 {id:'analysis-04',topic:'analysis',q:'Ethanoic acid is titrated with sodium hydroxide solution. Colour change ranges: methyl orange pH 3.1–4.4, bromothymol blue pH 6.0–7.6, phenolphthalein pH 8.3–10.0. Which indicator is most suitable?',options:['Phenolphthalein','Methyl orange','Bromothymol blue','Any of the three, as the end point is the same'],answer:0,explanation:'At the end point the solution contains sodium ethanoate, which is alkaline (pH above 7). The indicator must change colour in that region, so phenolphthalein is best. Methyl orange changes far too early.'},
 {id:'analysis-05',topic:'techniques',q:'Four titres are recorded: 22.4, 20.1, 20.0 and 20.2 cm³. Concordant results are within 0.2 cm³ of each other. What average titre should be used?',options:['20.0 cm³','20.2 cm³','20.1 cm³','20.7 cm³'],answer:2,explanation:'The first titre is not concordant with the others, so it is discarded. The mean of 20.1, 20.0 and 20.2 is 20.1 cm³. Including 22.4 would give 20.7 cm³, which is not representative.'},
 {id:'analysis-06',topic:'analysis',q:'Which substance is most suitable as a primary standard for preparing a standard solution?',options:['Sodium hydroxide','Anhydrous sodium carbonate','Potassium permanganate','Concentrated hydrochloric acid'],answer:1,explanation:'A primary standard is pure, stable, soluble, and has a known formula and a reasonably high gram formula mass. Sodium hydroxide absorbs water and carbon dioxide, permanganate slowly decomposes, and concentrated HCl has a variable concentration.'},
 // batch 2026-11-26: 23 questions merged from a ChatGPT set (7 duplicates skipped)
 {id:'bonding-07',topic:'periodicity',q:'Which equation represents the first ionisation energy of magnesium?',options:['Mg(s) → Mg⁺(g) + e⁻','Mg(g) + e⁻ → Mg⁻(g)','Mg(g) → Mg²⁺(g) + 2e⁻','Mg(g) → Mg⁺(g) + e⁻'],answer:3,explanation:'First ionisation removes one electron from each gaseous atom to form a gaseous 1+ ion.',why:['The initial atom must be gaseous, not solid.','This is electron gain, not ionisation by electron removal.','First ionisation removes just one electron, not two.','First ionisation removes one electron from each gaseous atom to form a gaseous 1+ ion.']},
 {id:'bonding-08',topic:'periodicity',q:'An element has successive ionisation energies of 590, 1150, 4940 and 6480 kJ mol⁻¹. What does the large jump indicate?',options:['It has two outer-shell electrons','It has three outer-shell electrons','It has four outer-shell electrons','It gains two electrons during ionisation'],answer:0,explanation:'After two electrons are removed, the next electron comes from an inner shell and is much harder to remove.',why:['After two electrons are removed, the next electron comes from an inner shell and is much harder to remove.','Three outer electrons would give the large jump after the third removal.','Four outer electrons would put the large jump after the fourth removal.','Ionisation energies describe electron removal, not electron gain.']},
 {id:'structure-07',topic:'structure',q:'Which substance can form hydrogen bonds between its own molecules?',options:['CH₄','HCl','CH₃OH','CO₂'],answer:2,explanation:'Methanol contains O–H bonds and oxygen lone pairs, allowing hydrogen bonds between molecules.',why:['Methane has no hydrogen bonded to nitrogen, oxygen or fluorine.','HCl is polar, but it does not form the hydrogen bonding required here.','Methanol contains O–H bonds and oxygen lone pairs, allowing hydrogen bonds between molecules.','Carbon dioxide contains no hydrogen atoms.']},
 {id:'bonding-09',topic:'structure',q:'CO₂ contains polar C=O bonds. Why is the molecule non-polar overall?',options:['Its bonds contain no shared electrons','Its linear shape makes the equal bond dipoles cancel','Oxygen and carbon have identical electronegativities','All molecules containing two oxygen atoms are non-polar'],answer:1,explanation:'The two equal C=O dipoles point in opposite directions in a linear molecule, so their effects cancel.',why:['Covalent bonds involve shared electrons; polarity concerns unequal sharing.','The two equal C=O dipoles point in opposite directions in a linear molecule, so their effects cancel.','Oxygen is more electronegative than carbon, making each C=O bond polar.','Overall polarity depends on bond polarity and shape; the atom count alone is insufficient.']},
 {id:'rates-07',topic:'rate',q:'A fixed visible change takes 80 s in experiment A and 20 s in experiment B. Using relative rate = 1/time, how does B compare with A?',options:['B is four times as fast','B is one quarter as fast','B is 60 times as fast','Both have the same relative rate'],answer:0,explanation:'The ratio is (1/20) ÷ (1/80) = 4. The same change occurs in one quarter of the time.',why:['The ratio is (1/20) ÷ (1/80) = 4. The same change occurs in one quarter of the time.','This reverses the rate ratio.','Subtracting the times gives 60 s, not a rate ratio.','Different times for the same endpoint give different relative rates.']},
 {id:'redox-07',topic:'redox',q:'Acidified permanganate ions are reduced to Mn²⁺. How many Fe²⁺ ions can one MnO₄⁻ ion oxidise to Fe³⁺?',options:['One','Two','Four','Five'],answer:3,explanation:'MnO₄⁻ gains five electrons in acid: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O. Each Fe²⁺ loses one electron, giving a 1:5 ratio.',why:['One Fe²⁺ supplies only one electron, while permanganate needs five.','Two Fe²⁺ supply only two electrons.','Four Fe²⁺ supply only four electrons.','MnO₄⁻ gains five electrons in acid: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O. Each Fe²⁺ loses one electron, giving a 1:5 ratio.']},
 {id:'organic-07',topic:'alcohols',q:'Which product forms when pentan-2-ol is oxidised under suitable conditions?',options:['Pentanal','Pentanoic acid','Pentan-2-one','Pentane'],answer:2,explanation:'Pentan-2-ol is secondary. Oxidation forms a ketone with the carbonyl at carbon 2.',why:['Pentanal is an aldehyde associated with oxidation of the primary alcohol pentan-1-ol.','A secondary alcohol does not give this carboxylic acid by the usual school oxidation reaction.','Pentan-2-ol is secondary. Oxidation forms a ketone with the carbonyl at carbon 2.','Conversion to an alkane is not this oxidation reaction.']},
 {id:'organic-08',topic:'alcohols',q:'Which observation distinguishes propanal from propanone using warm Fehling’s solution?',options:['Propanal forms a brick-red precipitate; propanone does not','Both form a silver mirror','Propanone forms a brick-red precipitate; propanal does not','Neither changes the blue solution'],answer:0,explanation:'The aldehyde is oxidised and reduces copper(II) to a brick-red copper(I) oxide precipitate. The ketone gives no such reaction.',why:['The aldehyde is oxidised and reduces copper(II) to a brick-red copper(I) oxide precipitate. The ketone gives no such reaction.','A silver mirror is associated with Tollens’ reagent, not Fehling’s solution.','This reverses the aldehyde and ketone results.','Propanal gives a positive Fehling’s test.']},
 {id:'organic-09',topic:'esters',q:'Which ester forms from ethanol and butanoic acid?',options:['Butyl ethanoate','Ethyl butanoate','Methyl butanoate','Ethyl propanoate'],answer:1,explanation:'The alcohol gives ethyl; the carboxylic acid gives butanoate.',why:['This name corresponds to butan-1-ol and ethanoic acid.','The alcohol gives ethyl; the carboxylic acid gives butanoate.','Methyl would come from methanol rather than ethanol.','Propanoate would come from propanoic acid rather than butanoic acid.']},
 {id:'organic-10',topic:'esters',q:'Which products form when methyl ethanoate undergoes hydrolysis with water?',options:['Ethanol and methanoic acid','Methanol and ethanol','Ethane and methanoic acid','Methanol and ethanoic acid'],answer:3,explanation:'Methyl identifies the methanol part and ethanoate identifies the ethanoic-acid part. Hydrolysis reverses the condensation.',why:['This pair would form ethyl methanoate, a different ester.','Hydrolysis produces an alcohol and a carboxylic acid, not two alcohols.','An alkane is not one of these ester hydrolysis products.','Methyl identifies the methanol part and ethanoate identifies the ethanoic-acid part. Hydrolysis reverses the condensation.']},
 {id:'organic-11',topic:'soaps',q:'How does a soap molecule arrange itself at an oil–water boundary?',options:['Its hydrophobic tail enters the oil and its ionic head interacts with water','Its ionic head enters the oil and its tail dissolves in water','Both parts must remain entirely in the oil','Both parts must remain entirely in the water'],answer:0,explanation:'The non-polar tail associates with oil while the hydrophilic ionic head interacts with water, helping disperse oil droplets.',why:['The non-polar tail associates with oil while the hydrophilic ionic head interacts with water, helping disperse oil droplets.','This reverses the affinities of the head and tail.','Keeping the ionic head in oil does not favour its interactions with water.','The hydrocarbon tail is hydrophobic and associates with oil.']},
 {id:'organic-12',topic:'oxfood',q:'How can an antioxidant help protect food from oxidation?',options:['It supplies oxygen to the food','It is oxidised in preference to susceptible food components','It converts every unsaturated fat into a saturated fat','It prevents all molecular collisions'],answer:1,explanation:'An antioxidant can act as a reducing agent, being oxidised itself and slowing oxidation of other components.',why:['Supplying oxygen does not explain protection against oxidation.','An antioxidant can act as a reducing agent, being oxidised itself and slowing oxidation of other components.','Hydrogenation requires different conditions; this is not the general action of an antioxidant.','Antioxidants do not stop molecular motion or collisions.']},
 {id:'organic-13',topic:'fragrances',q:'A terpene has 15 carbon atoms and is built from isoprene units. How many isoprene units does it contain?',options:['Two','Four','Five','Three'],answer:3,explanation:'Each isoprene unit contributes five carbon atoms: 15 ÷ 5 = 3.',why:['Two five-carbon units supply ten carbons.','Four five-carbon units supply twenty carbons.','Five units supply twenty-five carbons.','Each isoprene unit contributes five carbon atoms: 15 ÷ 5 = 3.']},
 {id:'organic-14',topic:'skin',q:'Which event is a termination step in a free-radical chain reaction?',options:['Cl₂ absorbs light and forms two Cl• radicals','Cl• reacts with CH₄ to form HCl and CH₃•','CH₃• combines with Cl• to form CH₃Cl','CH₃• reacts with Cl₂ to form CH₃Cl and Cl•'],answer:2,explanation:'Two radicals combine to make a non-radical product. No new radical forms, terminating those chains.',why:['Formation of radicals from a non-radical molecule is initiation.','A radical is consumed but another radical forms, so this is propagation.','Two radicals combine to make a non-radical product. No new radical forms, terminating those chains.','A radical is regenerated, so this is propagation.']},
 {id:'organic-15',topic:'proteins',q:'What happens during hydrolysis of a peptide link?',options:['Water is used to split the link, regenerating amino and carboxyl groups','Water is removed to form the link','Only the protein’s shape changes; no covalent bonds break','Every carbon–carbon bond is broken'],answer:0,explanation:'Hydrolysis uses water to break the peptide (amide) link. Complete hydrolysis of a protein produces amino acids.',why:['Hydrolysis uses water to break the peptide (amide) link. Complete hydrolysis of a protein produces amino acids.','Removing water to form the link describes condensation.','A shape change without peptide-link cleavage describes denaturation rather than hydrolysis.','Hydrolysis targets peptide links; it does not break every carbon–carbon bond.']},
 {id:'calcs-07',topic:'reactants',q:'N₂ + 3H₂ → 2NH₃. A mixture contains 0.40 mol N₂ and 0.90 mol H₂. What is the maximum amount of NH₃ that can form?',options:['0.30 mol','0.80 mol','1.30 mol','0.60 mol'],answer:3,explanation:'Hydrogen is limiting: 0.90 × 2/3 = 0.60 mol NH₃. Only 0.30 mol N₂ is needed.',why:['0.30 mol is the N₂ consumed by 0.90 mol H₂, not the NH₃ formed.','This assumes all 0.40 mol N₂ reacts, but there is insufficient hydrogen.','Adding the starting mole amounts does not determine product amount.','Hydrogen is limiting: 0.90 × 2/3 = 0.60 mol NH₃. Only 0.30 mol N₂ is needed.']},
 {id:'calcs-08',topic:'reactants',q:'A reaction has a theoretical product mass of 8.0 g. A student isolates 6.2 g. What is the percentage yield?',options:['129%','77.5%','1.8%','62.0%'],answer:1,explanation:'Percentage yield = 6.2 ÷ 8.0 × 100 = 77.5%.',why:['This reverses actual and theoretical yield.','Percentage yield = 6.2 ÷ 8.0 × 100 = 77.5%.','1.8 g is the shortfall in product mass, not the percentage yield.','The actual mass must be compared with 8.0 g, not with 10 g.']},
 {id:'equilibrium-07',topic:'equilibria',q:'A forward reaction is exothermic. Which change increases its equilibrium product yield?',options:['Adding a catalyst','Raising the temperature','Removing some reactant','Lowering the temperature'],answer:3,explanation:'Lower temperature favours the exothermic direction, increasing equilibrium product yield, although it may slow the reaction.',why:['A catalyst speeds attainment of equilibrium without changing its position.','Higher temperature favours the endothermic reverse reaction.','Removing a reactant favours the reverse direction to replace it.','Lower temperature favours the exothermic direction, increasing equilibrium product yield, although it may slow the reaction.']},
 {id:'enthalpy-07',topic:'energy',q:'A fuel heats 0.150 kg of water by 24 °C. Using c = 4.18 kJ kg⁻¹ °C⁻¹, what energy does the water gain?',options:['0.627 kJ','15.0 kJ','100 kJ','15000 kJ'],answer:1,explanation:'E = cmΔT = 4.18 × 0.150 × 24 = 15.048 kJ, approximately 15.0 kJ.',why:['This omits the temperature change.','E = cmΔT = 4.18 × 0.150 × 24 = 15.048 kJ, approximately 15.0 kJ.','This omits the water mass factor.','Use 0.150 kg, not 150, because the supplied specific heat capacity is per kilogram.']},
 {id:'enthalpy-08',topic:'energy',q:'For A → B, ΔH = +45 kJ mol⁻¹. For B → C, ΔH = −120 kJ mol⁻¹. What is ΔH for A → C?',options:['−75 kJ mol⁻¹','+75 kJ mol⁻¹','−165 kJ mol⁻¹','+165 kJ mol⁻¹'],answer:0,explanation:'The steps add directly: +45 + (−120) = −75 kJ mol⁻¹, by Hess’s law.',why:['The steps add directly: +45 + (−120) = −75 kJ mol⁻¹, by Hess’s law.','This reverses the sign of the net change.','The first step is endothermic (+45), not −45.','Adding magnitudes without their signs does not give the enthalpy change.']},
 {id:'enthalpy-09',topic:'energy',q:'For H₂(g) + Cl₂(g) → 2HCl(g), use bond enthalpies H–H = 436, Cl–Cl = 243 and H–Cl = 431 kJ mol⁻¹. What is the estimated reaction enthalpy?',options:['+183 kJ mol⁻¹','−248 kJ mol⁻¹','−183 kJ mol⁻¹','−862 kJ mol⁻¹'],answer:2,explanation:'Bonds broken: 436 + 243 = 679. Bonds formed: 2 × 431 = 862. ΔH = 679 − 862 = −183 kJ mol⁻¹.',why:['This reverses the sign: forming the product bonds releases more energy than breaking reactant bonds requires.','This results from counting only one product H–Cl bond and using the wrong sign.','Bonds broken: 436 + 243 = 679. Bonds formed: 2 × 431 = 862. ΔH = 679 − 862 = −183 kJ mol⁻¹.','−862 accounts for bond formation but omits the energy required to break reactant bonds.']},
 {id:'calcs-09',topic:'analysis',q:'25.0 cm³ of sodium hydroxide reacts exactly with 20.0 cm³ of 0.150 mol l⁻¹ hydrochloric acid. HCl + NaOH → NaCl + H₂O. What is the sodium hydroxide concentration?',options:['0.188 mol l⁻¹','0.00300 mol l⁻¹','0.0750 mol l⁻¹','0.120 mol l⁻¹'],answer:3,explanation:'n(HCl) = 0.150 × 0.0200 = 0.00300 mol = n(NaOH). c = 0.00300 ÷ 0.0250 = 0.120 mol l⁻¹.',why:['This reverses the volume ratio.','0.00300 mol is the reacting amount, not the concentration.','The equation gives a 1:1 ratio; there is no factor of two.','n(HCl) = 0.150 × 0.0200 = 0.00300 mol = n(NaOH). c = 0.00300 ÷ 0.0250 = 0.120 mol l⁻¹.']},
 {id:'analysis-07',topic:'analysis',q:'Under the same chromatographic conditions, a pure standard gives a peak at 4.6 minutes. A mixture gives peaks at 2.1, 4.6 and 7.8 minutes. Which conclusion is best supported?',options:['The mixture may contain the standard substance, based on matching retention time','The standard must make up exactly one third of the mixture','The mixture contains only one substance','The peak at 7.8 minutes must be the standard'],answer:0,explanation:'Matching retention time supports identification under the same conditions, although different substances can share a retention time.',why:['Matching retention time supports identification under the same conditions, although different substances can share a retention time.','The number of peaks does not determine the amount of each component; peak size and calibration matter.','Three separated peaks indicate at least three detected components in this simplified chromatogram.','The matching retention time is 4.6 minutes, not 7.8 minutes.']},
 // figures batch 2026-11-26: 3 organic questions with displayed-formula diagrams
 {id:'organic-16',topic:'alcohols',q:'Three alcohols, A, B and C, are shown. Which of them would be oxidised to a ketone by acidified potassium dichromate solution?',figure:{src:'img/higher-organic-16.svg',alt:'Three displayed formulae labelled A, B and C. A is a chain of four carbon atoms with an OH group on the end carbon. B is a chain of four carbon atoms with an OH group on the second carbon. C is a chain of three carbon atoms with both an OH group and a methyl group on the middle carbon.'},options:['A only','B only','C only','A and B'],answer:1,explanation:'Only a secondary alcohol is oxidised to a ketone. In B the carbon bonded to –OH is joined to two other carbon atoms. A is a primary alcohol, oxidised to an aldehyde and then a carboxylic acid, and C is a tertiary alcohol, which is not oxidised.'},
 {id:'organic-17',topic:'esters',q:'Which pair of compounds would react to form the ester shown?',figure:{src:'img/higher-organic-17.svg',alt:'Displayed formula of a molecule drawn as one chain: a carbon carrying three hydrogen atoms, then a carbon double-bonded to an oxygen atom, then a single-bonded oxygen atom, then a chain of three carbon atoms each carrying hydrogen atoms.'},options:['Ethanoic acid and propan-1-ol','Propanoic acid and ethanol','Ethanoic acid and propan-2-ol','Butanoic acid and methanol'],answer:0,explanation:'The carbon chain containing C=O comes from the carboxylic acid (two carbons, so ethanoic acid). The chain on the single-bonded oxygen comes from the alcohol (a straight chain of three carbons joined at its end, so propan-1-ol). The other pairs would give isomeric esters.'},
 {id:'organic-18',topic:'systematic',q:'What is the systematic name of the compound shown?',figure:{src:'img/higher-organic-18.svg',alt:'Displayed formula: a chain of four carbon atoms with a double bond between the second and third carbon atoms and a one-carbon methyl branch on the second carbon. All other bonds are single bonds.'},options:['2-methylbut-2-ene','3-methylbut-2-ene','2-methylbut-3-ene','2-methylpent-2-ene'],answer:0,explanation:'The longest chain containing the double bond has four carbons (butene). The double bond starts at carbon 2 whichever end you number from, so the methyl group decides the direction: numbering so that it is on carbon 2 gives 2-methylbut-2-ene.'},
 // batch Gemini 2026-11-27 (10 questions)
 {"id":"acids-c-01","topic":"acids-c","q":"Which statement best describes what happens when ethanoic acid is added to excess sodium carbonate solution?","options":["A carboxylate salt, water and carbon dioxide are formed","A neutral salt is formed and hydrogen gas is given off","An ester is formed and water is the only other product","Ethanoic acid is oxidised to ethanal with no gas evolved"],"answer":0,"explanation":"Carboxylic acids react with carbonates to produce a salt (sodium ethanoate), water and carbon dioxide gas. Acids reacting with reactive metals form hydrogen, not carbonates."},
 {"id":"acids-c-02","topic":"acids-c","q":"Why does methanoic acid have a higher boiling point than propane of similar gram formula mass?","options":["Methanoic acid has stronger covalent bonds within each molecule","Methanoic acid molecules form giant covalent lattices","Hydrogen bonding exists between methanoic acid molecules","Dispersion forces are weaker between propane molecules because they are polar"],"answer":2,"explanation":"The –COOH group contains an –O–H bond, allowing strong hydrogen bonds between methanoic acid molecules in addition to London dispersion forces, which requires more energy to overcome than the dispersion forces in propane."},
 {"id":"acids-c-03","topic":"acids-c","q":"What is formed when propanoic acid reacts with magnesium ribbon?","options":["Magnesium propanoate and hydrogen gas","Magnesium propanoate and water only","Propan-1-ol and magnesium oxide","Magnesium propanoate and carbon dioxide gas"],"answer":0,"explanation":"A carboxylic acid reacts with a reactive metal such as magnesium to produce a carboxylate salt (magnesium propanoate) and hydrogen gas."},
 {"id":"soaps-01","topic":"soaps","q":"A soap molecule has a long hydrocarbon tail and an ionic carboxylate head (–COO⁻Na⁺). How do these parts behave with grease and water?","options":["The head is hydrophobic and dissolves in grease; the tail is hydrophilic and dissolves in water","Both the head and the tail are ionic and dissolve only in water","The tail is hydrophobic and dissolves in grease; the head is hydrophilic and interacts with water","Both the head and the tail are non-polar and dissolve only in oil"],"answer":2,"explanation":"The non-polar hydrocarbon chain is hydrophobic (attracted to non-polar grease/oil), while the negatively charged –COO⁻ head is hydrophilic and attracted to polar water molecules."},
 {"id":"soaps-02","topic":"soaps","q":"What happens when soap is added to hard water containing dissolved Ca²⁺ or Mg²⁺ ions?","options":["The soap reacts with the metal ions to form an insoluble precipitate called scum","The soap forms more lather than in soft water","The metal ions hydrolyse the soap into glycerol and fatty acids","The boiling point of the water drops below 100 °C"],"answer":0,"explanation":"Carboxylate ions from soap form an insoluble solid (scum) with Ca²⁺ and Mg²⁺ ions in hard water, reducing the amount of soap available to form lather."},
 {"id":"oxfood-01","topic":"oxfood","q":"Why can leaving cut apple slices exposed to air cause them to turn brown over time?","options":["Water evaporates leaving behind solid starch crystals","Sugars undergo thermal decomposition at room temperature","Enzymes catalyse oxidation reactions involving oxygen from the air","Atmospheric nitrogen reduces the fruit acids to alcohols"],"answer":2,"explanation":"Exposure to oxygen allows oxidation reactions (often enzyme-catalysed in fresh fruit) that produce coloured compounds."},
 {"id":"fragrances-01","topic":"fragrances","q":"Many fragrance compounds such as terpenes in essential oils are volatile. What does being volatile mean for a substance?","options":["It evaporates easily at room temperature because of relatively weak intermolecular forces","It is chemically unstable and explodes on warming","It is an ionic solid with a very high melting point","It is completely insoluble in organic solvents"],"answer":0,"explanation":"Volatile substances have a low boiling point and evaporate readily at room temperature, allowing vapour molecules to reach the nose."},
 {"id":"skin-01","topic":"skin","q":"How do free radical scavengers (antioxidants) in skin-care products help protect against UV damage?","options":["They reflect all visible light away from the skin","They convert UV radiation into nuclear energy","They react with free radicals to form stable, non-radical species and stop chain reactions","They permanently block sweat glands"],"answer":2,"explanation":"Free radical scavengers donate an electron or hydrogen atom to unpaired free radicals, quenching them and preventing further radical chain reactions."},
 {"id":"techniques-01","topic":"techniques","q":"Why is a reaction mixture sometimes heated under reflux rather than in an open beaker?","options":["To allow volatile liquids to vaporise, condense and return to the flask without losing reactants or products","To increase the pressure inside the flask to ten atmospheres","To cool the mixture below 0 °C","To separate two immiscible liquids by distillation"],"answer":0,"explanation":"Refluxing heats a mixture continuously while a condenser returns escaping vapours as liquid, preventing loss of volatile substances."},
 {"id":"reporting-01","topic":"reporting","q":"In a titration experiment, a student obtains concordant titre volumes of 24.20 cm³, 24.15 cm³ and 24.25 cm³. Which value should be used in the subsequent calculation?","options":["24.15 cm³, because it is the smallest volume measured","24.25 cm³, because it is the largest volume measured","24.20 cm³, which is the mean of the three concordant titres","72.60 cm³, which is the sum of the three titres"],"answer":2,"explanation":"Concordant titres agree closely with each other, so taking their mean (24.20 cm³) gives the best representative volume for stoichiometric calculations."},
 // batch SQA additions b01 (90 questions)
 {"id":"higher-expand-b01-001","topic":"periodicity","q":"Removing an electron from gaseous X⁺ to form gaseous X²⁺ represents which quantity?","options":["The second ionisation energy of X","The first ionisation energy of X","The electron affinity of X","The energy released when X forms an anion"],"answer":0,"explanation":"The first electron has already been removed in X⁺. Removing the next electron is the second ionisation, and the gaseous state is part of the definition."},
 {"id":"higher-expand-b01-002","topic":"periodicity","q":"Why does a magnesium atom have a smaller covalent radius than a sodium atom in the same period?","options":["It has fewer occupied shells","Its greater nuclear charge attracts electrons in the same outer shell more strongly","Its nucleus has a smaller positive charge","It has no inner electrons to provide shielding"],"answer":1,"explanation":"Across this part of the period, electrons enter the same outer shell while nuclear charge increases. The stronger effective attraction draws the outer electrons closer."},
 {"id":"higher-expand-b01-003","topic":"periodicity","q":"Which comparison best explains the stronger attraction for a bonding pair in chlorine than in sulfur?","options":["Chlorine has fewer occupied shells than sulfur","Sulfur is a noble gas","Chlorine has a greater effective nuclear attraction within the same period","Chlorine has no electron shielding"],"answer":2,"explanation":"Sulfur and chlorine are in the same period. The increased nuclear charge across the period gives chlorine a stronger attraction for a shared bonding pair and higher electronegativity."},
 {"id":"higher-expand-b01-004","topic":"structure","q":"Electronegativities are H 2.2, C 2.6, O 3.4 and F 4.0. Which listed bond has the smallest electronegativity difference?","options":["O–H","F–H","C–F","C–H"],"answer":3,"explanation":"The differences are 0.4, 1.2, 1.8 and 1.4 respectively. C–H has the smallest difference and is the least polar of these bonds."},
 {"id":"higher-expand-b01-005","topic":"structure","q":"In a polar H–Cl bond, where is the partial negative charge?","options":["On chlorine, because the shared electrons are attracted more strongly towards it","On hydrogen, because hydrogen has fewer electrons overall","Equally on both atoms because the bond is covalent","On neither atom because all molecules must be ions"],"answer":0,"explanation":"Chlorine is more electronegative than hydrogen. It attracts the shared electrons more strongly, producing δ− on Cl and δ+ on H without complete electron transfer."},
 {"id":"higher-expand-b01-006","topic":"periodicity","q":"A student explains a Group 1 ionisation-energy decrease by saying only “the atom has more protons”. What is missing?","options":["A claim that proton charge becomes negative down the group","The greater outer-electron distance and shielding that outweigh increased nuclear charge","The idea that all electrons occupy the first shell","A claim that inner electrons stop repelling outer electrons"],"answer":1,"explanation":"More protons alone would increase attraction. Down Group 1, the additional occupied shell increases distance and shielding sufficiently to make the outer electron easier to remove."},
 {"id":"higher-expand-b01-007","topic":"periodicity","q":"Which comparison correctly describes a cation and the neutral atom that formed it by electron loss?","options":["The cation has fewer protons but the same electron count","The cation has more occupied shells in every case","The cation has fewer electrons but the same nuclear charge","The cation has a different atomic number"],"answer":2,"explanation":"Ion formation by electron loss changes the electron count, not the nucleus. The number of protons and therefore the element’s identity remain unchanged."},
 {"id":"higher-expand-b01-008","topic":"structure","q":"What is required to justify a permanent dipole in a molecule?","options":["At least one lone pair on any atom, regardless of symmetry","A large number of carbon atoms","An ionic lattice containing both charges","Polar bonds arranged so that their dipoles do not cancel"],"answer":3,"explanation":"Bond polarity alone is insufficient. Molecular geometry determines whether individual bond dipoles cancel or produce a net dipole."},
 {"id":"higher-expand-b01-009","topic":"structure","q":"Both CH₄ and CCl₄ are non-polar. Why does CCl₄ have stronger London dispersion forces?","options":["Its larger electron cloud is more easily polarised","It forms hydrogen bonds through chlorine","Every C–Cl bond is an ionic bond","It contains a permanent overall molecular dipole"],"answer":0,"explanation":"The larger, more polarisable electron cloud produces stronger temporary and induced dipoles. This increases London forces even though molecular symmetry cancels the bond dipoles."},
 {"id":"higher-expand-b01-010","topic":"periodicity","q":"An unknown element shows successive ionisation energies with a very large increase between the third and fourth removals. What is the best main-group interpretation?","options":["It has four occupied shells","It has three outer-shell electrons","It must have atomic number 4","It forms a 4− ion most readily"],"answer":1,"explanation":"After three outer electrons are removed, the fourth is taken from a more strongly bound inner shell. The jump therefore supports three valence electrons, not four shells."},
 {"id":"higher-expand-b01-011","topic":"structure","q":"Which attraction is overcome when liquid nitrogen boils?","options":["The N≡N covalent bonds in every molecule","Ionic bonds between N³⁻ ions","London dispersion forces between N₂ molecules","Metallic bonds between nitrogen atoms"],"answer":2,"explanation":"Boiling separates nitrogen molecules without splitting them into atoms. N₂ is non-polar, so London forces are the relevant intermolecular attractions."},
 {"id":"higher-expand-b01-012","topic":"structure","q":"A liquid dissolves iodine but does not mix with water. What does this suggest about the liquid?","options":["It must contain free-moving ions","It must form stronger hydrogen bonds than water","It is necessarily an element","It is likely to be largely non-polar"],"answer":3,"explanation":"Non-polar solvents interact favourably with iodine through dispersion forces and often mix poorly with polar water. Solubility gives evidence, not a unique molecular identity."},
 {"id":"higher-expand-b01-013","topic":"structure","q":"Which pure liquid can donate and accept hydrogen bonds between its molecules?","options":["CH₃CH₂CH₂OH","CH₃OCH₂CH₃","CH₃CH₂CH₃","CCl₄"],"answer":0,"explanation":"Propan-1-ol contains O–H, allowing hydrogen-bond donation, and oxygen lone pairs for acceptance. An ether can accept hydrogen bonds from water but cannot donate them to its own molecules."},
 {"id":"higher-expand-b01-014","topic":"structure","q":"Why do large non-polar molecules sometimes boil above small hydrogen-bonded molecules?","options":["Non-polar molecules always have ionic bonds","Their many electrons can produce very strong cumulative London forces","Hydrogen bonding only exists in solids","Their covalent bonds must be broken during boiling"],"answer":1,"explanation":"Intermolecular-force comparisons must consider molecular size as well as force type. Strong cumulative dispersion attractions in a large molecule can outweigh hydrogen bonding in a smaller one."},
 {"id":"higher-expand-b01-015","topic":"structure","q":"A solid dissolves in water to form a conducting solution but does not conduct as a solid. Which particles carry charge in the solution?","options":["Neutral solvent molecules only","Protons inside the nuclei of the solute","Mobile positive and negative ions","Covalent bonds moving intact through the wire"],"answer":2,"explanation":"Dissolution releases ions that can move under an electric field. In the solid lattice they are fixed, so they cannot transport charge through the material."},
 {"id":"higher-expand-b01-016","topic":"structure","q":"Why does silicon have a much higher melting point than molecular phosphorus?","options":["Phosphorus contains no covalent bonds","Silicon atoms form hydrogen bonds","Phosphorus is a metal with mobile electrons","Melting silicon disrupts a covalent network rather than only separating molecules"],"answer":3,"explanation":"Silicon has a three-dimensional covalent network. Phosphorus has separate P₄ molecules; melting mainly overcomes weaker forces between these molecules."},
 {"id":"higher-expand-b01-017","topic":"structure","q":"Ethanol mixes with water because of which additional attraction between the two substances?","options":["Hydrogen bonding involving their OH groups and oxygen lone pairs","Metallic attraction between carbon atoms","Ionic attraction between ethanol cations and water anions","Formation of permanent new C–O covalent bonds in every molecule"],"answer":0,"explanation":"Ethanol and water can form hydrogen bonds with each other. Mixing does not require them all to react into a new compound."},
 {"id":"higher-expand-b01-018","topic":"structure","q":"Which description best distinguishes covalent bonds from intermolecular forces in a sample of liquid bromine?","options":["Both terms refer only to attractions inside the Br nucleus","Covalent bonds hold Br atoms together within Br₂; intermolecular forces act between Br₂ molecules","Intermolecular forces hold each Br₂ molecule together and covalent bonds act between molecules","Liquid bromine contains only ionic bonds"],"answer":1,"explanation":"The Br–Br bond joins two atoms in a molecule. London dispersion forces attract one molecule to another and are the main attractions overcome during boiling."},
 {"id":"higher-expand-b01-019","topic":"structure","q":"For molecules of similar size, which pair most clearly adds permanent-dipole interactions to London forces?","options":["Propane molecules","Nitrogen molecules","Propanone molecules","Methane molecules"],"answer":2,"explanation":"Propanone has a polar carbonyl group and a net dipole, so both permanent-dipole and London attractions operate. The other listed molecules are non-polar."},
 {"id":"higher-expand-b01-020","topic":"structure","q":"A student claims that the higher boiling point of hexane than pentane means its C–C bonds are stronger. What is the best correction?","options":["All covalent bonds break when an alkane boils","Pentane has hydrogen bonds but hexane does not","Hexane is an ionic solid","The difference mainly reflects stronger intermolecular London forces in the larger molecules"],"answer":3,"explanation":"Boiling changes physical state and normally leaves the alkane molecules intact. Hexane’s larger electron cloud gives stronger London attractions than pentane’s."},
 {"id":"higher-expand-b01-021","topic":"rate","q":"Products lie 35 kJ mol⁻¹ below reactants and the transition state lies 65 kJ mol⁻¹ above reactants. What is the reverse activation energy?","options":["100 kJ mol⁻¹","30 kJ mol⁻¹","65 kJ mol⁻¹","−100 kJ mol⁻¹"],"answer":0,"explanation":"The reverse reaction starts at the lower product level and climbs to the same peak. Ea(reverse) = 65 + 35 = 100 kJ mol⁻¹."},
 {"id":"higher-expand-b01-022","topic":"rate","q":"A reaction has Ea = 82 kJ mol⁻¹. A catalyst lowers it to 54 kJ mol⁻¹. Which other quantity is unchanged at the same temperature?","options":["The fraction of collisions able to follow the catalysed route","The reaction enthalpy change","The initial rate in a reacting mixture","The energy barrier of the available pathway"],"answer":1,"explanation":"A catalyst changes the route and activation barrier, not reactant or product energy levels. Therefore ΔH remains unchanged, although the rate usually increases."},
 {"id":"higher-expand-b01-023","topic":"rate","q":"What does the area beyond the activation-energy threshold on a molecular energy distribution represent?","options":["The activation energy multiplied by time","Only particles that have already become products","The fraction or number of particles energetic enough to react, depending on the vertical scale","The total energy stored in covalent bonds"],"answer":2,"explanation":"Particles to the high-energy side of Ea have enough energy for reaction if they collide appropriately. The area does not mean every such particle reacts immediately."},
 {"id":"higher-expand-b01-024","topic":"rate","q":"At constant temperature, adding a catalyst to a gas reaction changes which feature of an energy-distribution diagram?","options":["The whole distribution shifts to higher energy","The total number of particles must double","The peak becomes the enthalpy of reaction","The relevant activation-energy threshold moves to lower energy"],"answer":3,"explanation":"At unchanged temperature, the particles’ energy distribution stays the same. The catalyst provides a lower threshold, increasing the fraction that can react."},
 {"id":"higher-expand-b01-025","topic":"rate","q":"Gas volumes increase from 24 to 66 cm³ between 12 and 40 s. What is the average rate over that interval?","options":["1.5 cm³ s⁻¹","1.05 cm³ s⁻¹","2.36 cm³ s⁻¹","3.5 cm³ s⁻¹"],"answer":0,"explanation":"Average rate = Δvolume/Δtime = (66 − 24)/(40 − 12) = 42/28 = 1.5 cm³ s⁻¹. Use both differences rather than either total."},
 {"id":"higher-expand-b01-026","topic":"rate","q":"A rate experiment times how long it takes a cross to disappear. What must be controlled when comparing 1/time values?","options":["The exact clock time of day only","The amount of cloudiness required to hide the cross","The final mass of the stopwatch","The colour of the laboratory walls only"],"answer":1,"explanation":"The same visible end-point must represent the same reaction progress. Changing solution depth or the visibility of the cross could change the timing without a genuine rate change."},
 {"id":"higher-expand-b01-027","topic":"rate","q":"In a proposed cycle, Co²⁺ is consumed in one stage and regenerated in the next. What role can it have overall?","options":["Limiting reactant that is permanently used up","Final product only","Catalyst","Solvent that cannot react at any stage"],"answer":2,"explanation":"A catalyst can participate in individual steps but is regenerated overall. Cancelling it from the combined equation shows it is not consumed by the net reaction."},
 {"id":"higher-expand-b01-028","topic":"rate","q":"Why does a temperature rise often increase rate more than collision frequency alone would predict?","options":["Temperature removes the need for collisions","Every molecule acquires exactly the activation energy","The reaction enthalpy becomes zero","The fraction of particles with energy at least Ea increases significantly"],"answer":3,"explanation":"Heating changes the distribution of particle energies. The larger high-energy fraction increases the proportion of successful collisions as well as slightly increasing collision frequency."},
 {"id":"higher-expand-b01-029","topic":"rate","q":"A catalysed and uncatalysed run use identical reactant amounts. Which comparison is normally expected when both go to completion?","options":["Different times but the same theoretical final product amount","Different final product amounts because the catalyst supplies atoms","Identical times because ΔH is identical","No products in the uncatalysed run under any conditions"],"answer":0,"explanation":"The catalyst affects how quickly conversion occurs, not the stoichiometric amount available from the reactants. It may make a slow reaction practical without creating extra product atoms."},
 {"id":"higher-expand-b01-030","topic":"rate","q":"How is the instantaneous rate at a particular time found from a gas-volume versus time graph?","options":["Divide every recorded volume by the final time","Find the gradient of a tangent at that time","Use only the final gas volume","Read the height of the curve without considering time"],"answer":1,"explanation":"A tangent shows the local slope at the chosen time. Its gradient, change in volume divided by change in time along the tangent, estimates the instantaneous rate."},
 {"id":"higher-expand-b01-031","topic":"energy","q":"For A → B, ΔH = −72 kJ mol⁻¹. What is ΔH for 3B → 3A?","options":["−216 kJ mol⁻¹","+24 kJ mol⁻¹","+216 kJ mol⁻¹","−72 kJ mol⁻¹"],"answer":2,"explanation":"Reverse the reaction to change −72 to +72, then multiply the whole equation by three: 3 × 72 = +216 kJ mol⁻¹ for the equation as written."},
 {"id":"higher-expand-b01-032","topic":"energy","q":"A fuel sample of 0.0200 mol heats 0.250 kg water by 12.0 °C. Ignoring heat loss, what is its molar enthalpy of combustion? c = 4.18 kJ kg⁻¹ °C⁻¹.","options":["+627 kJ mol⁻¹","−12.54 kJ mol⁻¹","−0.2508 kJ mol⁻¹","−627 kJ mol⁻¹"],"answer":3,"explanation":"Water gains E = 4.18 × 0.250 × 12.0 = 12.54 kJ. Combustion releases this energy, so ΔH = −12.54/0.0200 = −627 kJ mol⁻¹."},
 {"id":"higher-expand-b01-033","topic":"energy","q":"A process breaks bonds needing 950 kJ and forms bonds releasing 1120 kJ. What is ΔH for that process?","options":["−170 kJ","+170 kJ","−2.07 × 10³ kJ","+2.07 × 10³ kJ"],"answer":0,"explanation":"ΔH = energy absorbed in breaking − energy released in forming = 950 − 1120 = −170 kJ. The negative result means net energy release."},
 {"id":"higher-expand-b01-034","topic":"energy","q":"Given A → C has ΔH = −140 kJ mol⁻¹ and B → C has ΔH = −55 kJ mol⁻¹, what is ΔH for A → B?","options":["−195 kJ mol⁻¹","−85 kJ mol⁻¹","+85 kJ mol⁻¹","+195 kJ mol⁻¹"],"answer":1,"explanation":"Combine A → C with the reverse C → B. The sum is −140 + 55 = −85 kJ mol⁻¹; reversing the second reaction changes its sign."},
 {"id":"higher-expand-b01-035","topic":"energy","q":"Ethene is hydrogenated: C₂H₄ + H₂ → C₂H₆. Use C=C = 614, H–H = 436, C–C = 346 and C–H = 412 kJ mol⁻¹. What is the estimated ΔH?","options":["+120 kJ mol⁻¹","−532 kJ mol⁻¹","−120 kJ mol⁻¹","+1050 kJ mol⁻¹"],"answer":2,"explanation":"Unchanged C–H bonds cancel. Break C=C and H–H; form C–C and two extra C–H. ΔH = 614 + 436 − 346 − 2 × 412 = −120 kJ mol⁻¹."},
 {"id":"higher-expand-b01-036","topic":"energy","q":"Why can a value calculated from mean bond enthalpies differ from an accurately measured reaction enthalpy?","options":["Mean bond enthalpies include only ionic solids","Measured enthalpies never obey conservation of energy","Bond formation is actually endothermic","Mean values average a bond across different gaseous molecular environments"],"answer":3,"explanation":"A particular bond’s energy depends on its molecular environment. Mean bond enthalpies are averaged values and also refer to gaseous species, so exact agreement is not guaranteed."},
 {"id":"higher-expand-b01-037","topic":"energy","q":"A calorimeter records only part of the heat released by complete combustion. How does this affect the calculated negative ΔH?","options":["It becomes less negative than the true value","It becomes more negative than the true value","It must become exactly zero","It changes the balanced equation"],"answer":0,"explanation":"Underestimating the transferred heat underestimates the magnitude of energy released per mole. For an exothermic reaction, this places the calculated ΔH closer to zero."},
 {"id":"higher-expand-b01-038","topic":"energy","q":"A reaction releases 18.0 kJ when 0.150 mol product forms. For an equation forming 2 mol product, what is the corresponding energy change?","options":["−120 kJ","−240 kJ","+240 kJ","−36.0 kJ"],"answer":1,"explanation":"Energy per mole of product is −18.0/0.150 = −120 kJ. The equation forms two moles, so its energy change is −240 kJ."},
 {"id":"higher-expand-b01-039","topic":"energy","q":"Which process correctly defines bond breaking for a gaseous diatomic molecule X₂?","options":["2X(g) → X₂(g)","X₂(l) → X₂(g)","X₂(g) → 2X(g)","X₂(s) → X₂(l)"],"answer":2,"explanation":"Bond breaking separates gaseous molecules into gaseous atoms and absorbs energy. Vaporisation and melting change physical state without necessarily breaking the intramolecular bond."},
 {"id":"higher-expand-b01-040","topic":"energy","q":"A reaction has reactant energy 140 and product energy 195 kJ on the same scale. What is its enthalpy change?","options":["−55 kJ","+335 kJ","−335 kJ","+55 kJ"],"answer":3,"explanation":"ΔH = product energy − reactant energy = 195 − 140 = +55 kJ. The absolute zero of the scale is irrelevant; only the difference matters."},
 {"id":"higher-expand-b01-041","topic":"equilibria","q":"For PCl₅(g) ⇌ PCl₃(g) + Cl₂(g), what happens to equilibrium composition if the volume is decreased at constant temperature?","options":["More PCl₅ forms","More PCl₃ and Cl₂ form","Only the catalyst concentration changes","All gas concentrations must become zero"],"answer":0,"explanation":"Decreasing volume increases pressure. The equilibrium shifts towards one gaseous molecule on the left rather than two on the right, favouring PCl₅."},
 {"id":"higher-expand-b01-042","topic":"equilibria","q":"For H₂(g) + I₂(g) ⇌ 2HI(g), what is the equilibrium yield effect of increasing pressure at constant temperature in an ideal-gas model?","options":["More HI always forms","No shift, because both sides contain equal gas mole totals","Only iodine forms","The reaction becomes irreversible"],"answer":1,"explanation":"Both sides contain two gas moles, so compression does not favour either side. Rates may change, but equal gas totals mean no pressure-induced equilibrium shift here."},
 {"id":"higher-expand-b01-043","topic":"equilibria","q":"For A(g) ⇌ 2B(g), the forward reaction is endothermic. Which pair of changes both favour a larger equilibrium fraction of B?","options":["Lower temperature and higher pressure","Higher temperature and higher pressure","Higher temperature and lower pressure","Lower temperature and unchanged pressure"],"answer":2,"explanation":"Heating favours the endothermic forward direction. Lower pressure favours the side with more gas molecules, which is the two B molecules on the right."},
 {"id":"higher-expand-b01-044","topic":"equilibria","q":"In a sealed vessel at equilibrium, forward reaction rate is 0.004 mol l⁻¹ s⁻¹. What is the reverse rate?","options":["Zero","0.008 mol l⁻¹ s⁻¹","It cannot be equal unless concentrations are equal","0.004 mol l⁻¹ s⁻¹"],"answer":3,"explanation":"Dynamic equilibrium requires equal forward and reverse reaction rates. It does not require equal concentrations of the substances involved."},
 {"id":"higher-expand-b01-045","topic":"equilibria","q":"For A(aq) + B(aq) ⇌ C(aq), extra B is added at constant temperature and volume. What happens initially?","options":["The forward rate increases and the mixture moves towards more C","The reverse rate must instantly become zero","The forward reaction stops","The catalyst becomes a reactant"],"answer":0,"explanation":"Increasing B raises the forward reaction rate initially while the product amount has not yet changed. Net conversion towards C continues until the rates become equal again."},
 {"id":"higher-expand-b01-046","topic":"equilibria","q":"A product is continuously removed from a reversible industrial reaction. Why can this improve conversion of reactants?","options":["Removal increases the product concentration in the vessel","Removing product reduces the reverse reaction rate and favours further product formation","Removal changes the atoms in the balanced equation","Removal guarantees the catalyst is consumed"],"answer":1,"explanation":"Lower product concentration reduces the reverse rate initially. The imbalance allows further forward reaction, improving overall conversion as product is removed."},
 {"id":"higher-expand-b01-047","topic":"equilibria","q":"Why can a moderate temperature be chosen for an exothermic industrial equilibrium?","options":["The highest temperature always gives both the best yield and fastest rate","It prevents any reverse reaction","It balances a useful reaction rate against a higher yield favoured at lower temperature","It makes activation energy equal to zero"],"answer":2,"explanation":"Cooling favours exothermic product formation but can make the reaction too slow. Industrial conditions balance production rate, equilibrium yield and cost."},
 {"id":"higher-expand-b01-048","topic":"equilibria","q":"A catalyst is added to a mixture already at equilibrium with temperature fixed. What is true once its action is established?","options":["Only the forward rate increases permanently","The product concentration doubles automatically","The equilibrium disappears","Both opposing rates can increase while composition remains unchanged"],"answer":3,"explanation":"A catalyst accelerates both directions. Since the opposing rates remain equal at the same equilibrium composition, there is no net conversion caused by the catalyst alone."},
 {"id":"higher-expand-b01-049","topic":"equilibria","q":"For 2NO₂(g) ⇌ N₂O₄(g), cooling makes a brown mixture paler. What does this show about N₂O₄ formation?","options":["It is exothermic","It is necessarily endothermic","It involves no energy change","It creates more brown NO₂"],"answer":0,"explanation":"The brown colour comes from NO₂. Cooling favours more pale N₂O₄, so the forward process is the heat-releasing, exothermic direction."},
 {"id":"higher-expand-b01-050","topic":"equilibria","q":"Why is a closed system needed to establish a gas-phase dynamic equilibrium in a vessel?","options":["Gas particles must stop moving","Reactants and products must not continually escape from the system","All particles must have the same kinetic energy","The forward reaction must occur without a reverse reaction"],"answer":1,"explanation":"Retaining the reacting substances allows both directions to continue and balance. Escaping gas can prevent the required equilibrium composition being maintained."},
 {"id":"higher-expand-b01-051","topic":"redox","q":"In 2Fe³⁺ + Sn²⁺ → 2Fe²⁺ + Sn⁴⁺, which species is the reducing agent?","options":["Fe³⁺","Fe²⁺ only","Sn²⁺","Sn⁴⁺ only"],"answer":2,"explanation":"Sn²⁺ loses two electrons to become Sn⁴⁺. The electron donor causes reduction of Fe³⁺, so it is the reducing agent and is itself oxidised."},
 {"id":"higher-expand-b01-052","topic":"redox","q":"Which ion-electron equation conserves charge when sulfite is oxidised to sulfate in acid?","options":["SO₃²⁻ → SO₄²⁻ + 2e⁻","SO₃²⁻ + 2e⁻ → SO₄²⁻","SO₃²⁻ + H₂O → SO₄²⁻ + 2H⁺","SO₃²⁻ + H₂O → SO₄²⁻ + 2H⁺ + 2e⁻"],"answer":3,"explanation":"Balance oxygen with water and hydrogen with H⁺, then balance charge with two electrons on the right. Both sides have overall charge −2."},
 {"id":"higher-expand-b01-053","topic":"redox","q":"How many moles of electrons are released when 0.040 mol Al forms Al³⁺?","options":["0.120 mol","0.040 mol","0.0133 mol","0.080 mol"],"answer":0,"explanation":"Al → Al³⁺ + 3e⁻ shows three moles of electrons per mole of aluminium. Therefore 0.040 × 3 = 0.120 mol electrons are released."},
 {"id":"higher-expand-b01-054","topic":"alcohols","q":"Which change is reduction of an organic compound?","options":["A primary alcohol becomes a carboxylic acid","An aldehyde becomes a primary alcohol","A secondary alcohol becomes a ketone","Aldehyde molecules gain oxygen to form acid"],"answer":1,"explanation":"Reduction can involve hydrogen gain or oxygen loss. Converting RCHO to RCH₂OH adds hydrogen and gives a primary alcohol; the other listed changes are oxidation."},
 {"id":"higher-expand-b01-055","topic":"redox","q":"I₂ reacts with thiosulfate: I₂ + 2S₂O₃²⁻ → 2I⁻ + S₄O₆²⁻. How many moles of I₂ react with 0.0060 mol thiosulfate?","options":["0.0120 mol","0.0060 mol","0.0030 mol","0.0015 mol"],"answer":2,"explanation":"The iodine:thiosulfate mole ratio is 1:2. Divide the thiosulfate amount by two: n(I₂) = 0.0060/2 = 0.0030 mol."},
 {"id":"higher-expand-b01-056","topic":"redox","q":"Which equation shows oxidation of chloride ions at an electrode?","options":["Cl₂ + 2e⁻ → 2Cl⁻","Cl⁻ + e⁻ → Cl²⁻","2Cl⁻ + 2H⁺ → 2HCl","2Cl⁻ → Cl₂ + 2e⁻"],"answer":3,"explanation":"Chloride ions lose electrons to form neutral chlorine molecules. Oxidation has electrons on the product side, and both atoms and total charge balance."},
 {"id":"higher-expand-b01-057","topic":"oxfood","q":"An antioxidant protects another substance by which action?","options":["It is oxidised preferentially, donating electrons","It is reduced while forcing the protected substance to oxidise faster","It removes all covalent bonds in the food","It acts only by freezing water"],"answer":0,"explanation":"An antioxidant reacts with oxidising species before important molecules do. It can donate electrons and is itself oxidised in protecting the other substance."},
 {"id":"higher-expand-b01-058","topic":"redox","q":"Permanganate requires five electrons per MnO₄⁻ reduced in acid; oxalate releases two per C₂O₄²⁻. What ratio MnO₄⁻:C₂O₄²⁻ balances electron transfer?","options":["5:2","2:5","1:1","1:5"],"answer":1,"explanation":"The least common multiple of five and two is ten electrons. Two permanganate ions accept ten while five oxalate ions release ten, giving ratio 2:5."},
 {"id":"higher-expand-b01-059","topic":"redox","q":"What happens to Fe²⁺ when it changes to Fe³⁺?","options":["It gains one proton","It gains one electron","It loses one electron","It loses one neutron"],"answer":2,"explanation":"The charge increases from +2 to +3 through loss of one electron. Redox chemistry does not require changing the nucleus."},
 {"id":"higher-expand-b01-060","topic":"redox","q":"A metal M reacts as M + 2Ag⁺ → M²⁺ + 2Ag. If 0.015 mol M reacts completely, how much silver forms?","options":["0.0075 mol","0.015 mol","0.045 mol","0.030 mol"],"answer":3,"explanation":"One mole of M releases two moles of electrons and reduces two moles of Ag⁺. Thus 0.015 mol M produces 2 × 0.015 = 0.030 mol Ag."},
 {"id":"higher-expand-b01-061","topic":"alcohols","q":"Which product forms when hexan-3-ol is oxidised under ordinary alcohol-oxidation conditions?","options":["Hexan-3-one","Hexanoic acid","Hexanal","Hex-3-ene"],"answer":0,"explanation":"The OH-bearing carbon in hexan-3-ol is attached to two other carbons, so it is a secondary alcohol. Oxidation gives the ketone with C=O at carbon 3."},
 {"id":"higher-expand-b01-062","topic":"alcohols","q":"Which alcohol is tertiary?","options":["Butan-1-ol","2-methylbutan-2-ol","Butan-2-ol","2-methylpropan-1-ol"],"answer":1,"explanation":"In 2-methylbutan-2-ol, the OH-bearing carbon is bonded to three carbon groups. The classification depends on that carbon’s neighbours, not the total number of carbons."},
 {"id":"higher-expand-b01-063","topic":"esters","q":"Hydrolysis of propyl ethanoate with water gives which pair?","options":["Ethanol and propanoic acid","Propene and carbon dioxide","Propan-1-ol and ethanoic acid","Propanone and methanol"],"answer":2,"explanation":"The alkyl part of the ester name identifies the alcohol, propan-1-ol. The ethanoate part identifies ethanoic acid. Hydrolysis splits the ester link by adding water."},
 {"id":"higher-expand-b01-064","topic":"proteins","q":"Four amino acids form one straight-chain tetrapeptide. How many water molecules are eliminated?","options":["4","2","8","3"],"answer":3,"explanation":"A chain of four amino acids needs three peptide links. Each link forms by condensation with loss of one H₂O, so three water molecules are released."},
 {"id":"higher-expand-b01-065","topic":"proteins","q":"Why can heating a protein destroy its biological activity without hydrolysing its peptide links?","options":["It changes interactions responsible for the protein’s three-dimensional shape","It necessarily removes every nitrogen atom","It converts every peptide link into a metallic bond","It always breaks the chain into free amino acids"],"answer":0,"explanation":"Denaturation disrupts interactions stabilising the folded structure, altering active or binding sites. Hydrolysis of peptide links is a separate process that breaks the chain itself."},
 {"id":"higher-expand-b01-066","topic":"soaps","q":"Which part of a soap ion associates most strongly with a grease droplet?","options":["The charged carboxylate head only","The non-polar hydrocarbon tail","The sodium counter-ion only","A free proton that soap always releases"],"answer":1,"explanation":"The hydrocarbon tail has favourable non-polar interactions with grease. The charged hydrophilic head interacts with water, helping disperse the grease in droplets."},
 {"id":"higher-expand-b01-067","topic":"fragrances","q":"A terpene hydrocarbon contains four isoprene units. What molecular formula corresponds to their combined composition?","options":["C₂₀H₄₀","C₁₆H₂₀","C₂₀H₃₂","C₄H₈"],"answer":2,"explanation":"One isoprene unit has composition C₅H₈. Four units give C₂₀H₃₂; do not apply the alkane formula to a terpene built from unsaturated units."},
 {"id":"higher-expand-b01-068","topic":"skin","q":"In a radical substitution, which step is propagation?","options":["Cl₂ → 2Cl•","CH₃• + Cl• → CH₃Cl","CH₃• + CH₃• → C₂H₆","Cl• + CH₄ → HCl + CH₃•"],"answer":3,"explanation":"Propagation consumes one radical while producing another, allowing the chain to continue. Splitting Cl₂ initiates the chain; combining two radicals terminates it."},
 {"id":"higher-expand-b01-069","topic":"fats","q":"Hydrogenation converts an unsaturated oil into a more saturated material. Which change is expected?","options":["Less bromine is consumed per gram in an addition test","More C=C bonds are created","The number of carbon atoms must halve","Every ester link is hydrolysed"],"answer":0,"explanation":"Hydrogen adds across C=C bonds and reduces unsaturation. Fewer double bonds remain available to react with bromine; hydrogenation does not itself hydrolyse ester links."},
 {"id":"higher-expand-b01-070","topic":"alcohols","q":"When an aldehyde reacts with warm Fehling’s solution, what happens to the aldehyde?","options":["It is reduced while copper(II) ions are oxidised","It is oxidised while copper(II) ions are reduced","It forms a tertiary alcohol by addition","It loses its entire carbon skeleton as nitrogen gas"],"answer":1,"explanation":"The aldehyde is oxidised to a carboxylate under the alkaline conditions, while Cu²⁺ is reduced to Cu₂O, giving a brick-red precipitate."},
 {"id":"higher-expand-b01-071","topic":"reactants","q":"A compound reacts as 2A + B → 3C. Starting with 0.30 mol A and 0.10 mol B, what is the maximum amount of C?","options":["0.45 mol","0.10 mol","0.30 mol","0.90 mol"],"answer":2,"explanation":"For 0.10 mol B, 0.20 mol A is needed, so B is limiting. The 1:3 ratio gives 0.10 × 3 = 0.30 mol C."},
 {"id":"higher-expand-b01-072","topic":"reactants","q":"Heating 12.5 g CaCO₃ gives 5.60 g CaO. What is the percentage yield? GFMs: CaCO₃ = 100 g; CaO = 56 g. CaCO₃ → CaO + CO₂.","options":["44.8%","125%","56.0%","80.0%"],"answer":3,"explanation":"Theoretical CaO = (12.5/100) × 56 = 7.00 g. Percentage yield = 5.60/7.00 × 100 = 80.0%."},
 {"id":"higher-expand-b01-073","topic":"reactants","q":"For CaCO₃ → CaO + CO₂, what is the atom economy for the desired CO₂? GFMs: 100, 56 and 44 g respectively.","options":["44%","56%","78.6%","100%"],"answer":0,"explanation":"Desired product mass per equation amount is 44 g from 100 g reactant. Atom economy = 44/100 × 100 = 44%; it depends on which product is desired."},
 {"id":"higher-expand-b01-074","topic":"reactants","q":"A gas has molar volume 25.0 litres mol⁻¹ under the stated conditions. What volume is occupied by 0.0800 mol?","options":["0.00320 litres","2.00 litres","312.5 litres","20.0 litres"],"answer":1,"explanation":"Use the given molar volume, not a memorised value for other conditions. V = nVₘ = 0.0800 × 25.0 = 2.00 litres."},
 {"id":"higher-expand-b01-075","topic":"reactants","q":"A hydrocarbon burns as C₃H₈ + 5O₂ → 3CO₂ + 4H₂O(l). What gas volume remains after 40 cm³ propane reacts with 240 cm³ oxygen and the mixture cools? All gas volumes use the same conditions.","options":["120 cm³","200 cm³","160 cm³","280 cm³"],"answer":2,"explanation":"The propane consumes 5 × 40 = 200 cm³ O₂ and forms 3 × 40 = 120 cm³ CO₂. Water condenses. Add 40 cm³ unused O₂ to give 160 cm³ gas."},
 {"id":"higher-expand-b01-076","topic":"reactants","q":"A 0.240 mol sample of Al₂(SO₄)₃ dissolves completely. What total amount of ions is produced?","options":["0.480 mol","0.720 mol","0.240 mol","1.20 mol"],"answer":3,"explanation":"One formula unit produces two Al³⁺ and three SO₄²⁻ ions: five ions total. Thus 0.240 × 5 = 1.20 mol ions, assuming complete dissolution as stated."},
 {"id":"higher-expand-b01-077","topic":"reactants","q":"An industrial process has two consecutive yields of 75% and 80%. What percentage of the original theoretical amount is obtained overall?","options":["60%","77.5%","155%","95%"],"answer":0,"explanation":"Multiply stage yield fractions: 0.75 × 0.80 = 0.60. Therefore 60% of the original theoretical amount survives both stages; averaging percentages is inappropriate."},
 {"id":"higher-expand-b01-078","topic":"reactants","q":"How much 0.400 mol l⁻¹ solution is needed to prepare 200 cm³ of 0.0500 mol l⁻¹ solution by dilution?","options":["10.0 cm³","25.0 cm³","40.0 cm³","1600 cm³"],"answer":1,"explanation":"Solute moles are conserved: c₁V₁ = c₂V₂. V₁ = 0.0500 × 200/0.400 = 25.0 cm³, then dilute to a total of 200 cm³."},
 {"id":"higher-expand-b01-079","topic":"analysis","q":"A 0.287 g precipitate of AgCl is obtained from a sample. How many moles of chloride ions did it contain? GFM(AgCl) = 143.5 g; Ag⁺ + Cl⁻ → AgCl.","options":["0.00400 mol","0.00100 mol","0.00200 mol","0.0200 mol"],"answer":2,"explanation":"n(AgCl) = 0.287/143.5 = 0.00200 mol. The precipitation ratio is 1:1, so the chloride amount equals the AgCl amount."},
 {"id":"higher-expand-b01-080","topic":"analysis","q":"A hydrated salt loses 1.08 g water on heating and leaves 0.0200 mol anhydrous salt. What is x in salt·xH₂O? GFM(H₂O) = 18.0 g.","options":["2","6","0.33","3"],"answer":3,"explanation":"Water amount = 1.08/18.0 = 0.0600 mol. Divide by 0.0200 mol salt to obtain x = 3 water molecules per formula unit."},
 {"id":"higher-expand-b01-081","topic":"techniques","q":"A colourless solution is titrated with a coloured reagent. Why add the reagent dropwise close to the end-point?","options":["To minimise overshooting the first lasting colour change","To remove all dissolved ions before reaction","To guarantee an exactly zero initial burette reading","To avoid using the balanced equation"],"answer":0,"explanation":"Near the end-point only a small amount is required. Dropwise addition with swirling limits excess titrant and helps locate the first lasting change accurately."},
 {"id":"higher-expand-b01-082","topic":"apparatus","q":"A pipette is rinsed only with water before transferring a sample for titration. What error can residual water cause?","options":["An increase in sample concentration","Dilution of the sample inside the pipette","A change in the sample’s GFM","A larger fixed calibration volume"],"answer":1,"explanation":"Residual water mixes with the sample and can reduce the moles delivered in the calibrated volume. Rinsing with a little sample avoids this dilution error."},
 {"id":"higher-expand-b01-083","topic":"techniques","q":"In a titration, 18.60, 18.65 and 19.80 cm³ are accurate-run readings; the last is investigated and identified as an overshoot. What mean of the agreeing pair is used?","options":["19.017 cm³","18.700 cm³","18.625 cm³","0.050 cm³"],"answer":2,"explanation":"Average the agreeing valid titres: (18.60 + 18.65)/2 = 18.625 cm³ before reporting appropriate precision. Exclusion should follow investigation, not a wish for a preferred answer."},
 {"id":"higher-expand-b01-084","topic":"apparatus","q":"Why can a conical flask remain wet with deionised water before a titration?","options":["The water changes the reaction ratio to 1:1","The water always reacts with all the titrant first","Water makes all indicators unnecessary","The water changes volume but not the moles of sample delivered into it"],"answer":3,"explanation":"The aliquot’s solute amount is unchanged by additional water in the flask. The same titrant amount is required, provided the end-point remains suitable."},
 {"id":"higher-expand-b01-085","topic":"analysis","q":"A chromatographic sample gives peaks at 3.1 and 6.8 min. A pure reference peaks at 6.8 min under identical conditions. What is supported?","options":["The sample may contain the reference substance as one component","The sample must be pure","Both sample peaks are the same compound","The reference has a concentration of 6.8 mol l⁻¹"],"answer":0,"explanation":"Matching retention times support a possible identification, but do not prove it. The extra peak shows another detected component; retention time does not itself give concentration."},
 {"id":"higher-expand-b01-086","topic":"apparatus","q":"A burette starts at 1.35 cm³ and ends at 23.80 cm³. What volume has been delivered?","options":["25.15 cm³","22.45 cm³","23.80 cm³","1.35 cm³"],"answer":1,"explanation":"The delivered volume is the difference between readings: 23.80 − 1.35 = 22.45 cm³. A non-zero starting reading is acceptable if recorded correctly."},
 {"id":"higher-expand-b01-087","topic":"apparatus","q":"What does quantitative transfer into a volumetric flask require?","options":["Discarding the liquid and transferring only dry residue","Adding exactly the flask volume of water before the solute","Transferring the solution and rinsings from the original vessel","Leaving some crystals in the weighing beaker"],"answer":2,"explanation":"All the measured solute must reach the flask, including material in droplets or on the vessel walls. Rinsings prevent an unknown fraction being left behind."},
 {"id":"higher-expand-b01-088","topic":"apparatus","q":"A gas is very soluble in water. Which collection method avoids dissolution in a water trough?","options":["Collection over a large volume of water","Bubbling through water before measuring it","Leaving an open flask to catch it","A suitable gas syringe"],"answer":3,"explanation":"A gas syringe collects gas without requiring displacement of water. For a very soluble gas, collection over water would substantially underestimate gas production."},
 {"id":"higher-expand-b01-089","topic":"analysis","q":"A calibration gives absorbances 0.12, 0.24 and 0.36 for concentrations 2, 4 and 6 mg l⁻¹. What concentration corresponds to absorbance 0.30 within this linear range?","options":["5 mg l⁻¹","3 mg l⁻¹","10 mg l⁻¹","0.05 mg l⁻¹"],"answer":0,"explanation":"The data show absorbance proportional to concentration. At 0.30, the concentration lies halfway between 4 and 6 mg l⁻¹, giving 5 mg l⁻¹."},
 {"id":"higher-expand-b01-090","topic":"reporting","q":"What is the best response to an unexpected experimental result?","options":["Delete it automatically before looking for a cause","Check the procedure, repeat where possible and justify any exclusion","Change the reading to fit the expected trend","Report only the result closest to the textbook value"],"answer":1,"explanation":"Unexpected results may reveal procedural errors or real effects. Investigating and documenting them is more reliable than deleting or altering data solely because they disagree with expectations."},
 // batch Higher unit 3 written + extra MC (88 questions)
 {"id":"reactants-w01","topic":"reactants","type":"written","marks":3,"q":"Ethyl ethanoate is made from ethanol and ethanoic acid.\nCH₃COOH + C₂H₅OH → CH₃COOC₂H₅ + H₂O\nIn one preparation, 9.20 g of ethanol (GFM = 46.0 g) reacted with excess ethanoic acid and 11.4 g of ethyl ethanoate (GFM = 88.0 g) was obtained.\nCalculate the percentage yield of ethyl ethanoate.","points":[{"t":"Moles of ethanol = 9.20 ÷ 46.0 = 0.200 mol","m":1},{"t":"Theoretical mass of ester = 0.200 × 88.0 = 17.6 g","m":1},{"t":"Percentage yield = 11.4 ÷ 17.6 × 100 = 64.8 % (accept 65 %)","m":1}],"model":"n(ethanol) = 9.20 ÷ 46.0 = 0.200 mol. The equation is 1 : 1, so n(ester) = 0.200 mol and the theoretical mass = 0.200 × 88.0 = 17.6 g. Percentage yield = actual ÷ theoretical × 100 = 11.4 ÷ 17.6 × 100 = 64.8 %.","explanation":"Always base the theoretical yield on the limiting reactant (here ethanol, because the acid is in excess)."},
 {"id":"reactants-w02","topic":"reactants","type":"written","marks":4,"q":"Magnesium reacts with dilute hydrochloric acid.\nMg + 2HCl → MgCl₂ + H₂\n2.43 g of magnesium ribbon (GFM = 24.3 g) was added to 50.0 cm³ of hydrochloric acid, concentration 1.50 mol l⁻¹.\n(a) Show by calculation which reactant is in excess. (2)\n(b) Calculate the volume of hydrogen produced. The molar volume of hydrogen under these conditions is 24.0 l mol⁻¹. (2)","points":[{"t":"Moles: Mg = 2.43 ÷ 24.3 = 0.100 mol and HCl = 0.0500 × 1.50 = 0.0750 mol","m":1},{"t":"0.100 mol Mg needs 0.200 mol HCl, but only 0.0750 mol is present, so magnesium is in excess (HCl is limiting)","m":1},{"t":"Moles of hydrogen = 0.0750 ÷ 2 = 0.0375 mol (found from the limiting reactant)","m":1},{"t":"Volume = 0.0375 × 24.0 = 0.900 litres (900 cm³)","m":1}],"model":"(a) n(Mg) = 2.43 ÷ 24.3 = 0.100 mol. n(HCl) = 0.0500 l × 1.50 mol l⁻¹ = 0.0750 mol. The equation needs 2 mol HCl per mol Mg, so 0.100 mol Mg would need 0.200 mol HCl. Only 0.0750 mol is present, so HCl is limiting and magnesium is in excess.\n(b) From the limiting reactant: n(H₂) = 0.0750 ÷ 2 = 0.0375 mol. Volume = 0.0375 × 24.0 = 0.900 litres = 900 cm³."},
 {"id":"reactants-w03","topic":"reactants","type":"written","marks":2,"q":"Ethanol can be made by fermentation of glucose.\nC₆H₁₂O₆ → 2C₂H₅OH + 2CO₂\nCalculate the atom economy for the production of ethanol. (GFM glucose = 180 g; GFM ethanol = 46 g)","points":[{"t":"Mass of desired product = 2 × 46 = 92 g (from the balanced equation)","m":1},{"t":"Atom economy = 92 ÷ 180 × 100 = 51.1 %","m":1}],"model":"Atom economy = (mass of desired product ÷ total mass of reactants) × 100. Desired product = 2 × 46 = 92 g; total mass of reactants = 180 g. Atom economy = 92 ÷ 180 × 100 = 51.1 %."},
 {"id":"reactants-w04","topic":"reactants","type":"written","marks":4,"q":"Compound Z is made from compound X in a two-step synthesis. The yield for step 1 is 80 % and the yield for step 2 is 70 %.\n(a) Calculate the overall percentage yield. (1)\n(b) Calculate the mass of X (GFM = 120 g) needed to make 14.0 g of Z (GFM = 150 g). Assume that every step is 1 : 1 and use your answer to (a). (3)","points":[{"t":"Overall yield = 0.80 × 0.70 = 56 %","m":1},{"t":"Theoretical mass of Z required = 14.0 ÷ 0.56 = 25.0 g","m":1},{"t":"Moles of Z = 25.0 ÷ 150 = 0.167 mol, so moles of X = 0.167 mol","m":1},{"t":"Mass of X = 0.167 × 120 = 20.0 g","m":1}],"model":"(a) Overall yield = 80 % × 70 % = 56 %.\n(b) Only 56 % of the theoretical amount is obtained, so the theoretical mass of Z must be 14.0 ÷ 0.56 = 25.0 g. n(Z) = 25.0 ÷ 150 = 0.167 mol. The ratio is 1 : 1, so n(X) = 0.167 mol and mass of X = 0.167 × 120 = 20.0 g.","explanation":"Yields of consecutive steps are multiplied, not added."},
 {"id":"reactants-w05","topic":"reactants","type":"written","marks":3,"q":"Magnesium carbonate reacts with excess dilute hydrochloric acid.\nMgCO₃ + 2HCl → MgCl₂ + H₂O + CO₂\nCalculate the volume of carbon dioxide produced from 8.43 g of magnesium carbonate (GFM = 84.3 g). The molar volume of carbon dioxide under these conditions is 23.0 l mol⁻¹.","points":[{"t":"Moles of MgCO₃ = 8.43 ÷ 84.3 = 0.100 mol","m":1},{"t":"Mole ratio 1 : 1, so moles of CO₂ = 0.100 mol","m":1},{"t":"Volume = 0.100 × 23.0 = 2.30 litres (2300 cm³)","m":1}],"model":"n(MgCO₃) = 8.43 ÷ 84.3 = 0.100 mol. The equation shows 1 mol MgCO₃ gives 1 mol CO₂, so n(CO₂) = 0.100 mol. Volume = n × molar volume = 0.100 × 23.0 = 2.30 litres, which is 2300 cm³."},
 {"id":"reactants-w06","topic":"reactants","type":"written","marks":3,"q":"Calculate the total number of ions present in 5.85 g of sodium chloride, NaCl (GFM = 58.5 g). (The Avogadro constant is 6.02 × 10²³ mol⁻¹.)","points":[{"t":"Moles of NaCl = 5.85 ÷ 58.5 = 0.100 mol","m":1},{"t":"Number of formula units = 0.100 × 6.02 × 10²³ = 6.02 × 10²²","m":1},{"t":"Each formula unit gives two ions (Na⁺ and Cl⁻), so total ions = 1.20 × 10²³ (1.204 × 10²³)","m":1}],"model":"n(NaCl) = 5.85 ÷ 58.5 = 0.100 mol. Number of formula units = 0.100 × 6.02 × 10²³ = 6.02 × 10²². Each formula unit contains one Na⁺ and one Cl⁻, so the number of ions = 2 × 6.02 × 10²² = 1.20 × 10²³."},
 {"id":"reactants-w07","topic":"reactants","type":"written","marks":3,"q":"Ethane burns in oxygen.\n2C₂H₆(g) + 7O₂(g) → 4CO₂(g) + 6H₂O(l)\n20 cm³ of ethane is mixed with 100 cm³ of oxygen and the mixture is ignited. All gas volumes are measured at the same temperature and pressure, and the final mixture is cooled to room temperature.\nCalculate the total volume of gas remaining.","points":[{"t":"Volume of oxygen needed = 20 × 7/2 = 70 cm³, so 100 − 70 = 30 cm³ of oxygen is left over","m":1},{"t":"Volume of carbon dioxide formed = 20 × 4/2 = 40 cm³","m":1},{"t":"Total volume of gas remaining = 30 + 40 = 70 cm³ (water is liquid and does not count)","m":1}],"model":"Gas volumes are in the same ratio as the moles in the equation. 20 cm³ of ethane needs 20 × 7/2 = 70 cm³ of oxygen, so 30 cm³ of oxygen is left unreacted. It forms 20 × 4/2 = 40 cm³ of carbon dioxide. Water is a liquid at room temperature, so remaining gas = 30 + 40 = 70 cm³."},
 {"id":"reactants-w08","topic":"reactants","type":"written","marks":3,"q":"Zinc displaces copper from copper(II) sulfate solution.\nZn + CuSO₄ → ZnSO₄ + Cu\n6.54 g of zinc powder (GFM = 65.4 g) was added to 100 cm³ of copper(II) sulfate solution of concentration 0.600 mol l⁻¹.\nCalculate the mass of zinc left unreacted at the end of the reaction.","points":[{"t":"Moles of copper(II) sulfate = 0.100 × 0.600 = 0.0600 mol (the limiting reactant)","m":1},{"t":"Moles of zinc at the start = 6.54 ÷ 65.4 = 0.100 mol; moles zinc left = 0.100 − 0.0600 = 0.0400 mol","m":1},{"t":"Mass of zinc left = 0.0400 × 65.4 = 2.62 g","m":1}],"model":"n(CuSO₄) = 0.100 l × 0.600 mol l⁻¹ = 0.0600 mol. n(Zn) = 6.54 ÷ 65.4 = 0.100 mol. The ratio is 1 : 1, so 0.0600 mol of zinc reacts and 0.100 − 0.0600 = 0.0400 mol is left. Mass left = 0.0400 × 65.4 = 2.62 g."},
 {"id":"reactants-w09","topic":"reactants","type":"written","marks":3,"q":"Iron is extracted from iron(III) oxide in a blast furnace.\nFe₂O₃ + 3CO → 2Fe + 3CO₂\nCalculate the mass of iron, in kg, that could be produced from 400 kg of iron(III) oxide (GFM = 160 g; relative atomic mass of Fe = 56). Assume the reaction goes to completion.","points":[{"t":"Moles of Fe₂O₃ = 400 000 ÷ 160 = 2500 mol (2.50 × 10³ mol)","m":1},{"t":"Moles of iron = 2 × 2500 = 5000 mol (5.00 × 10³ mol)","m":1},{"t":"Mass of iron = 5000 × 56 = 280 000 g = 280 kg","m":1}],"model":"n(Fe₂O₃) = 400 000 g ÷ 160 g mol⁻¹ = 2500 mol. The equation gives 2 mol Fe per mol Fe₂O₃, so n(Fe) = 5000 mol. Mass = 5000 × 56 = 280 000 g = 280 kg.","explanation":"Convert kg to g before dividing by the GFM, or work in kmol throughout."},
 {"id":"reactants-w10","topic":"reactants","type":"written","marks":3,"q":"A company can make a pharmaceutical intermediate by two routes.\nRoute A: percentage yield 88 %, atom economy 36 %.\nRoute B: percentage yield 64 %, atom economy 92 %.\nUsing your knowledge of chemistry, discuss which route the company should choose.","points":[{"t":"Route B has the higher atom economy, so a greater proportion of the reactant atoms end up in the desired product and less waste is produced","m":1},{"t":"Route A gives more product from a given amount of reactants (higher yield), but its low atom economy means large amounts of by-products to dispose of, adding cost and environmental harm","m":1},{"t":"A reasoned conclusion is made, e.g. Route B is preferable on sustainability, provided unreacted starting materials from its lower yield can be recycled; or Route A if by-products can be sold/used","m":1}],"model":"Route A has the higher yield (88 % against 64 %), so it converts more of the limiting reactant to product. However, its atom economy is only 36 %, which means that most of the mass of the reactants ends up as waste by-products that must be separated, treated and disposed of. Route B has an atom economy of 92 %, so it is much more efficient in the use of atoms and produces far less waste. Its lower yield can be partly offset by recycling unreacted starting materials. Overall Route B is the better choice on cost of waste disposal and sustainability, although the final decision also depends on raw-material cost, energy use and hazards.","explanation":"Open-ended questions are marked on whether you show understanding of both measures and reach a justified decision."},
 {"id":"reactants-w11","topic":"reactants","type":"written","marks":2,"q":"Explain why a chemical company wants a process with a high atom economy.","points":[{"t":"A high atom economy means most of the reactant atoms end up in the desired product, so there are fewer waste by-products","m":1},{"t":"This reduces waste disposal costs and environmental impact, and makes better use of raw materials (more sustainable / more profit)","m":1}],"model":"Atom economy measures what proportion of the mass of the reactants ends up in the desired product. A high atom economy means there is little waste, so less money is spent separating and disposing of by-products, raw materials are used more efficiently (saving cost and conserving resources) and there is less environmental damage."},
 {"id":"reactants-w12","topic":"reactants","type":"written","marks":2,"q":"A reaction in an industrial process has a low yield because some of the reactants remain unreacted. Suggest two ways in which the manufacturer could make the process more economical.","points":[{"t":"Recycle the unreacted starting materials back into the reactor","m":1},{"t":"Any one of: use a catalyst to speed up the reaction/lower energy cost; use heat exchangers to recover energy from an exothermic reaction; improve conditions (temperature/pressure) to raise yield","m":1}],"model":"(1) Separate the unreacted starting materials from the product mixture and recycle them back into the reactor so that they are not wasted. (2) Use a catalyst so that the reaction can be done at a lower temperature and cost, or use heat exchangers to capture energy released by an exothermic reaction and use it to heat incoming reactants."},
 {"id":"reactants-w13","topic":"reactants","type":"written","marks":2,"q":"In a laboratory preparation the percentage yield is almost always less than 100 %. Give two reasons for this.","points":[{"t":"The reaction may be reversible so it does not go to completion / may be incomplete","m":1},{"t":"Any one of: side reactions form other products; product is lost during transfers, filtering or purification; impure reactants","m":1}],"model":"Possible reasons: the reaction is reversible and reaches an equilibrium with some reactants still present; side reactions produce unwanted by-products; some product is lost when it is transferred between containers, filtered, washed or purified by recrystallisation or distillation."},
 {"id":"reactants-x01","topic":"reactants","q":"What is the atom economy for the production of calcium oxide in the reaction CaCO₃ → CaO + CO₂? (GFM: CaCO₃ = 100 g; CaO = 56 g; CO₂ = 44 g)","options":["44 %","100 %","56 %","78 %"],"answer":2,"explanation":"Atom economy = mass of desired product ÷ total mass of products (or reactants) × 100 = 56 ÷ 100 × 100 = 56 %. The CO₂ is a waste by-product."},
 {"id":"reactants-x02","topic":"reactants","q":"The theoretical yield of a product is 10.0 g but 8.0 g is obtained. What is the percentage yield?","options":["80 %","20 %","125 %","8 %"],"answer":0,"explanation":"Percentage yield = actual ÷ theoretical × 100 = 8.0 ÷ 10.0 × 100 = 80 %."},
 {"id":"reactants-x03","topic":"reactants","q":"What volume does 0.050 mol of a gas occupy when the molar volume is 24.0 l mol⁻¹?","options":["0.0021 litres","480 litres","1.20 litres","12.0 litres"],"answer":2,"explanation":"Volume = n × molar volume = 0.050 × 24.0 = 1.20 litres."},
 {"id":"reactants-x04","topic":"reactants","q":"How many molecules are present in 0.50 mol of nitrogen gas? (Avogadro constant = 6.02 × 10²³ mol⁻¹)","options":["3.01 × 10²³","6.02 × 10²³","1.20 × 10²⁴","3.01 × 10²²"],"answer":0,"explanation":"Number of molecules = 0.50 × 6.02 × 10²³ = 3.01 × 10²³."},
 {"id":"reactants-x05","topic":"reactants","q":"In a continuous industrial process, which action is most likely to improve the overall use of raw materials?","options":["Increasing the amount of waste gases released","Discarding any unreacted starting materials","Recycling unreacted reactants back into the reactor","Using only low-purity reactants"],"answer":2,"explanation":"Recycling unreacted reactants means they are given another chance to react, so less raw material is wasted and the overall conversion improves."},
 {"id":"rate-w01","topic":"rate","type":"written","marks":2,"q":"Explain, in terms of collisions between particles, why the rate of reaction between zinc and hydrochloric acid increases when the concentration of the acid is increased.","points":[{"t":"There are more acid particles in a given volume (the particles are closer together)","m":1},{"t":"So collisions between the reacting particles are more frequent (more successful collisions per second)","m":1}],"model":"In a more concentrated acid there are more hydrogen ions in each cm³, so they collide with the surface of the zinc more often. A greater number of successful collisions per second means a faster rate of reaction."},
 {"id":"rate-w02","topic":"rate","type":"written","marks":3,"q":"The rate of a reaction increases when the temperature is raised, even though the number of collisions only increases slightly. Explain this using the idea of an energy distribution diagram (number of particles against kinetic energy).","points":[{"t":"At a higher temperature the particles have a greater average kinetic energy (the curve shifts to the right and flattens)","m":1},{"t":"A greater proportion/number of particles has energy equal to or greater than the activation energy (more of the area lies beyond Ea)","m":1},{"t":"So a greater proportion of collisions are successful, and the rate increases","m":1}],"model":"Raising the temperature increases the average kinetic energy of the particles, so the energy distribution curve moves to the right and becomes flatter. The area under the curve beyond the activation energy (Ea) is larger, meaning a greater fraction of particles has enough energy to react when they collide. A much greater proportion of collisions are therefore successful, so the rate increases sharply.","explanation":"The key idea is the fraction of particles with E ≥ Ea, not the small increase in collision frequency."},
 {"id":"rate-w03","topic":"rate","type":"written","marks":2,"q":"Explain how a catalyst increases the rate of a chemical reaction.","points":[{"t":"It provides an alternative reaction pathway with a lower activation energy","m":1},{"t":"A greater proportion of particles have energy equal to or greater than the (lower) activation energy, so more collisions are successful","m":1}],"model":"A catalyst provides an alternative route for the reaction with a lower activation energy. At the same temperature, a greater proportion of colliding particles have energy equal to or greater than this lower activation energy, so more collisions are successful and the reaction is faster. The catalyst is regenerated and the enthalpy change is unchanged."},
 {"id":"rate-w04","topic":"rate","type":"written","marks":3,"q":"The volume of gas produced in a reaction was measured at intervals.\nTime / s: 0, 20, 40, 60, 80\nVolume of gas / cm³: 0, 36, 58, 70, 76\n(a) Calculate the average rate of reaction between 20 s and 60 s, in cm³ s⁻¹. (1)\n(b) Explain why the rate of reaction decreases as the reaction proceeds. (2)","points":[{"t":"Average rate = (70 − 36) ÷ (60 − 20) = 0.85 cm³ s⁻¹","m":1},{"t":"The concentration of the reactants decreases as they are used up","m":1},{"t":"So collisions between reactant particles become less frequent","m":1}],"model":"(a) Average rate = change in volume ÷ change in time = (70 − 36) ÷ (60 − 20) = 34 ÷ 40 = 0.85 cm³ s⁻¹.\n(b) As the reaction proceeds the reactants are used up, so their concentration falls. There are fewer particles per unit volume, so collisions are less frequent and the rate decreases."},
 {"id":"rate-w05","topic":"rate","type":"written","marks":2,"q":"In an experiment on the reaction of sodium thiosulfate with acid, a cross viewed through the mixture disappeared after 40 s. In a second experiment at a higher temperature, the cross disappeared after 16 s. Calculate how many times faster the second reaction was, using relative rate = 1/t.","points":[{"t":"Relative rates: 1/40 = 0.025 s⁻¹ and 1/16 = 0.0625 s⁻¹","m":1},{"t":"Ratio = 2.5, so the second reaction was 2.5 times faster","m":1}],"model":"Relative rate = 1/t. Experiment 1: 1/40 = 0.025 s⁻¹. Experiment 2: 1/16 = 0.0625 s⁻¹. 0.0625 ÷ 0.025 = 2.5, so the second reaction was 2.5 times faster (equivalently 40 ÷ 16 = 2.5)."},
 {"id":"rate-w06","topic":"rate","type":"written","marks":2,"q":"A reaction has an activation energy of 70 kJ mol⁻¹ and an enthalpy change of −45 kJ mol⁻¹.\n(a) Calculate the activation energy of the reverse reaction. (1)\n(b) A catalyst is added. State what happens to the enthalpy change. (1)","points":[{"t":"Ea (reverse) = 70 + 45 = 115 kJ mol⁻¹","m":1},{"t":"The enthalpy change is unchanged (−45 kJ mol⁻¹)","m":1}],"model":"(a) The reaction is exothermic, so the products lie 45 kJ mol⁻¹ below the reactants on the potential energy diagram. The reverse reaction must climb from the products to the top of the barrier: 70 + 45 = 115 kJ mol⁻¹.\n(b) A catalyst lowers the activation energy of both the forward and reverse reactions but does not change the energy of the reactants or products, so ΔH stays at −45 kJ mol⁻¹."},
 {"id":"rate-w07","topic":"rate","type":"written","marks":2,"q":"A reaction takes 120 s at 25 °C. Assuming that the rate doubles for every 10 °C rise in temperature, calculate the time the reaction would take at 45 °C.","points":[{"t":"45 °C is two 10 °C rises, so the rate increases by 2 × 2 = 4 times","m":1},{"t":"Time = 120 ÷ 4 = 30 s","m":1}],"model":"A rise from 25 °C to 45 °C is two steps of 10 °C. The rate doubles each time, so it becomes 2 × 2 = 4 times faster. Since the rate is inversely proportional to the time, the time = 120 ÷ 4 = 30 s."},
 {"id":"rate-w08","topic":"rate","type":"written","marks":2,"q":"Powdered calcium carbonate reacts faster with dilute hydrochloric acid than the same mass of marble chips. Explain why.","points":[{"t":"The powder has a larger surface area (more particles of calcium carbonate exposed)","m":1},{"t":"So collisions between acid particles and the solid are more frequent","m":1}],"model":"The same mass of powder has a much larger surface area than chips, so many more calcium carbonate particles are exposed to the acid. The collision frequency between the reacting particles increases and the rate of reaction is faster."},
 {"id":"rate-w09","topic":"rate","type":"written","marks":3,"q":"Describe how you would investigate the effect of temperature on the rate of reaction between sodium thiosulfate solution and dilute hydrochloric acid. Include two variables that must be kept constant.","points":[{"t":"Method: heat/cool the thiosulfate solution to a measured temperature, add the acid, and start the timer","m":1},{"t":"Measure the time taken for the cloudiness (sulfur) to hide a cross under the flask; repeat at several temperatures","m":1},{"t":"Two variables kept constant, e.g. concentration and volume of each solution, same flask/cross/observer","m":1}],"model":"Measure out a fixed volume of sodium thiosulfate solution into a conical flask standing on a cross drawn on paper. Warm the solution to a chosen temperature and record it with a thermometer. Add a fixed volume of hydrochloric acid, start the stopclock and swirl. Stop the clock when the cross can no longer be seen through the cloudy sulfur. Repeat at several different temperatures. Keep constant: the concentrations and volumes of both solutions, and the same flask, cross and way of judging the end-point. Plot 1/t (relative rate) against temperature."},
 {"id":"rate-w10","topic":"rate","type":"written","marks":2,"q":"What is meant by the term activated complex?","points":[{"t":"An unstable (temporary) arrangement of atoms formed during a collision as old bonds break and new bonds form","m":1},{"t":"It is at the maximum/highest energy point on the potential energy diagram (the top of the energy barrier)","m":1}],"model":"The activated complex is a very unstable, short-lived arrangement of atoms formed at the instant of a successful collision, when bonds are partly broken and partly formed. It corresponds to the peak of the potential energy diagram. It then breaks down to give either the products or the original reactants."},
 {"id":"rate-w11","topic":"rate","type":"written","marks":2,"q":"The rate of a reaction between two gases increases when the pressure is increased at constant temperature. Explain why.","points":[{"t":"Increasing pressure forces the gas particles closer together (more particles in a given volume / higher concentration)","m":1},{"t":"So collisions are more frequent, increasing the rate","m":1}],"model":"At higher pressure the same number of gas particles occupies a smaller volume, so the concentration of each gas is greater. The particles collide more frequently, so the rate of reaction increases."},
 {"id":"rate-w12","topic":"rate","type":"written","marks":3,"q":"Describe how the potential energy diagram for an exothermic reaction changes when a catalyst is added. Refer to the activation energy and the enthalpy change.","points":[{"t":"The peak of the curve is lower (the activation energy is reduced)","m":1},{"t":"The energy levels of the reactants and products are unchanged, so ΔH is unchanged","m":1},{"t":"The catalyst provides an alternative pathway; the lower barrier means more particles can react","m":1}],"model":"With a catalyst the energy barrier between reactants and products is lower, so the activation energy is reduced for both the forward and the reverse reactions. The reactants and products stay at exactly the same energy levels, so the enthalpy change is the same. The catalyst provides an alternative reaction pathway with a lower activation energy."},
 {"id":"rate-w13","topic":"rate","type":"written","marks":2,"q":"A student follows the reaction between marble chips and excess acid by measuring the mass of the flask and contents. The graph of mass lost against time eventually levels off. Explain why.","points":[{"t":"The limiting reactant (marble) has been completely used up / the reaction has finished","m":1},{"t":"No more carbon dioxide is produced, so no further mass is lost","m":1}],"model":"The mass is lost as carbon dioxide escapes. When the limiting reactant (the marble chips) is used up the reaction stops, no more gas is produced and no more mass is lost, so the graph becomes horizontal."},
 {"id":"rate-x01","topic":"rate","q":"What is the effect of adding a catalyst on a potential energy diagram?","options":["The activation energy is lowered but ΔH is unchanged","ΔH becomes less negative","The products are raised to a higher energy","The activation energy is unchanged but ΔH is zero"],"answer":0,"explanation":"A catalyst provides an alternative pathway with a lower activation energy. It does not change the energies of the reactants and products, so ΔH is unchanged."},
 {"id":"rate-x02","topic":"rate","q":"Why does a rise in temperature increase the rate of reaction so much?","options":["The activation energy decreases","The particles become smaller","A greater proportion of particles have energy equal to or greater than the activation energy","The concentration of the particles increases"],"answer":2,"explanation":"Raising the temperature shifts the energy distribution so that a greater fraction of the particles have E ≥ Ea. Many more collisions are successful."},
 {"id":"rate-x03","topic":"rate","q":"A forward reaction has an activation energy of 60 kJ mol⁻¹ and ΔH = +20 kJ mol⁻¹. What is the activation energy of the reverse reaction?","options":["40 kJ mol⁻¹","80 kJ mol⁻¹","60 kJ mol⁻¹","20 kJ mol⁻¹"],"answer":0,"explanation":"The reaction is endothermic, so the products are 20 kJ mol⁻¹ above the reactants. The reverse reaction has to climb 60 − 20 = 40 kJ mol⁻¹."},
 {"id":"rate-x04","topic":"rate","q":"Cloudiness hides a cross after 50 s in one experiment and 25 s in another. Using relative rate = 1/t, how do the rates compare?","options":["The second experiment is half as fast as the first","The rates are the same","The second experiment is twice as fast as the first","The second experiment is 25 times faster"],"answer":2,"explanation":"Relative rate = 1/t: 1/50 = 0.020 s⁻¹ and 1/25 = 0.040 s⁻¹, so the second is twice as fast."},
 {"id":"rate-x05","topic":"rate","q":"In which change would the initial rate of reaction of marble chips with 1.0 mol l⁻¹ hydrochloric acid at constant temperature be unaffected?","options":["Using a larger volume of the same acid","Using powdered marble","Using 2.0 mol l⁻¹ acid","Using hotter acid"],"answer":0,"explanation":"The initial rate depends on concentration, temperature and surface area. A larger volume of acid of the same concentration does not change the concentration of H⁺ at the surface of the marble."},
 {"id":"equilibria-w01","topic":"equilibria","type":"written","marks":2,"q":"What is meant by a dynamic equilibrium?","points":[{"t":"The rate of the forward reaction is equal to the rate of the reverse reaction","m":1},{"t":"The concentrations of reactants and products stay constant (in a closed system)","m":1}],"model":"A dynamic equilibrium is reached in a closed system when the forward and reverse reactions are still taking place but at the same rate. As a result the concentrations of reactants and products remain constant, although they are not necessarily equal."},
 {"id":"equilibria-w02","topic":"equilibria","type":"written","marks":3,"q":"Dinitrogen tetroxide decomposes reversibly: N₂O₄(g) ⇌ 2NO₂(g)   ΔH = +57 kJ mol⁻¹\n(a) State and explain the effect of increasing the pressure on the equilibrium position. (2)\n(b) State the effect of increasing the temperature on the equilibrium position. (1)","points":[{"t":"Equilibrium shifts to the left (towards N₂O₄)","m":1},{"t":"Because there are fewer gas molecules (1 mol) on the left than on the right (2 mol), so the system reduces the pressure","m":1},{"t":"Increasing the temperature shifts the equilibrium to the right (the forward reaction is endothermic, so it absorbs the added energy)","m":1}],"model":"(a) The left-hand side has 1 mol of gas and the right-hand side has 2 mol. Increasing the pressure shifts the position of equilibrium to the side with fewer gas molecules, i.e. to the left, giving more N₂O₄.\n(b) The forward reaction is endothermic. Raising the temperature favours the endothermic direction, so the equilibrium shifts to the right and more NO₂ is formed."},
 {"id":"equilibria-w03","topic":"equilibria","type":"written","marks":3,"q":"In the Haber process, nitrogen and hydrogen react to form ammonia.\nN₂(g) + 3H₂(g) ⇌ 2NH₃(g)   ΔH = −92 kJ mol⁻¹\nThe reaction is carried out at about 450 °C. Explain why a temperature of 450 °C is chosen rather than a much lower or much higher temperature.","points":[{"t":"The forward reaction is exothermic, so a lower temperature would give a higher yield of ammonia (equilibrium moves to the right)","m":1},{"t":"But at a low temperature the rate of reaction is too slow","m":1},{"t":"450 °C is a compromise that gives an acceptable yield at a reasonable rate (a higher temperature would lower the yield further)","m":1}],"model":"Because the forward reaction is exothermic, the equilibrium position favours ammonia at lower temperatures, so a higher temperature would reduce the yield. However, at low temperatures the reaction is far too slow to be economical. A temperature of about 450 °C is a compromise between a reasonable yield and an acceptable rate of reaction."},
 {"id":"equilibria-w04","topic":"equilibria","type":"written","marks":2,"q":"Iron is used as a catalyst in the Haber process. State the effect of the catalyst on (a) the rate at which equilibrium is reached and (b) the percentage yield of ammonia at equilibrium.","points":[{"t":"(a) It speeds up the forward and reverse reactions equally, so equilibrium is reached faster","m":1},{"t":"(b) There is no change in the position of equilibrium / percentage yield","m":1}],"model":"A catalyst lowers the activation energy for both the forward and the reverse reaction by the same amount, so equilibrium is reached more quickly. It has no effect on the position of equilibrium, so the percentage yield is unchanged."},
 {"id":"equilibria-w05","topic":"equilibria","type":"written","marks":3,"q":"In aqueous solution an equilibrium exists between dichromate and chromate ions.\nCr₂O₇²⁻(aq) + H₂O(l) ⇌ 2CrO₄²⁻(aq) + 2H⁺(aq)\nDichromate ions are orange and chromate ions are yellow. Sodium hydroxide solution is added to the orange solution.\n(a) State the colour change that is observed. (1)\n(b) Explain this colour change. (2)","points":[{"t":"The solution turns from orange to yellow","m":1},{"t":"Hydroxide ions react with (remove) hydrogen ions, so the concentration of H⁺ decreases","m":1},{"t":"The equilibrium shifts to the right to replace the H⁺ ions, producing more yellow chromate ions","m":1}],"model":"(a) The solution changes from orange to yellow.\n(b) OH⁻ ions react with H⁺ ions (H⁺ + OH⁻ → H₂O), lowering the concentration of H⁺. The position of equilibrium shifts to the right to oppose this change by producing more H⁺, and so more CrO₄²⁻ (yellow) is formed."},
 {"id":"equilibria-w06","topic":"equilibria","type":"written","marks":3,"q":"(a) Calculate the pH of hydrochloric acid of concentration 0.0050 mol l⁻¹. (1)\n(b) A solution has a pH of 3.4. Calculate the hydrogen ion concentration. (1)\n(c) A solution has a pH of 12.0. Calculate the hydroxide ion concentration. (Kw = 1.0 × 10⁻¹⁴ mol² l⁻²) (1)","points":[{"t":"pH = −log[H⁺] = −log 0.0050 = 2.30","m":1},{"t":"[H⁺] = 10⁻³·⁴ = 4.0e-04 mol l⁻¹ (4.0 × 10⁻⁴)","m":1},{"t":"[H⁺] = 1.0 × 10⁻¹² so [OH⁻] = 1.0 × 10⁻¹⁴ ÷ 1.0 × 10⁻¹² = 1.0 × 10⁻² mol l⁻¹","m":1}],"model":"(a) HCl is a strong acid, so [H⁺] = 0.0050 mol l⁻¹ and pH = −log 0.0050 = 2.30.\n(b) [H⁺] = 10^(−pH) = 10^(−3.4) = 4.0 × 10⁻⁴ mol l⁻¹.\n(c) [H⁺] = 10⁻¹² mol l⁻¹, so [OH⁻] = Kw ÷ [H⁺] = 1.0 × 10⁻¹⁴ ÷ 1.0 × 10⁻¹² = 1.0 × 10⁻² mol l⁻¹."},
 {"id":"equilibria-w07","topic":"equilibria","type":"written","marks":2,"q":"25.0 cm³ of hydrochloric acid of concentration 0.100 mol l⁻¹ is diluted with water to a final volume of 250 cm³. Calculate the pH of the diluted solution.","points":[{"t":"New concentration = 0.100 × 25.0 ÷ 250 = 0.0100 mol l⁻¹ (diluted ten times)","m":1},{"t":"pH = −log 0.0100 = 2.00 (accept 2)","m":1}],"model":"The solution is diluted ten times, so [H⁺] = 0.0100 mol l⁻¹ (HCl is a strong acid and fully ionised). pH = −log 0.0100 = 2.00."},
 {"id":"equilibria-w08","topic":"equilibria","type":"written","marks":3,"q":"20 cm³ of hydrochloric acid of concentration 0.10 mol l⁻¹ and 20 cm³ of ethanoic acid of concentration 0.10 mol l⁻¹ are each added to an excess of magnesium ribbon.\n(a) Compare the total volume of hydrogen produced by each acid. (1)\n(b) Compare the initial rate of reaction with each acid and explain your answer. (2)","points":[{"t":"The same volume of hydrogen is produced by each acid (same number of moles of acid)","m":1},{"t":"The reaction with hydrochloric acid is initially faster","m":1},{"t":"Hydrochloric acid is a strong acid (fully ionised) and has a higher H⁺ concentration; ethanoic acid is weak (only partially ionised)","m":1}],"model":"(a) Both acids contain the same number of moles of acid (0.0020 mol) and are monoprotic, so they produce the same volume of hydrogen.\n(b) The initial rate is faster with hydrochloric acid. HCl is a strong acid and is completely ionised, so it has a higher concentration of H⁺ ions than ethanoic acid of the same concentration, which is a weak acid and only partially ionised. More frequent collisions occur with the magnesium. As the H⁺ ions of the weak acid are used up, more ethanoic acid molecules ionise, so the same total volume of hydrogen is eventually produced."},
 {"id":"equilibria-w09","topic":"equilibria","type":"written","marks":2,"q":"Describe two measurements that could be made to show that a 0.10 mol l⁻¹ solution of ethanoic acid is a weak acid when compared with a 0.10 mol l⁻¹ solution of hydrochloric acid.","points":[{"t":"pH measurement: the ethanoic acid has a higher pH (about 2.9 compared with 1.0)","m":1},{"t":"Conductivity measurement: the ethanoic acid has a lower conductivity (fewer ions); or a slower reaction rate with magnesium/carbonate","m":1}],"model":"Measure the pH of each solution with a pH meter: the ethanoic acid has a higher pH because it is only partly ionised. Measure the electrical conductivity of each: the ethanoic acid solution has a lower conductivity because it contains fewer ions. (Comparing the rate of reaction with magnesium is another possible test.)"},
 {"id":"equilibria-w10","topic":"equilibria","type":"written","marks":2,"q":"Iron(III) ions react with thiocyanate ions to form a deep red complex ion.\nFe³⁺(aq) + SCN⁻(aq) ⇌ FeSCN²⁺(aq)\nA few drops of concentrated iron(III) nitrate solution are added to an equilibrium mixture. Describe and explain the colour change.","points":[{"t":"The red colour becomes deeper (more intense)","m":1},{"t":"The concentration of Fe³⁺ has been increased, so the equilibrium shifts to the right to oppose the change, producing more FeSCN²⁺","m":1}],"model":"Adding iron(III) nitrate increases the concentration of Fe³⁺ ions. The system responds by shifting the position of equilibrium to the right, using up some of the extra Fe³⁺ and forming more of the red FeSCN²⁺, so the solution becomes a deeper red."},
 {"id":"equilibria-w11","topic":"equilibria","type":"written","marks":3,"q":"N₂(g) + 3H₂(g) ⇌ 2NH₃(g)\n(a) Explain, in terms of the number of gas molecules, why a high pressure increases the yield of ammonia. (2)\n(b) Suggest why an extremely high pressure is not used in industry. (1)","points":[{"t":"There are 4 mol of gas on the left and 2 mol on the right","m":1},{"t":"Increasing the pressure shifts the equilibrium to the side with fewer gas molecules (to the right), so more ammonia forms","m":1},{"t":"Very high pressures need expensive equipment/high energy costs and are more hazardous","m":1}],"model":"(a) The left-hand side has 1 + 3 = 4 mol of gas, the right-hand side has 2 mol. A higher pressure is relieved by shifting the equilibrium to the side with fewer molecules, so more ammonia is formed.\n(b) Very high pressure requires thicker, stronger (and so more expensive) reaction vessels and pipework and uses more energy for compression, and it is also more dangerous."},
 {"id":"equilibria-w12","topic":"equilibria","type":"written","marks":2,"q":"The graph of concentration against time for a reversible reaction in a closed vessel shows the concentrations of the reactant and product both becoming constant after 40 s. What does this tell you about the reaction after 40 s? Explain your answer.","points":[{"t":"Equilibrium has been reached at (or before) 40 s","m":1},{"t":"The rates of the forward and reverse reactions are equal, so there is no further net change in concentrations","m":1}],"model":"After 40 s the reaction has reached dynamic equilibrium. The forward and reverse reactions are still occurring but at equal rates, so there is no net change in the concentrations of the reactant and the product."},
 {"id":"equilibria-w13","topic":"equilibria","type":"written","marks":3,"q":"Calculate the pH of sodium hydroxide solution of concentration 0.020 mol l⁻¹. (Kw = 1.0 × 10⁻¹⁴ mol² l⁻²)","points":[{"t":"Sodium hydroxide is a strong alkali so [OH⁻] = 0.020 mol l⁻¹ and [H⁺][OH⁻] = Kw is used","m":1},{"t":"[H⁺] = 1.0 × 10⁻¹⁴ ÷ 0.020 = 5.0e-13 mol l⁻¹ (5.0 × 10⁻¹³)","m":1},{"t":"pH = −log (5.0 × 10⁻¹³) = 12.3","m":1}],"model":"NaOH is fully ionised, so [OH⁻] = 0.020 mol l⁻¹. [H⁺] = Kw ÷ [OH⁻] = 1.0 × 10⁻¹⁴ ÷ 0.020 = 5.0 × 10⁻¹³ mol l⁻¹. pH = −log [H⁺] = 12.3. (Alternatively pOH = −log 0.020 = 1.70, so pH = 14.00 − 1.70 = 12.3.)"},
 {"id":"equilibria-x01","topic":"equilibria","q":"What is the pH of nitric acid of concentration 0.0010 mol l⁻¹?","options":["1.0","11.0","3.0","0.0010"],"answer":2,"explanation":"Nitric acid is a strong acid, so [H⁺] = 0.0010 mol l⁻¹ and pH = −log 0.0010 = 3.0."},
 {"id":"equilibria-x02","topic":"equilibria","q":"A solution has pH 11 at 25 °C. What is its hydroxide ion concentration? (Kw = 1.0 × 10⁻¹⁴ mol² l⁻²)","options":["1.0 × 10⁻³ mol l⁻¹","1.0 × 10⁻¹¹ mol l⁻¹","1.0 × 10⁻¹⁴ mol l⁻¹","11 mol l⁻¹"],"answer":0,"explanation":"pH 11 means [H⁺] = 1.0 × 10⁻¹¹ mol l⁻¹, so [OH⁻] = Kw ÷ [H⁺] = 1.0 × 10⁻¹⁴ ÷ 1.0 × 10⁻¹¹ = 1.0 × 10⁻³ mol l⁻¹."},
 {"id":"equilibria-x03","topic":"equilibria","q":"2SO₂(g) + O₂(g) ⇌ 2SO₃(g) has a negative ΔH. What is the effect of increasing the temperature on the equilibrium?","options":["The position shifts to the right, giving a higher yield of SO₃","The position is unchanged but equilibrium is reached more slowly","The position shifts to the left, giving a lower yield of SO₃","The position is unchanged because the catalyst controls it"],"answer":2,"explanation":"The forward reaction is exothermic, so a rise in temperature shifts the equilibrium in the endothermic direction (to the left), reducing the yield of SO₃."},
 {"id":"equilibria-x04","topic":"equilibria","q":"What is the effect of adding a catalyst to a reaction mixture that is already at equilibrium?","options":["There is no change in the equilibrium position","The equilibrium shifts to the right","The equilibrium shifts to the left","The reverse reaction stops"],"answer":0,"explanation":"A catalyst increases the rates of the forward and reverse reactions equally, so the position of equilibrium does not change."},
 {"id":"equilibria-x05","topic":"equilibria","q":"Compared with hydrochloric acid of the same concentration, a solution of ethanoic acid has…","options":["a lower pH because it is partially ionised","a higher conductivity because it has more ions","a lower electrical conductivity because it is only partially ionised","the same pH because both are monoprotic"],"answer":2,"explanation":"Ethanoic acid is a weak acid and is only partly ionised, so it contains fewer ions, has a lower conductivity and a higher pH than hydrochloric acid of the same concentration."},
 {"id":"energy-w01","topic":"energy","type":"written","marks":3,"q":"0.920 g of ethanol (GFM = 46.0 g) was burned and the heat released warmed 250 g of water from 20.4 °C to 38.9 °C. Calculate the enthalpy of combustion of ethanol, in kJ mol⁻¹, using this data. (c = 4.18 kJ kg⁻¹ °C⁻¹)","points":[{"t":"Energy released = c m ΔT = 4.18 × 0.250 × 18.5 = 19.3 kJ","m":1},{"t":"Moles of ethanol = 0.920 ÷ 46.0 = 0.0200 mol","m":1},{"t":"ΔHc = −19.33 ÷ 0.0200 = −967 kJ mol⁻¹ (accept −966.6)","m":1}],"model":"ΔT = 38.9 − 20.4 = 18.5 °C. Energy to water = c m ΔT = 4.18 × 0.250 × 18.5 = 19.33 kJ. n(ethanol) = 0.920 ÷ 46.0 = 0.0200 mol. Enthalpy per mole = 19.33 ÷ 0.0200 = 967 kJ. The reaction is exothermic, so ΔHc = −967 kJ mol⁻¹.","explanation":"Remember the negative sign for an exothermic reaction, and change grams of water to kg when using c in kJ kg⁻¹ °C⁻¹."},
 {"id":"energy-w02","topic":"energy","type":"written","marks":3,"q":"Use the enthalpies of formation below to calculate the enthalpy of combustion of methane.\nCH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l)\nΔHf(CH₄) = −75 kJ mol⁻¹; ΔHf(CO₂) = −394 kJ mol⁻¹; ΔHf(H₂O) = −286 kJ mol⁻¹","points":[{"t":"Sum of ΔHf (products) = −394 + 2(−286) = −966 kJ mol⁻¹","m":1},{"t":"Sum of ΔHf (reactants) = −75 kJ mol⁻¹ (oxygen is an element so ΔHf = 0)","m":1},{"t":"ΔH = −966 − (−75) = -891 kJ mol⁻¹","m":1}],"model":"ΔH = Σ ΔHf(products) − Σ ΔHf(reactants) = [−394 + 2(−286)] − [−75 + 2(0)] = −966 + 75 = -891 kJ mol⁻¹."},
 {"id":"energy-w03","topic":"energy","type":"written","marks":3,"q":"Calculate the enthalpy change for the formation of propane from its elements, using the enthalpies of combustion below.\n3C(s) + 4H₂(g) → C₃H₈(g)\nΔHc(C) = −394 kJ mol⁻¹; ΔHc(H₂) = −286 kJ mol⁻¹; ΔHc(C₃H₈) = −2220 kJ mol⁻¹","points":[{"t":"Combustion of the elements: 3 × (−394) + 4 × (−286) = −1182 + (−1144) = −2326 kJ mol⁻¹","m":1},{"t":"Combustion of propane = −2220 kJ mol⁻¹","m":1},{"t":"ΔH = −2326 − (−2220) = -106 kJ mol⁻¹","m":1}],"model":"By Hess's law, the route from the elements via their combustion products equals the route via propane. ΔH(formation) = Σ ΔHc(reactants) − Σ ΔHc(products) = [3(−394) + 4(−286)] − (−2220) = −2326 + 2220 = -106 kJ mol⁻¹.","explanation":"For combustion data the order is reactants minus products, the opposite of the formation-data calculation."},
 {"id":"energy-w04","topic":"energy","type":"written","marks":3,"q":"Use the mean bond enthalpies below to calculate the enthalpy change for the reaction.\nCH₄(g) + Cl₂(g) → CH₃Cl(g) + HCl(g)\nC–H 412 kJ mol⁻¹; Cl–Cl 243 kJ mol⁻¹; C–Cl 338 kJ mol⁻¹; H–Cl 431 kJ mol⁻¹","points":[{"t":"Energy to break bonds = 412 + 243 = 655 kJ mol⁻¹","m":1},{"t":"Energy released making bonds = 338 + 431 = 769 kJ mol⁻¹","m":1},{"t":"ΔH = 655 − 769 = -114 kJ mol⁻¹","m":1}],"model":"Only one C–H bond and the Cl–Cl bond are broken: 412 + 243 = 655 kJ mol⁻¹ taken in. One C–Cl bond and one H–Cl bond are made: 338 + 431 = 769 kJ mol⁻¹ released. ΔH = bonds broken − bonds formed = 655 − 769 = -114 kJ mol⁻¹ (exothermic)."},
 {"id":"energy-w05","topic":"energy","type":"written","marks":2,"q":"The enthalpy of combustion of ethanol found by experiment is less exothermic than the data book value. Give two reasons for this.","points":[{"t":"Heat is lost to the surroundings (e.g. to the air, the apparatus/calorimeter)","m":1},{"t":"Any one of: incomplete combustion of the fuel; evaporation of fuel/water; heat absorbed by the container","m":1}],"model":"Not all the heat released by the burning fuel is transferred to the water: some is lost to the surroundings and absorbed by the calorimeter. The combustion may also be incomplete (forming soot or carbon monoxide), and some fuel may evaporate. The measured temperature rise is therefore smaller than it should be, giving a smaller calculated enthalpy change."},
 {"id":"energy-w06","topic":"energy","type":"written","marks":2,"q":"Describe two ways in which the experimental set-up used to measure the enthalpy of combustion of a liquid fuel could be improved to give a more accurate value.","points":[{"t":"Reduce heat loss by using a lid/draught shield/insulation around the calorimeter, or place the flame closer to the container","m":1},{"t":"Stir the water so that the temperature is uniform; or use a copper calorimeter/heat-resistant container for better heat transfer","m":1}],"model":"Heat loss could be reduced by placing a draught shield or insulating lid around the burner and container and by keeping the flame close to the base of the container. The water should be stirred so that the temperature recorded is uniform. A copper container conducts heat well and improves heat transfer to the water."},
 {"id":"energy-w07","topic":"energy","type":"written","marks":3,"q":"Butane burns with an enthalpy of combustion of −2877 kJ mol⁻¹. Calculate the mass of butane (GFM = 58.0 g) that must burn to raise the temperature of 2.00 kg of water by 25.0 °C. Assume that all of the energy is transferred to the water. (c = 4.18 kJ kg⁻¹ °C⁻¹)","points":[{"t":"Energy needed = c m ΔT = 4.18 × 2.00 × 25.0 = 209 kJ","m":1},{"t":"Moles of butane = 209 ÷ 2877 = 0.0726 mol","m":1},{"t":"Mass of butane = 0.0726 × 58.0 = 4.21 g","m":1}],"model":"Energy required = 4.18 × 2.00 × 25.0 = 209 kJ. Each mole of butane releases 2877 kJ, so n = 209 ÷ 2877 = 0.0726 mol. Mass = 0.0726 × 58.0 = 4.21 g."},
 {"id":"energy-w08","topic":"energy","type":"written","marks":3,"q":"50.0 cm³ of hydrochloric acid, concentration 1.00 mol l⁻¹, was mixed with 50.0 cm³ of sodium hydroxide solution, concentration 1.00 mol l⁻¹. The temperature rose by 6.7 °C. Calculate the enthalpy of neutralisation, in kJ mol⁻¹ of water formed. (Assume that 1.00 cm³ of solution has a mass of 1.00 g; c = 4.18 kJ kg⁻¹ °C⁻¹)","points":[{"t":"Energy released = c m ΔT = 4.18 × 0.100 × 6.7 = 2.80 kJ","m":1},{"t":"Moles of water formed = 0.0500 × 1.00 = 0.0500 mol","m":1},{"t":"ΔH = −2.80 ÷ 0.0500 = −56 kJ mol⁻¹ (accept −56.0)","m":1}],"model":"The total volume is 100 cm³, which has a mass of 100 g = 0.100 kg. Energy = 4.18 × 0.100 × 6.7 = 2.80 kJ. Moles of acid (and alkali) = 0.0500 l × 1.00 = 0.0500 mol, which forms 0.0500 mol of water. ΔH = −2.80 ÷ 0.0500 = −56 kJ mol⁻¹.","explanation":"Use the total mass of the mixed solutions (100 g), not just the volume of one of them."},
 {"id":"energy-w09","topic":"energy","type":"written","marks":3,"q":"Calculate the enthalpy change for the reaction in a blast furnace.\nFe₂O₃(s) + 3CO(g) → 2Fe(s) + 3CO₂(g)\nΔHf(Fe₂O₃) = −824 kJ mol⁻¹; ΔHf(CO) = −111 kJ mol⁻¹; ΔHf(CO₂) = −394 kJ mol⁻¹","points":[{"t":"Σ ΔHf(products) = 3 × (−394) = −1182 kJ mol⁻¹ (iron is an element, ΔHf = 0)","m":1},{"t":"Σ ΔHf(reactants) = −824 + 3 × (−111) = −1157 kJ mol⁻¹","m":1},{"t":"ΔH = −1182 − (−1157) = -25 kJ mol⁻¹","m":1}],"model":"ΔH = Σ ΔHf(products) − Σ ΔHf(reactants) = [2(0) + 3(−394)] − [(−824) + 3(−111)] = −1182 − (−1157) = -25 kJ mol⁻¹."},
 {"id":"energy-w10","topic":"energy","type":"written","marks":2,"q":"Define the enthalpy of combustion of a substance.","points":[{"t":"The enthalpy change (energy released) when one mole of a substance is burned completely","m":1},{"t":"in (excess) oxygen","m":1}],"model":"The enthalpy of combustion is the enthalpy change when 1 mole of a substance burns completely in oxygen (to form carbon dioxide and water for a hydrocarbon or alcohol). It is always negative because combustion is exothermic."},
 {"id":"energy-w11","topic":"energy","type":"written","marks":3,"q":"The enthalpy of combustion of ethanol (GFM = 46 g) is −1367 kJ mol⁻¹ and that of octane (GFM = 114 g) is −5470 kJ mol⁻¹. Calculate the energy released per gram for each fuel and state which fuel releases more energy per gram.","points":[{"t":"Ethanol: 1367 ÷ 46 = 29.7 kJ g⁻¹","m":1},{"t":"Octane: 5470 ÷ 114 = 48.0 kJ g⁻¹","m":1},{"t":"Octane releases more energy per gram","m":1}],"model":"Energy per gram = |ΔHc| ÷ GFM. Ethanol: 1367 ÷ 46 = 29.7 kJ g⁻¹. Octane: 5470 ÷ 114 = 48.0 kJ g⁻¹. Octane releases more energy per gram, which is why hydrocarbon fuels are used when mass matters (for example in aircraft)."},
 {"id":"energy-w12","topic":"energy","type":"written","marks":2,"q":"A reaction has ΔH = +50 kJ mol⁻¹. State whether the reaction is exothermic or endothermic and describe what happens to the temperature of the surroundings.","points":[{"t":"The reaction is endothermic","m":1},{"t":"Energy is taken in from the surroundings, so the temperature of the surroundings falls","m":1}],"model":"A positive ΔH means that the products have more enthalpy than the reactants, so the reaction is endothermic. It absorbs energy from the surroundings, so the temperature of the surroundings falls."},
 {"id":"energy-x01","topic":"energy","q":"A → B has ΔH = −30 kJ mol⁻¹ and B → C has ΔH = +50 kJ mol⁻¹. What is ΔH for A → C?","options":["−20 kJ mol⁻¹","+80 kJ mol⁻¹","−80 kJ mol⁻¹","+20 kJ mol⁻¹"],"answer":3,"explanation":"By Hess's law, ΔH(A → C) = ΔH(A → B) + ΔH(B → C) = −30 + 50 = +20 kJ mol⁻¹."},
 {"id":"energy-x02","topic":"energy","q":"How much energy is needed to raise the temperature of 0.500 kg of water by 10.0 °C? (c = 4.18 kJ kg⁻¹ °C⁻¹)","options":["2.09 kJ","20.9 kJ","209 kJ","41.8 kJ"],"answer":1,"explanation":"E = c m ΔT = 4.18 × 0.500 × 10.0 = 20.9 kJ."},
 {"id":"energy-x03","topic":"energy","q":"On a potential energy diagram for an exothermic reaction, where are the products relative to the reactants?","options":["At a higher energy than the reactants","At the same energy as the reactants","At the same energy as the activated complex","At a lower energy than the reactants"],"answer":3,"explanation":"In an exothermic reaction energy is released, so the products have a lower enthalpy than the reactants and ΔH is negative."},
 {"id":"energy-x04","topic":"energy","q":"When calculating ΔH from mean bond enthalpies, which expression is used?","options":["Σ bonds formed − Σ bonds broken","Σ bonds broken − Σ bonds formed","Σ bonds broken + Σ bonds formed","Σ products − Σ reactants"],"answer":1,"explanation":"Energy is taken in to break bonds and released when bonds form, so ΔH = Σ(bonds broken) − Σ(bonds formed)."},
 {"id":"energy-x05","topic":"energy","q":"The enthalpy of combustion of propane is −2220 kJ mol⁻¹. How much energy is released when 0.0100 mol of propane burns completely?","options":["222 kJ","2.22 kJ","2220 kJ","22.2 kJ"],"answer":3,"explanation":"Energy released = 0.0100 mol × 2220 kJ mol⁻¹ = 22.2 kJ."},
 {"id":"analysis-w01","topic":"analysis","type":"written","marks":3,"q":"25.0 cm³ of sodium hydroxide solution of unknown concentration was neutralised by 18.4 cm³ of sulfuric acid, concentration 0.100 mol l⁻¹.\nH₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O\nCalculate the concentration of the sodium hydroxide solution.","points":[{"t":"Moles of H₂SO₄ = 0.0184 × 0.100 = 1.84e-03 mol (1.84 × 10⁻³)","m":1},{"t":"Moles of NaOH = 2 × 1.84e-03 = 3.68e-03 mol (3.68 × 10⁻³)","m":1},{"t":"Concentration = 3.68e-03 ÷ 0.0250 = 0.147 mol l⁻¹","m":1}],"model":"n(H₂SO₄) = 0.0184 l × 0.100 mol l⁻¹ = 1.84 × 10⁻³ mol. The equation shows that 2 mol NaOH react with 1 mol H₂SO₄, so n(NaOH) = 3.68 × 10⁻³ mol. c(NaOH) = n ÷ V = 3.68 × 10⁻³ ÷ 0.0250 = 0.147 mol l⁻¹."},
 {"id":"analysis-w02","topic":"analysis","type":"written","marks":3,"q":"Iron(II) ions are oxidised by permanganate ions in acid solution.\nMnO₄⁻ + 8H⁺ + 5Fe²⁺ → Mn²⁺ + 4H₂O + 5Fe³⁺\n25.0 cm³ of an iron(II) solution required 21.6 cm³ of potassium permanganate solution, concentration 0.0200 mol l⁻¹, to reach the end-point. Calculate the concentration of the iron(II) solution.","points":[{"t":"Moles of MnO₄⁻ = 0.0216 × 0.0200 = 4.32e-04 mol (4.32 × 10⁻⁴)","m":1},{"t":"Moles of Fe²⁺ = 5 × 4.32e-04 = 2.16e-03 mol (2.16 × 10⁻³)","m":1},{"t":"Concentration = 2.16e-03 ÷ 0.0250 = 0.0864 mol l⁻¹","m":1}],"model":"n(MnO₄⁻) = 0.0216 × 0.0200 = 4.32 × 10⁻⁴ mol. The ratio is 1 : 5, so n(Fe²⁺) = 5 × 4.32 × 10⁻⁴ = 2.16 × 10⁻³ mol. c(Fe²⁺) = 2.16 × 10⁻³ ÷ 0.0250 = 0.0864 mol l⁻¹ (0.0864 mol l⁻¹)."},
 {"id":"analysis-w03","topic":"analysis","type":"written","marks":2,"q":"State two properties of a good primary standard.","points":[{"t":"High purity / known exact composition (and does not absorb water or react with the air, i.e. stable)","m":1},{"t":"Any one of: soluble in water; high GFM (reduces weighing error); can be weighed accurately","m":1}],"model":"A primary standard must be available in a very pure form with an exactly known formula, and it must be stable (not absorbing water or carbon dioxide from the air or decomposing). It should also be soluble in water and ideally have a high GFM so that weighing errors are small."},
 {"id":"analysis-w04","topic":"analysis","type":"written","marks":3,"q":"Describe how you would prepare 250 cm³ of a standard solution from a solid primary standard.","points":[{"t":"Weigh the solid accurately (e.g. by difference) and dissolve it in distilled/deionised water in a beaker","m":1},{"t":"Transfer the solution to a 250 cm³ volumetric flask, rinsing the beaker and funnel into the flask","m":1},{"t":"Add water up to the graduation mark (last drops with a dropper) and stopper and invert the flask to mix","m":1}],"model":"Weigh the required mass of the solid accurately and dissolve it in a little distilled water in a beaker. Pour the solution into a 250 cm³ volumetric flask through a funnel, rinsing the beaker and funnel with distilled water and adding the rinsings to the flask. Make up to the mark with distilled water (using a dropper for the final drops so the bottom of the meniscus sits on the line), then stopper the flask and invert it several times to mix thoroughly."},
 {"id":"analysis-w05","topic":"analysis","type":"written","marks":3,"q":"State three steps that should be taken to improve the accuracy of a titration.","points":[{"t":"Rinse the burette with the solution it will contain (and the pipette with the solution it will deliver)","m":1},{"t":"Do a rough titration first, then add the titrant drop by drop near the end-point, swirling and using a white tile","m":1},{"t":"Repeat until concordant titres (within 0.2 cm³) are obtained and use the mean","m":1}],"model":"Rinse the burette with the solution it will hold and the pipette with the solution it will measure so that no dilution occurs. Do a rough titration to find the approximate end-point, then add the solution dropwise near the end-point with swirling, with a white tile under the flask to see the colour change. Repeat the titration until at least two titres agree to within 0.2 cm³ (concordant) and calculate the average of these."},
 {"id":"analysis-w06","topic":"analysis","type":"written","marks":2,"q":"A student carried out a titration and recorded these titres: 21.3 cm³ (rough), 20.7 cm³, 20.5 cm³, 20.6 cm³, 20.9 cm³. Using concordant results (within 0.2 cm³ of each other), calculate the average titre to be used in the calculation.","points":[{"t":"The concordant results are 20.7, 20.5 and 20.6 cm³ (the rough titre and 20.9 cm³ are not used)","m":1},{"t":"Average = (20.7 + 20.5 + 20.6) ÷ 3 = 20.6 cm³","m":1}],"model":"The rough titre is never used. The values 20.7, 20.5 and 20.6 cm³ all agree to within 0.2 cm³ of each other, but 20.9 cm³ is 0.4 cm³ from 20.5 cm³, so it is excluded. Average = (20.7 + 20.5 + 20.6) ÷ 3 = 20.6 cm³."},
 {"id":"analysis-w07","topic":"analysis","type":"written","marks":3,"q":"The concentration of sulfate ions in a solution can be found by gravimetric analysis. Excess barium chloride solution was added to 25.0 cm³ of the solution. The precipitate of barium sulfate was filtered, washed, dried and weighed to constant mass. The mass of barium sulfate (GFM = 233 g) was 0.350 g.\nBa²⁺ + SO₄²⁻ → BaSO₄\nCalculate the concentration of sulfate ions in the original solution.","points":[{"t":"Moles of BaSO₄ = 0.350 ÷ 233 = 1.50e-03 mol (1.50 × 10⁻³)","m":1},{"t":"Moles of SO₄²⁻ = 1.50 × 10⁻³ mol (1 : 1 ratio)","m":1},{"t":"Concentration = 1.50 × 10⁻³ ÷ 0.0250 = 0.060 mol l⁻¹","m":1}],"model":"n(BaSO₄) = 0.350 ÷ 233 = 1.50 × 10⁻³ mol. One mole of sulfate ions gives one mole of precipitate, so n(SO₄²⁻) = 1.50 × 10⁻³ mol in the 25.0 cm³ sample. c = 1.50 × 10⁻³ ÷ 0.0250 = 0.060 mol l⁻¹.","explanation":"Heating and weighing until the mass is constant shows that the precipitate is completely dry."},
 {"id":"analysis-w08","topic":"analysis","type":"written","marks":2,"q":"A food colouring is analysed by paper chromatography alongside samples of three permitted dyes. Describe how the results can be used to decide which permitted dyes the colouring contains.","points":[{"t":"Compare the spots: a spot from the colouring that travels the same distance (same Rf value) as a reference spot indicates the same dye","m":1},{"t":"The number of spots in the colouring shows the minimum number of different components it contains","m":1}],"model":"Each component of the food colouring separates into its own spot. If a spot from the colouring has the same Rf value (travels the same distance under the same conditions) as one of the reference dyes, that dye is present. The number of separate spots gives the number of components in the mixture."},
 {"id":"analysis-w09","topic":"analysis","type":"written","marks":2,"q":"Describe how to prepare 250 cm³ of a 0.0200 mol l⁻¹ solution from a stock solution of concentration 0.500 mol l⁻¹, showing the volume of stock solution needed.","points":[{"t":"Volume of stock needed = 0.0200 × 250 ÷ 0.500 = 10.0 cm³","m":1},{"t":"Measure this volume with a pipette into a 250 cm³ volumetric flask and make up to the mark with distilled water","m":1}],"model":"Moles needed = 0.0200 × 0.250 = 0.00500 mol, which is contained in 0.00500 ÷ 0.500 = 0.0100 l = 10.0 cm³ of the stock solution. Transfer 10.0 cm³ of the stock solution with a pipette into a 250 cm³ volumetric flask, then add distilled water up to the graduation mark and mix by inverting the flask."},
 {"id":"analysis-w10","topic":"analysis","type":"written","marks":4,"q":"A 0.500 g sample of impure sodium hydroxide was dissolved in water and made up to 250 cm³ in a standard flask. A 25.0 cm³ portion required 20.5 cm³ of hydrochloric acid, concentration 0.0500 mol l⁻¹, for neutralisation.\nNaOH + HCl → NaCl + H₂O\nCalculate the percentage purity of the sodium hydroxide (GFM = 40.0 g).","points":[{"t":"Moles of HCl = 0.0205 × 0.0500 = 1.025e-03 mol, so moles of NaOH in 25.0 cm³ = 1.025e-03 mol","m":1},{"t":"Moles of NaOH in 250 cm³ = 10 × 1.025e-03 = 0.0103 mol","m":1},{"t":"Mass of NaOH = 0.0103 × 40.0 = 0.410 g","m":1},{"t":"Percentage purity = 0.410 ÷ 0.500 × 100 = 82.0 %","m":1}],"model":"n(HCl) = 0.0205 × 0.0500 = 1.025 × 10⁻³ mol = n(NaOH) in the 25.0 cm³ portion. The whole 250 cm³ contains ten times as much: 0.01025 mol. Mass of NaOH = 0.01025 × 40.0 = 0.410 g. Purity = 0.410 ÷ 0.500 × 100 = 82.0 %.","explanation":"Do not forget the 250 cm³ ÷ 25.0 cm³ = 10 scaling factor."},
 {"id":"analysis-w11","topic":"analysis","type":"written","marks":2,"q":"No indicator needs to be added in a titration of an acidified iron(II) solution with potassium permanganate solution. Explain why.","points":[{"t":"Permanganate ions are purple but are reduced to almost colourless Mn²⁺ ions as they react","m":1},{"t":"The first permanent pink/purple colour (one drop excess) marks the end-point, so the permanganate acts as its own indicator","m":1}],"model":"The MnO₄⁻ ions are intensely purple but they are reduced to Mn²⁺, which is almost colourless, so the solution stays colourless while the iron(II) is present. When all the Fe²⁺ has reacted, one extra drop of permanganate gives a permanent pale pink colour. The permanganate therefore acts as its own indicator."},
 {"id":"analysis-w12","topic":"analysis","type":"written","marks":3,"q":"Hydrogen peroxide reacts with acidified permanganate ions.\n2MnO₄⁻ + 6H⁺ + 5H₂O₂ → 2Mn²⁺ + 8H₂O + 5O₂\n25.0 cm³ of a diluted hydrogen peroxide solution required 20.0 cm³ of potassium permanganate solution, concentration 0.0200 mol l⁻¹. Calculate the concentration of the hydrogen peroxide solution.","points":[{"t":"Moles of MnO₄⁻ = 0.0200 × 0.0200 = 4.00e-04 mol (4.00 × 10⁻⁴)","m":1},{"t":"Moles of H₂O₂ = 4.00e-04 × 5/2 = 1.00e-03 mol (1.00 × 10⁻³)","m":1},{"t":"Concentration = 1.00e-03 ÷ 0.0250 = 0.040 mol l⁻¹","m":1}],"model":"n(MnO₄⁻) = 0.0200 l × 0.0200 mol l⁻¹ = 4.00 × 10⁻⁴ mol. From the equation 2 mol MnO₄⁻ react with 5 mol H₂O₂, so n(H₂O₂) = 4.00 × 10⁻⁴ × 5/2 = 1.00 × 10⁻³ mol. c = 1.00 × 10⁻³ ÷ 0.0250 = 0.040 mol l⁻¹."},
 {"id":"analysis-x01","topic":"analysis","q":"Which property is essential for a substance to be used as a primary standard?","options":["It is very pure and stable with an accurately known formula","It is a liquid at room temperature","It is highly coloured","It reacts slowly with water"],"answer":0,"explanation":"A primary standard is weighed to make a standard solution, so it must be very pure, stable and of known composition."},
 {"id":"analysis-x02","topic":"analysis","q":"20.0 cm³ of sodium hydroxide solution is neutralised by 25.0 cm³ of hydrochloric acid, concentration 0.100 mol l⁻¹ (1 : 1 reaction). What is the concentration of the sodium hydroxide?","options":["0.0800 mol l⁻¹","0.100 mol l⁻¹","0.125 mol l⁻¹","0.250 mol l⁻¹"],"answer":2,"explanation":"n(HCl) = 0.0250 × 0.100 = 2.50 × 10⁻³ mol = n(NaOH). c = 2.50 × 10⁻³ ÷ 0.0200 = 0.125 mol l⁻¹."},
 {"id":"analysis-x03","topic":"analysis","q":"10.0 cm³ of a 1.00 mol l⁻¹ solution is diluted to 100.0 cm³ with water. What is the new concentration?","options":["0.100 mol l⁻¹","0.0100 mol l⁻¹","1.00 mol l⁻¹","10.0 mol l⁻¹"],"answer":0,"explanation":"c₂ = c₁V₁ ÷ V₂ = 1.00 × 10.0 ÷ 100.0 = 0.100 mol l⁻¹."},
 {"id":"analysis-x04","topic":"analysis","q":"In paper chromatography, what does it show when a spot from an unknown mixture has the same Rf value as a spot from a reference compound under the same conditions?","options":["The mixture contains no other compounds","The compounds have different formulae","The mixture may contain the reference compound","The reference compound is a solvent"],"answer":2,"explanation":"Matching Rf values under identical conditions is evidence that the compound is present, though not absolute proof as other compounds can have similar Rf values."},
 {"id":"analysis-x05","topic":"analysis","q":"Why is a burette rinsed with a little of the solution it will contain before a titration?","options":["So that residual water does not dilute the solution","To remove all the air from the jet","To change the concentration of the solution","To make the solution flow faster"],"answer":0,"explanation":"Water left in the burette would dilute the solution being added, making the titre appear larger than it should be. Rinsing with the solution itself prevents this."},
 // batch unit1 written+MC
 {"id":"periodicity-w01","topic":"periodicity","type":"written","marks":4,"q":"The first twenty elements of the periodic table can be classified by bonding and structure.\nName the bonding and structure of each of the following elements.\n(a) silicon  (b) sulfur (S₈)  (c) argon  (d) magnesium","points":[{"t":"(a) silicon: covalent network","m":1},{"t":"(b) sulfur: covalent molecular (S₈ molecules)","m":1},{"t":"(c) argon: monatomic (single atoms held by London dispersion forces)","m":1},{"t":"(d) magnesium: metallic (lattice of positive ions in a sea of delocalised electrons)","m":1}],"model":"(a) Silicon is a covalent network: a giant three-dimensional lattice of atoms joined by covalent bonds. (b) Sulfur is covalent molecular: discrete S₈ molecules held together by London dispersion forces. (c) Argon is monatomic: separate atoms with only weak London dispersion forces between them. (d) Magnesium is metallic: positive ions held in a lattice by the attraction to a sea of delocalised electrons."},
 {"id":"periodicity-w02","topic":"periodicity","type":"written","marks":3,"q":"Describe and explain the trend in covalent radius across a period from sodium to chlorine.","points":[{"t":"Covalent radius decreases across the period","m":1},{"t":"The nuclear charge (number of protons) increases while the outer electrons are in the same shell","m":1},{"t":"So the outer electrons are pulled closer to the nucleus (stronger attraction)","m":1}],"model":"Covalent radius decreases from sodium to chlorine. Across the period the number of protons (nuclear charge) increases but the electrons are being added to the same outer shell, so the screening by inner shells is about the same. The outer electrons are therefore attracted more strongly towards the nucleus and the atom becomes smaller."},
 {"id":"periodicity-w03","topic":"periodicity","type":"written","marks":2,"q":"Explain why the covalent radius increases down Group 1 from lithium to potassium.","points":[{"t":"The number of occupied electron shells increases down the group","m":1},{"t":"So the outer electrons are further from the nucleus (and more screened by the inner electrons), which outweighs the increase in nuclear charge","m":1}],"model":"Each element down the group has one more occupied electron shell than the one above. The outer electrons are therefore further from the nucleus and screened by more inner electrons, so the atom is larger even though the nuclear charge is greater."},
 {"id":"periodicity-w04","topic":"periodicity","type":"written","marks":2,"q":"Define the term first ionisation energy.","points":[{"t":"The energy required to remove one mole of electrons","m":1},{"t":"from one mole of (gaseous) atoms (in the gaseous state)","m":1}],"model":"The first ionisation energy is the energy required to remove one mole of electrons from one mole of gaseous atoms, forming one mole of gaseous 1+ ions."},
 {"id":"periodicity-w05","topic":"periodicity","type":"written","marks":3,"q":"The first ionisation energy generally increases across a period from lithium to neon. Explain this trend.","points":[{"t":"The nuclear charge increases across the period","m":1},{"t":"The covalent radius decreases (the outer electron is in the same shell with similar screening)","m":1},{"t":"So the outer electron is held more strongly and more energy is needed to remove it","m":1}],"model":"Moving from lithium to neon the nuclear charge increases, while the outer electrons remain in the same shell with similar screening, so the covalent radius decreases. The attraction between the nucleus and the outer electron becomes stronger and more energy is needed to remove it, so the first ionisation energy increases."},
 {"id":"periodicity-w06","topic":"periodicity","type":"written","marks":3,"q":"The first ionisation energy decreases down Group 1. Explain why.","points":[{"t":"The covalent radius (atomic size) increases because there are more occupied shells","m":1},{"t":"The outer electron is further from the nucleus and is more screened by the inner shells","m":1},{"t":"So the attraction between the nucleus and the outer electron is weaker and less energy is needed to remove it","m":1}],"model":"Going down Group 1 each atom has an extra electron shell, so the outer electron is further from the nucleus and is screened by more inner electrons. The attraction of the nucleus for this electron is reduced even though the nuclear charge is larger, so less energy is needed to remove it."},
 {"id":"periodicity-w07","topic":"periodicity","type":"written","marks":3,"q":"The successive ionisation energies of element X, in kJ mol⁻¹, are: 1st 590; 2nd 1150; 3rd 4900; 4th 6500.\n(a) State the group of the periodic table in which element X is found. (1)\n(b) Explain your answer to (a). (2)","points":[{"t":"(a) Group 2 (two outer electrons)","m":1},{"t":"There is a very large increase between the 2nd and 3rd ionisation energies","m":1},{"t":"The third electron is removed from an inner shell, which is closer to the nucleus and less screened (so it is held much more strongly)","m":1}],"model":"(a) Group 2. (b) The jump from 1150 to 4900 kJ mol⁻¹ shows that after two electrons are removed the next electron comes from a full inner shell that is closer to the nucleus and is held much more strongly. So there are two electrons in the outer shell, which is typical of a Group 2 element."},
 {"id":"periodicity-w08","topic":"periodicity","type":"written","marks":3,"q":"(a) Write an equation, including state symbols, for the second ionisation energy of magnesium. (1)\n(b) Explain why the second ionisation energy of magnesium is greater than its first ionisation energy. (2)","points":[{"t":"Mg⁺(g) → Mg²⁺(g) + e⁻","m":1},{"t":"The second electron is removed from a positive ion (Mg⁺), which has the same nuclear charge but fewer electrons","m":1},{"t":"So the remaining electrons are held more strongly (the ion is smaller, with less electron repulsion)","m":1}],"model":"(a) Mg⁺(g) → Mg²⁺(g) + e⁻. (b) The first electron is removed from a neutral atom. The second is removed from a positive ion in which the nuclear charge is unchanged but there are fewer electrons, so the electrons are attracted more strongly and the ion is smaller. More energy is needed to remove the second electron."},
 {"id":"periodicity-w09","topic":"periodicity","type":"written","marks":3,"q":"(a) What is meant by the term electronegativity? (1)\n(b) Explain why electronegativity generally increases across a period. (2)","points":[{"t":"The attraction an atom has for the electrons in a (covalent) bond","m":1},{"t":"The nuclear charge increases across the period","m":1},{"t":"The covalent radius decreases, so the bonding electrons are attracted more strongly","m":1}],"model":"(a) Electronegativity is a measure of the attraction an atom has for the electrons in a bond. (b) Across a period the nuclear charge increases and the covalent radius decreases, so the nucleus attracts the shared electrons more strongly and electronegativity increases."},
 {"id":"periodicity-w10","topic":"periodicity","type":"written","marks":2,"q":"Explain why fluorine has a higher electronegativity than iodine.","points":[{"t":"Fluorine has a smaller covalent radius (fewer occupied shells)","m":1},{"t":"So the bonding electrons are closer to the nucleus and are less screened, giving a stronger attraction","m":1}],"model":"A fluorine atom has fewer occupied electron shells, so it is much smaller than iodine. The shared electrons are close to the nucleus and are only slightly screened by inner electrons, so the attraction for the bonding electrons is greater. Fluorine is therefore more electronegative than iodine."},
 {"id":"periodicity-w11","topic":"periodicity","type":"written","marks":3,"q":"The first ionisation energy of neon is much greater than that of sodium. Explain why.","points":[{"t":"Neon's outer electrons are in the second shell, closer to the nucleus than sodium's outer electron (third shell)","m":1},{"t":"Sodium's outer electron is screened by two full inner shells, so it is held weakly (neon is screened by only one)","m":1},{"t":"Neon's outer electrons are held more strongly, so more energy is needed to remove one","m":1}],"model":"Neon's outer electrons are in the second shell, close to the nucleus and screened by only one inner shell, so they are held strongly. Sodium's outer electron is in the third shell, further from the nucleus and screened by two inner shells, so it is held weakly and is easy to remove. Much more energy is therefore needed to remove an electron from neon."},
 {"id":"periodicity-w12","topic":"periodicity","type":"written","marks":2,"q":"Explain why a nitrogen atom has a smaller covalent radius than a carbon atom.","points":[{"t":"Nitrogen has a greater nuclear charge (7 protons against 6)","m":1},{"t":"The outer electrons are in the same shell, so they are pulled closer to the nucleus","m":1}],"model":"Both atoms have their outer electrons in the second shell, but nitrogen has seven protons against six in carbon. The greater nuclear charge attracts the outer electrons more strongly, so the nitrogen atom is smaller."},
 {"id":"periodicity-x01","topic":"periodicity","q":"What happens to covalent radius across a period from left to right?","options":["It increases because more electrons are added","It decreases because the nuclear charge increases","It stays the same because the shell is the same","It increases because the nuclear charge increases"],"answer":1,"explanation":"Across a period electrons are added to the same shell while the nuclear charge increases, so the outer electrons are pulled in and the radius decreases."},
 {"id":"periodicity-x02","topic":"periodicity","q":"Which element has the highest electronegativity?","options":["Chlorine","Oxygen","Caesium","Fluorine"],"answer":3,"explanation":"Fluorine is small and has a high nuclear charge with little screening, so it has the strongest attraction for bonding electrons."},
 {"id":"periodicity-x03","topic":"periodicity","q":"Why is the first ionisation energy of potassium less than that of sodium?","options":["Potassium has a smaller nuclear charge","The outer electron is further from the nucleus and more screened","Potassium has a smaller covalent radius","Potassium has fewer electrons in its outer shell"],"answer":1,"explanation":"Potassium has an extra shell, so its outer electron is further from the nucleus and is more screened. It is held more weakly."},
 {"id":"periodicity-x04","topic":"periodicity","q":"Which equation represents the second ionisation energy of calcium?","options":["Ca(g) → Ca²⁺(g) + 2e⁻","Ca(s) → Ca⁺(g) + e⁻","Ca²⁺(g) → Ca³⁺(g) + e⁻","Ca⁺(g) → Ca²⁺(g) + e⁻"],"answer":3,"explanation":"The second ionisation energy removes one mole of electrons from one mole of gaseous 1+ ions: Ca⁺(g) → Ca²⁺(g) + e⁻."},
 {"id":"periodicity-x05","topic":"periodicity","q":"An element has a very large jump between its second and third ionisation energies. In which group is it?","options":["Group 1","Group 2","Group 3","Group 7"],"answer":1,"explanation":"The big jump shows that the third electron is removed from an inner shell, so there are two outer electrons: Group 2."},
 {"id":"structure-w01","topic":"structure","type":"written","marks":2,"q":"What is meant by a polar covalent bond? Explain how it arises.","points":[{"t":"A covalent bond in which the shared electrons are unequally shared, giving a permanent dipole (δ+ and δ−)","m":1},{"t":"Because the two atoms have different electronegativities, the more electronegative atom attracts the electrons more strongly","m":1}],"model":"In a polar covalent bond the bonding electrons are not shared equally. The atoms have different electronegativities, so the more electronegative atom attracts the electron pair more and becomes slightly negative (δ−) while the other atom becomes slightly positive (δ+)."},
 {"id":"structure-w02","topic":"structure","type":"written","marks":3,"q":"Electronegativity values: Li 1.0; H 2.1; Cl 3.0; F 4.0.\nUsing these values, state the type of bonding in each of Cl₂, HCl and LiF, and arrange the three substances in order of increasing ionic character.","points":[{"t":"Cl₂ has no electronegativity difference: pure (non-polar) covalent","m":1},{"t":"HCl has a difference of 0.9: polar covalent; LiF has a difference of 3.0: ionic","m":1},{"t":"Order of increasing ionic character: Cl₂ < HCl < LiF","m":1}],"model":"The greater the difference in electronegativity, the more ionic the bond. Cl–Cl: difference 0, pure covalent. H–Cl: 3.0 − 2.1 = 0.9, polar covalent. Li–F: 4.0 − 1.0 = 3.0, ionic. Increasing ionic character: Cl₂ < HCl < LiF."},
 {"id":"structure-w03","topic":"structure","type":"written","marks":2,"q":"Carbon dioxide has polar bonds but the molecule is non-polar. Explain why.","points":[{"t":"The molecule is linear (symmetrical) and the two C=O bonds are polar","m":1},{"t":"The dipoles act in opposite directions and cancel out, so there is no overall (permanent) dipole","m":1}],"model":"Each C=O bond is polar because oxygen is more electronegative than carbon. The CO₂ molecule is linear, so the two bond dipoles are equal and point in opposite directions. They cancel each other and the molecule has no permanent dipole."},
 {"id":"structure-w04","topic":"structure","type":"written","marks":2,"q":"Bromine has a higher boiling point than chlorine. Explain this in terms of intermolecular forces.","points":[{"t":"Both are non-polar molecules, held together by London dispersion forces","m":1},{"t":"Br₂ has more electrons, so its London dispersion forces are stronger and more energy is needed to separate the molecules","m":1}],"model":"Br₂ and Cl₂ are non-polar molecules, so the only forces between their molecules are London dispersion forces. Br₂ molecules have more electrons than Cl₂ molecules, so the dispersion forces are stronger and more energy is needed to overcome them. Bromine therefore has the higher boiling point."},
 {"id":"structure-w05","topic":"structure","type":"written","marks":3,"q":"Water has a much higher boiling point than hydrogen sulfide (H₂S). Explain why.","points":[{"t":"There are hydrogen bonds between water molecules (O–H bonds, very polar)","m":1},{"t":"H₂S molecules are held by weaker permanent dipole–dipole interactions and London dispersion forces","m":1},{"t":"Hydrogen bonds are stronger, so more energy is needed to separate the water molecules","m":1}],"model":"In water, hydrogen is bonded to the highly electronegative oxygen, so there are hydrogen bonds between the molecules. Hydrogen sulfide molecules are held together only by the weaker permanent dipole–dipole interactions and London dispersion forces. Hydrogen bonds are stronger, so much more energy is needed to separate water molecules and its boiling point is higher."},
 {"id":"structure-w06","topic":"structure","type":"written","marks":3,"q":"Ethanol (C₂H₅OH) has a boiling point of 78 °C and propane (C₃H₈) has a boiling point of −42 °C, even though the two molecules have similar numbers of electrons. Explain the difference.","points":[{"t":"Ethanol has hydrogen bonding between its molecules (O–H group)","m":1},{"t":"Propane is non-polar and has only London dispersion forces","m":1},{"t":"Hydrogen bonds are stronger than London dispersion forces, so more energy is needed to separate ethanol molecules","m":1}],"model":"Ethanol contains an O–H bond, so hydrogen bonds form between ethanol molecules in addition to London dispersion forces. Propane is non-polar and the only forces between its molecules are London dispersion forces. As the molecules have similar numbers of electrons, the dispersion forces are of similar size, and the extra hydrogen bonding in ethanol means more energy is needed to boil it."},
 {"id":"structure-w07","topic":"structure","type":"written","marks":3,"q":"Methanol dissolves in water, but hexane does not. Explain why, in terms of the intermolecular forces involved.","points":[{"t":"Methanol contains an O–H group and forms hydrogen bonds with water molecules","m":1},{"t":"Hexane is non-polar and has only London dispersion forces with water","m":1},{"t":"Water molecules are strongly hydrogen bonded to each other, so they do not interact with hexane (insoluble)","m":1}],"model":"Methanol molecules contain an O–H bond, so they can form hydrogen bonds with water and mix with it. Hexane is a non-polar molecule that can only form weak London dispersion forces with water. These are far weaker than the hydrogen bonds between water molecules, so hexane does not dissolve."},
 {"id":"structure-w08","topic":"structure","type":"written","marks":2,"q":"Ice is less dense than liquid water. Explain why.","points":[{"t":"In ice, each water molecule is held in a regular open lattice by hydrogen bonds","m":1},{"t":"The molecules are further apart in ice than in liquid water, so a given mass occupies a larger volume","m":1}],"model":"In ice the water molecules are held in a regular, open, three-dimensional arrangement by hydrogen bonds. There are spaces within this structure, so the molecules are slightly further apart on average than in the liquid, where the structure partly collapses. The same mass occupies a larger volume, so ice is less dense."},
 {"id":"structure-w09","topic":"structure","type":"written","marks":3,"q":"Propanone (CH₃COCH₃) has a boiling point of 56 °C and butane (C₄H₁₀) has a boiling point of −1 °C. Their molecules have a similar number of electrons. Explain the difference in boiling point.","points":[{"t":"Propanone molecules are polar (permanent dipole), so have permanent dipole–dipole interactions as well as London dispersion forces","m":1},{"t":"Butane molecules are non-polar so have only London dispersion forces","m":1},{"t":"The permanent dipole–dipole interactions are stronger (for similar electron numbers), so more energy is needed to separate propanone molecules","m":1}],"model":"The C=O bond in propanone is polar and the molecule has a permanent dipole, so propanone molecules attract each other by permanent dipole–dipole interactions as well as by London dispersion forces. Butane is non-polar and has only London dispersion forces. For similar electron numbers, permanent dipole–dipole interactions add to the attraction, so more energy is needed to separate propanone molecules and it boils at a higher temperature."},
 {"id":"structure-w10","topic":"structure","type":"written","marks":3,"q":"Silicon melts at 1414 °C and sulfur (S₈) melts at 115 °C. Explain this difference in terms of structure and bonding.","points":[{"t":"Silicon is a covalent network with strong covalent bonds throughout the structure","m":1},{"t":"Sulfur is covalent molecular: only the weak London dispersion forces between S₈ molecules are broken on melting","m":1},{"t":"Much more energy is needed to break covalent bonds than to overcome London dispersion forces","m":1}],"model":"Silicon is a covalent network, so melting requires the breaking of strong covalent bonds throughout the lattice. Sulfur exists as discrete S₈ molecules, and on melting only the weak London dispersion forces between molecules are overcome (the covalent bonds within S₈ stay intact). Far less energy is needed for sulfur, so it has the much lower melting point."},
 {"id":"structure-w11","topic":"structure","type":"written","marks":3,"q":"Three solids A, B and C have the following properties.\nA: melting point 801 °C; does not conduct as a solid; conducts when molten and when dissolved in water.\nB: melting point 114 °C; does not conduct in any state; insoluble in water, soluble in hexane.\nC: melting point above 1700 °C; very hard; insoluble in all solvents; does not conduct electricity.\nState the bonding and structure of each solid and give one piece of evidence for each.","points":[{"t":"A is ionic (lattice): conducts when molten/dissolved because ions are free to move","m":1},{"t":"B is covalent molecular (non-polar): low melting point as only weak forces between molecules; dissolves in non-polar hexane","m":1},{"t":"C is covalent network: very high melting point and hardness because of strong covalent bonds throughout; no free electrons or ions","m":1}],"model":"A is an ionic compound with a lattice of ions: it conducts only when the ions are free to move (molten or in solution). B is covalent molecular: it has a low melting point because only weak intermolecular forces are broken on melting, and as a non-polar substance it dissolves in non-polar hexane. C is a covalent network: its very high melting point and hardness come from strong covalent bonds throughout the structure, and there are no mobile charged particles to conduct."},
 {"id":"structure-w12","topic":"structure","type":"written","marks":2,"q":"Glycerol, which has three O–H groups per molecule, is much more viscous than ethanol, which has one. Explain why.","points":[{"t":"Glycerol molecules form more hydrogen bonds with each other (three O–H groups per molecule)","m":1},{"t":"The intermolecular attraction is stronger, so the molecules move past each other less easily","m":1}],"model":"Each glycerol molecule has three O–H groups and can form many hydrogen bonds with its neighbours, whereas an ethanol molecule has only one. The overall attraction between glycerol molecules is much greater, so they cannot move past each other easily and the liquid is more viscous."},
 {"id":"structure-w13","topic":"structure","type":"written","marks":2,"q":"Iodine dissolves in hexane but not in water. Explain why.","points":[{"t":"Iodine and hexane are both non-polar, so they can mix, forming London dispersion forces between the molecules","m":1},{"t":"Water is polar with hydrogen bonds between its molecules, which are much stronger than any forces with iodine, so iodine does not dissolve","m":1}],"model":"Iodine and hexane are both non-polar substances, so London dispersion forces between iodine and hexane molecules are similar in strength to those within each substance and they mix. Water is a polar liquid with strong hydrogen bonds between its molecules; iodine cannot form attractions strong enough to overcome these, so it is insoluble."},
 {"id":"structure-x01","topic":"structure","q":"In which compound is there hydrogen bonding between its molecules?","options":["CH₄","CH₃Cl","CH₃CH₃","CH₃OH"],"answer":3,"explanation":"Hydrogen bonding needs H bonded directly to F, O or N. Methanol has an O–H group."},
 {"id":"structure-x02","topic":"structure","q":"Which type of force is present in all substances, including noble gases?","options":["Hydrogen bonds","London dispersion forces","Permanent dipole–dipole interactions","Ionic bonds"],"answer":1,"explanation":"London dispersion forces act between all atoms and molecules and are the only forces between non-polar substances such as argon."},
 {"id":"structure-x03","topic":"structure","q":"Which of the following molecules is non-polar?","options":["CH₃Cl","HCl","H₂O","CCl₄"],"answer":3,"explanation":"The four polar C–Cl bonds in a tetrahedral CCl₄ molecule are arranged symmetrically, so their dipoles cancel."},
 {"id":"structure-x04","topic":"structure","q":"Which statement about the bonding continuum is correct?","options":["Pure covalent bonds have the greatest electronegativity difference","A greater electronegativity difference means a bond has more ionic character","All bonds between metals and non-metals are pure ionic","Polar covalent bonds have no electronegativity difference"],"answer":1,"explanation":"Bonds range from pure covalent (no difference) through polar covalent to ionic as the electronegativity difference increases."},
 {"id":"structure-x05","topic":"structure","q":"Why is the boiling point of HF much higher than that of HCl?","options":["HF molecules have more electrons","The H–F bond is weaker","HF is non-polar","Hydrogen bonding occurs between HF molecules"],"answer":3,"explanation":"Hydrogen bonds form between HF molecules (H bonded to F). HCl cannot form hydrogen bonds, so its intermolecular forces are weaker."},
 {"id":"redox-w01","topic":"redox","type":"written","marks":2,"q":"Explain what is meant by (a) an oxidising agent and (b) a reducing agent.","points":[{"t":"An oxidising agent accepts electrons (and so is itself reduced)","m":1},{"t":"A reducing agent donates (loses) electrons (and so is itself oxidised)","m":1}],"model":"(a) An oxidising agent takes electrons from another substance, causing it to be oxidised; the oxidising agent is itself reduced. (b) A reducing agent gives electrons to another substance, causing it to be reduced; the reducing agent is itself oxidised."},
 {"id":"redox-w02","topic":"redox","type":"written","marks":2,"q":"Complete the ion-electron equation for the reduction of permanganate ions in acid solution.\nMnO₄⁻ → Mn²⁺","points":[{"t":"4H₂O added to the right-hand side","m":1},{"t":"8H⁺ and 5e⁻ added to the left-hand side: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O","m":1}],"model":"Balance oxygen with water: MnO₄⁻ → Mn²⁺ + 4H₂O. Balance hydrogen with H⁺: MnO₄⁻ + 8H⁺ → Mn²⁺ + 4H₂O. Balance charge with electrons (+7 on the left, +2 on the right): MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O.","explanation":"Order: balance atoms other than O and H, then O with H₂O, then H with H⁺, then charge with e⁻."},
 {"id":"redox-w03","topic":"redox","type":"written","marks":2,"q":"Combine the ion-electron equations below to give the redox equation.\nFe²⁺ → Fe³⁺ + e⁻\nMnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O","points":[{"t":"The first equation is multiplied by 5 so that the electrons balance","m":1},{"t":"MnO₄⁻ + 8H⁺ + 5Fe²⁺ → Mn²⁺ + 4H₂O + 5Fe³⁺","m":1}],"model":"Multiply the oxidation half-equation by 5 so that five electrons are lost and five are gained: 5Fe²⁺ → 5Fe³⁺ + 5e⁻. Add the two equations and cancel the electrons: MnO₄⁻ + 8H⁺ + 5Fe²⁺ → Mn²⁺ + 4H₂O + 5Fe³⁺."},
 {"id":"redox-w04","topic":"redox","type":"written","marks":3,"q":"Acidified dichromate ions oxidise sulfite ions to sulfate ions.\nCr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O\nSO₃²⁻ + H₂O → SO₄²⁻ + 2H⁺ + 2e⁻\nCombine these ion-electron equations to give the overall redox equation.","points":[{"t":"The sulfite equation is multiplied by 3 so that six electrons are lost and six gained","m":1},{"t":"Equations added: Cr₂O₇²⁻ + 14H⁺ + 3SO₃²⁻ + 3H₂O → 2Cr³⁺ + 7H₂O + 3SO₄²⁻ + 6H⁺","m":1},{"t":"H⁺ and H₂O cancelled: Cr₂O₇²⁻ + 8H⁺ + 3SO₃²⁻ → 2Cr³⁺ + 4H₂O + 3SO₄²⁻","m":1}],"model":"Multiply the second equation by 3: 3SO₃²⁻ + 3H₂O → 3SO₄²⁻ + 6H⁺ + 6e⁻. Add it to the first equation and cancel the 6e⁻. Cancel 6H⁺ from the 14H⁺ on the left and 3H₂O from the 7H₂O on the right: Cr₂O₇²⁻ + 8H⁺ + 3SO₃²⁻ → 2Cr³⁺ + 4H₂O + 3SO₄²⁻."},
 {"id":"redox-w05","topic":"redox","type":"written","marks":2,"q":"Explain why Group 1 metals are strong reducing agents whereas the halogens are strong oxidising agents. Refer to electronegativity in your answer.","points":[{"t":"Group 1 metals have low electronegativities, so they lose electrons easily (and so act as reducing agents)","m":1},{"t":"Halogens have high electronegativities, so they gain electrons easily (and so act as oxidising agents)","m":1}],"model":"Group 1 metals have low electronegativity (low attraction for electrons) and a single outer electron that is easily lost, so they readily donate electrons and are strong reducing agents. The halogens have high electronegativity and strongly attract electrons, so they readily gain electrons and are strong oxidising agents."},
 {"id":"redox-w06","topic":"redox","type":"written","marks":3,"q":"Zinc is above copper in the electrochemical series. A piece of zinc is placed in copper(II) sulfate solution.\n(a) Will a reaction occur? Explain your answer. (1)\n(b) Write the ion-electron equations for the oxidation and the reduction that take place. (2)","points":[{"t":"Yes: zinc is a stronger reducing agent than copper (higher in the series), so it donates electrons to Cu²⁺ ions","m":1},{"t":"Oxidation: Zn → Zn²⁺ + 2e⁻","m":1},{"t":"Reduction: Cu²⁺ + 2e⁻ → Cu","m":1}],"model":"(a) Yes. Zinc is higher in the electrochemical series, so it is a stronger reducing agent and can give electrons to copper(II) ions, which are reduced to copper metal. (b) Oxidation: Zn → Zn²⁺ + 2e⁻. Reduction: Cu²⁺ + 2e⁻ → Cu. Overall: Zn + Cu²⁺ → Zn²⁺ + Cu."},
 {"id":"redox-w07","topic":"redox","type":"written","marks":3,"q":"Hydrogen peroxide acts as an oxidising agent in acid solution.\nH₂O₂ + 2H⁺ + 2e⁻ → 2H₂O\nIt oxidises iron(II) ions: Fe²⁺ → Fe³⁺ + e⁻\nWrite the redox equation for this reaction.","points":[{"t":"The iron(II) equation is multiplied by 2","m":1},{"t":"The equations are added and the electrons cancelled","m":1},{"t":"H₂O₂ + 2H⁺ + 2Fe²⁺ → 2H₂O + 2Fe³⁺","m":1}],"model":"Multiply the iron equation by 2 so that two electrons are lost: 2Fe²⁺ → 2Fe³⁺ + 2e⁻. Add this to the hydrogen peroxide equation and cancel the electrons: H₂O₂ + 2H⁺ + 2Fe²⁺ → 2H₂O + 2Fe³⁺."},
 {"id":"redox-w08","topic":"redox","type":"written","marks":2,"q":"Acidified potassium dichromate solution is added to an excess of iron(II) sulfate solution. State the colour change observed and identify the ion responsible for the final colour.","points":[{"t":"The colour changes from orange to green","m":1},{"t":"Cr³⁺ ions (formed when dichromate is reduced) are responsible for the green","m":1}],"model":"Dichromate ions (orange) are reduced to chromium(III) ions, Cr³⁺, which are green, while Fe²⁺ is oxidised to Fe³⁺. The observed change is therefore orange to green."},
 {"id":"redox-w09","topic":"redox","type":"written","marks":2,"q":"Explain why chlorine is added to water supplies and swimming pools.","points":[{"t":"Chlorine is an oxidising agent","m":1},{"t":"It kills bacteria (microorganisms) by oxidising them / making the water safe","m":1}],"model":"Chlorine is a powerful oxidising agent. It oxidises the chemicals in bacteria, fungi and viruses, killing or inactivating them, which makes drinking water and swimming pools safe."},
 {"id":"redox-w10","topic":"redox","type":"written","marks":3,"q":"Magnesium ribbon reacts with dilute hydrochloric acid.\n(a) Write the ion-electron equation for the oxidation. (1)\n(b) Write the ion-electron equation for the reduction. (1)\n(c) Write the overall redox equation. (1)","points":[{"t":"Mg → Mg²⁺ + 2e⁻","m":1},{"t":"2H⁺ + 2e⁻ → H₂","m":1},{"t":"Mg + 2H⁺ → Mg²⁺ + H₂","m":1}],"model":"(a) Magnesium loses electrons: Mg → Mg²⁺ + 2e⁻. (b) Hydrogen ions gain electrons: 2H⁺ + 2e⁻ → H₂. (c) Adding the two equations (electrons already balance): Mg + 2H⁺ → Mg²⁺ + H₂."},
 {"id":"redox-w11","topic":"redox","type":"written","marks":2,"q":"Chlorine reacts with potassium bromide solution.\nCl₂ + 2Br⁻ → 2Cl⁻ + Br₂\nName the oxidising agent and the reducing agent and explain your choices.","points":[{"t":"Oxidising agent is chlorine: it gains electrons (Cl₂ + 2e⁻ → 2Cl⁻)","m":1},{"t":"Reducing agent is the bromide ion: it loses electrons (2Br⁻ → Br₂ + 2e⁻)","m":1}],"model":"Chlorine gains electrons to form chloride ions (Cl₂ + 2e⁻ → 2Cl⁻), so it is reduced and is the oxidising agent. Bromide ions lose electrons to form bromine (2Br⁻ → Br₂ + 2e⁻), so they are oxidised and act as the reducing agent."},
 {"id":"redox-w12","topic":"redox","type":"written","marks":3,"q":"Chlorine displaces bromine from potassium bromide solution, but iodine does not displace bromine from potassium bromide solution. Explain this in terms of electronegativity and oxidising ability.","points":[{"t":"Electronegativity decreases down the group: Cl > Br > I","m":1},{"t":"Chlorine is a stronger oxidising agent than bromine (it attracts electrons more strongly) so it can take electrons from bromide ions","m":1},{"t":"Iodine is a weaker oxidising agent than bromine, so it cannot remove electrons from bromide ions","m":1}],"model":"Electronegativity falls down Group 7 (Cl > Br > I), so chlorine attracts electrons more strongly than bromine and is the stronger oxidising agent: it can oxidise bromide ions to bromine. Iodine has a lower electronegativity than bromine and is a weaker oxidising agent, so it cannot take electrons from bromide ions and no reaction occurs."},
 {"id":"redox-x01","topic":"redox","q":"Which of the following is the best description of reduction?","options":["Gain of electrons","Loss of electrons","Gain of hydrogen ions","Loss of protons"],"answer":0,"explanation":"Reduction is the gain of electrons; oxidation is the loss of electrons."},
 {"id":"redox-x02","topic":"redox","q":"Which ion-electron equation represents an oxidation?","options":["Cl₂ + 2e⁻ → 2Cl⁻","Cu²⁺ + 2e⁻ → Cu","Fe²⁺ → Fe³⁺ + e⁻","2H⁺ + 2e⁻ → H₂"],"answer":2,"explanation":"Oxidation is loss of electrons, so the electrons appear on the right-hand side: Fe²⁺ → Fe³⁺ + e⁻."},
 {"id":"redox-x03","topic":"redox","q":"In the reaction 2Mg + O₂ → 2MgO, which substance is the oxidising agent?","options":["Oxygen","Magnesium","Magnesium oxide","There is none, it is not a redox reaction"],"answer":0,"explanation":"Oxygen accepts electrons from magnesium (O₂ + 4e⁻ → 2O²⁻), so it is the oxidising agent."},
 {"id":"redox-x04","topic":"redox","q":"How many electrons are gained when one MnO₄⁻ ion is reduced to Mn²⁺ in acid solution?","options":["2","3","5","7"],"answer":2,"explanation":"MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O. Five electrons are gained."},
 {"id":"redox-x05","topic":"redox","q":"Which element is the strongest reducing agent?","options":["Sodium","Chlorine","Oxygen","Sulfur"],"answer":0,"explanation":"Sodium has a low electronegativity and loses its outer electron very easily, so it is a strong reducing agent. The others tend to gain electrons."},
 {"id":"rate-w14","topic":"rate","type":"written","marks":3,"q":"Using an energy distribution diagram, explain why adding a catalyst increases the rate of reaction at constant temperature.","points":[{"t":"The distribution of kinetic energies (the curve) is unchanged because the temperature is the same","m":1},{"t":"The catalyst provides an alternative pathway with a lower activation energy","m":1},{"t":"So a greater proportion of particles has energy equal to or greater than the new activation energy, and more collisions are successful","m":1}],"model":"At constant temperature the energy distribution curve does not change. The catalyst lowers the activation energy, so the activation energy marker moves to the left on the energy axis. The area under the curve to the right of the marker is larger, meaning more particles can react on collision and the rate increases."},
 {"id":"rate-w15","topic":"rate","type":"written","marks":2,"q":"(a) The mass of a reactant falls from 4.8 g to 3.0 g in 90 s. Calculate the average rate of reaction in g s⁻¹. (1)\n(b) The concentration of a reactant falls from 0.60 mol l⁻¹ to 0.36 mol l⁻¹ in 120 s. Calculate the average rate of reaction, with units. (1)","points":[{"t":"(a) Rate = (4.8 − 3.0) ÷ 90 = 0.020 g s⁻¹","m":1},{"t":"(b) Rate = (0.60 − 0.36) ÷ 120 = 0.0020 mol l⁻¹ s⁻¹","m":1}],"model":"Average rate = change in quantity ÷ time. (a) (4.8 − 3.0) ÷ 90 = 1.8 ÷ 90 = 0.020 g s⁻¹. (b) (0.60 − 0.36) ÷ 120 = 0.24 ÷ 120 = 0.0020 mol l⁻¹ s⁻¹."},
 {"id":"rate-w16","topic":"rate","type":"written","marks":2,"q":"Not every collision between reactant particles with energy greater than the activation energy results in a reaction. Explain why.","points":[{"t":"The particles must collide with the correct orientation (collision geometry) so that the bonds that break and form are brought together","m":1},{"t":"A collision with the wrong orientation will not react even if the energy is sufficient; both energy ≥ Ea and correct geometry are needed","m":1}],"model":"For a successful collision the particles need energy equal to or greater than the activation energy and they must also collide with the correct orientation. If the reacting parts of the particles do not meet, the bonds cannot rearrange and the particles simply bounce apart."},
 {"id":"rate-w17","topic":"rate","type":"written","marks":3,"q":"A forward reaction has an activation energy of 95 kJ mol⁻¹ and an enthalpy change of +30 kJ mol⁻¹.\n(a) State whether the forward reaction is exothermic or endothermic, and justify your answer. (1)\n(b) Calculate the activation energy for the reverse reaction. (1)\n(c) The activated complex is formed. State its energy relative to the reactants. (1)","points":[{"t":"Endothermic, because ΔH is positive (the products are at a higher enthalpy than the reactants)","m":1},{"t":"Ea (reverse) = 95 − 30 = 65 kJ mol⁻¹","m":1},{"t":"The activated complex is 95 kJ mol⁻¹ above the energy of the reactants","m":1}],"model":"(a) Endothermic: ΔH is positive, so the products have more enthalpy than the reactants. (b) The products lie 30 kJ mol⁻¹ above the reactants and the peak lies 95 kJ mol⁻¹ above the reactants, so the reverse reaction has to climb 95 − 30 = 65 kJ mol⁻¹. (c) The activated complex is at the top of the energy barrier, 95 kJ mol⁻¹ higher in energy than the reactants."},
 // batch figure questions
 {"id":"rate-w18","topic":"rate","type":"written","marks":4,"q":"The potential energy diagram below is for a reaction.\n(a) Calculate the activation energy for the forward reaction. (1)\n(b) Calculate the enthalpy change for the forward reaction and state whether it is exothermic or endothermic. (2)\n(c) Calculate the activation energy for the reverse reaction. (1)","points":[{"t":"(a) Ea (forward) = 140 − 40 = 100 kJ mol⁻¹","m":1},{"t":"(b) ΔH = 90 − 40 = +50 kJ mol⁻¹","m":1},{"t":"The reaction is endothermic (ΔH is positive)","m":1},{"t":"(c) Ea (reverse) = 140 − 90 = 50 kJ mol⁻¹","m":1}],"model":"(a) The activation energy is the height from reactants to the top of the barrier: 140 − 40 = 100 kJ mol⁻¹. (b) ΔH = enthalpy of products − enthalpy of reactants = 90 − 40 = +50 kJ mol⁻¹; the sign is positive so the reaction is endothermic. (c) The reverse reaction starts at the products, so Ea = 140 − 90 = 50 kJ mol⁻¹.","explanation":"Read each level from the energy axis, then subtract. Ea (forward) − Ea (reverse) = ΔH.","figure":{"src":"img/higher-profile-endo.svg","alt":"Potential energy diagram: a curve rises from a low energy plateau of reactants to a single peak, then falls to a product plateau that is higher than the reactants. The energy axis is marked every 20 kJ per mole.","caption":"Potential energy diagram"}},
 {"id":"rate-w19","topic":"rate","type":"written","marks":5,"q":"The diagram shows the potential energy profile for a reaction with and without a catalyst.\n(a) Calculate ΔH for the uncatalysed reaction. (1)\n(b) Calculate the activation energy of the forward reaction (i) without the catalyst and (ii) with the catalyst. (2)\n(c) Calculate the activation energy for the reverse reaction with the catalyst. (1)\n(d) State the effect of the catalyst on ΔH. (1)","points":[{"t":"(a) ΔH = 50 − 120 = −70 kJ mol⁻¹","m":1},{"t":"(b)(i) 190 − 120 = 70 kJ mol⁻¹","m":1},{"t":"(b)(ii) 155 − 120 = 35 kJ mol⁻¹","m":1},{"t":"(c) 155 − 50 = 105 kJ mol⁻¹","m":1},{"t":"(d) The catalyst has no effect on ΔH (the reactants and products are at the same energy)","m":1}],"model":"(a) ΔH = 50 − 120 = −70 kJ mol⁻¹ (exothermic). (b) Without catalyst Ea = 190 − 120 = 70 kJ mol⁻¹; with catalyst Ea = 155 − 120 = 35 kJ mol⁻¹. (c) The reverse reaction starts at the products: 155 − 50 = 105 kJ mol⁻¹. (d) A catalyst provides an alternative pathway with a lower activation energy but does not change the energies of the reactants and products, so ΔH is unchanged.","figure":{"src":"img/higher-profile-exo.svg","alt":"Potential energy diagram with two pathways from the same reactant level down to the same lower product level: a black curve with a high peak and a dashed orange curve labelled catalysed with a lower peak. The energy axis is marked every 20 kJ per mole.","caption":"Reaction with and without a catalyst"}},
 {"id":"rate-w20","topic":"rate","type":"written","marks":4,"q":"The graph shows the distribution of kinetic energies of the particles in a gas at two temperatures, T₁ and T₂. The activation energy is marked.\n(a) State which temperature is higher and explain how you can tell. (2)\n(b) Explain, using the graph, why the reaction is faster at the higher temperature. (2)","points":[{"t":"(a) T₂ is higher: the peak is lower and moved to the right (the curve is flatter and wider, with the same total area)","m":1},{"t":"The average kinetic energy of the particles is greater at T₂","m":1},{"t":"(b) The area under the curve beyond the activation energy is larger at T₂","m":1},{"t":"So a greater proportion (more) of the particles have energy equal to or greater than the activation energy, giving more successful collisions per second","m":1}],"model":"(a) The curve for T₂ has its maximum at a higher kinetic energy and is flatter, which means the particles have a higher average kinetic energy, so T₂ is the higher temperature. The total area under each curve (the total number of particles) is the same. (b) At T₂ the area to the right of the activation energy line is larger, so a greater proportion of the particles have at least the activation energy. More collisions are successful in a given time and the reaction is faster.","figure":{"src":"img/higher-energy-dist.svg","alt":"Two kinetic energy distribution curves sharing a vertical dotted line for activation energy: a taller blue curve labelled T1 peaking at low energy and a lower, flatter dashed orange curve labelled T2 peaking at higher energy with a longer tail.","caption":"Energy distribution at two temperatures"}},
 {"id":"rate-w21","topic":"rate","type":"written","marks":4,"q":"Magnesium carbonate reacts with excess acid and the volume of gas is measured. Three experiments A, B and C were carried out. The graph shows the results.\nIn experiment A the temperature was 25 °C and 0.50 mol l⁻¹ acid was used.\n(a) Calculate the average rate of reaction in experiment A over the first 20 seconds, in cm³ s⁻¹. (1)\n(b) Experiment B used the same mass of carbonate as A but the final volume is the same and the rate is lower. Suggest one change that could have been made. (1)\n(c) The curve for experiment C levels off at a lower volume. Suggest why. (1)\n(d) Explain why each curve becomes horizontal. (1)","points":[{"t":"(a) Rate = 40 ÷ 20 = 2.0 cm³ s⁻¹ (read the volume at 20 s as 40 cm³)","m":1},{"t":"(b) Any one of: lower temperature; lower concentration of acid; larger lumps (smaller surface area); no catalyst","m":1},{"t":"(c) A smaller mass (fewer moles) of the limiting reactant was used","m":1},{"t":"(d) The limiting reactant has been used up, so no more gas is produced","m":1}],"model":"(a) At 20 s experiment A has produced 40 cm³ of gas, so the average rate is 40 ÷ 20 = 2.0 cm³ s⁻¹. (b) B reaches the same final volume more slowly, so the reactants are the same amount but the rate is lower: lower temperature, lower acid concentration or larger particles of carbonate would all do this. (c) A lower final volume means less gas was produced, so less of the limiting reactant was present. (d) The curve becomes horizontal when the limiting reactant is used up.","explanation":"The final volume depends on the amount of limiting reactant; the steepness of the curve depends on the rate.","figure":{"src":"img/higher-gas-volume.svg","alt":"Line graph of volume of gas in cubic centimetres against time in seconds for three experiments A, B and C. A and B end at the same high volume but A rises faster; C rises quickly but ends at half that volume.","caption":"Gas volume against time"}},
 {"id":"periodicity-w13","topic":"periodicity","type":"written","marks":3,"q":"The bar chart shows the successive ionisation energies of element X.\n(a) State the group of the periodic table to which X belongs. (1)\n(b) Write the equation for the third ionisation energy of X. (1)\n(c) Explain why the fourth ionisation energy is much greater than the third. (1)","points":[{"t":"(a) Group 3 (there is a large jump after the third electron is removed)","m":1},{"t":"(b) X²⁺(g) → X³⁺(g) + e⁻","m":1},{"t":"(c) The fourth electron is removed from an inner shell (closer to the nucleus and less shielded) so is held much more strongly","m":1}],"model":"(a) The big increase between the third (2745) and fourth (11577) ionisation energies shows that there are three outer electrons, so X is in Group 3. (b) X²⁺(g) → X³⁺(g) + e⁻. (c) After three electrons have been removed the next electron comes from a full inner shell, which is closer to the nucleus and less screened, so much more energy is needed.","figure":{"src":"img/higher-successive-ie.svg","alt":"Bar chart of successive ionisation energies for eight electrons removed from one element. The bars rise gradually for the first three electrons, jump sharply at the fourth, and continue rising to the eighth.","caption":"Successive ionisation energies of element X"}},
 {"id":"structure-w14","topic":"structure","type":"written","marks":4,"q":"The graph shows the boiling points of the hydrides of Groups 4, 5, 6 and 7 plotted against the period of the element bonded to hydrogen.\n(a) Explain the trend in boiling point for the Group 4 hydrides. (2)\n(b) Explain why NH₃, H₂O and HF have much higher boiling points than the other hydrides in their groups. (2)","points":[{"t":"(a) Group 4 hydrides are non-polar; the only forces between molecules are London dispersion forces","m":1},{"t":"London dispersion forces get stronger as the molecules get larger (more electrons), so the boiling point rises down the group","m":1},{"t":"(b) NH₃, H₂O and HF molecules form hydrogen bonds (H bonded to N, O or F)","m":1},{"t":"Hydrogen bonds are stronger than the other intermolecular forces, so more energy is needed to separate the molecules","m":1}],"model":"(a) The Group 4 hydrides are symmetrical, non-polar molecules, so only London dispersion forces act between them. The molecules have more electrons down the group, so the dispersion forces are stronger and the boiling point rises. (b) Hydrogen is bonded to the very electronegative N, O and F in NH₃, H₂O and HF, so hydrogen bonds act between these molecules. Hydrogen bonds are much stronger than London dispersion forces or dipole–dipole interactions, so more energy is needed to boil them.","figure":{"src":"img/higher-hydride-bp.svg","alt":"Line graph of boiling points in degrees Celsius for four series of hydrides against the period of the element bonded to hydrogen. One series rises steadily from a very low value; three others fall sharply from period 2 to period 3 and then rise.","caption":"Boiling points of hydrides"}},
 {"id":"equilibria-w14","topic":"equilibria","type":"written","marks":5,"q":"Dinitrogen tetroxide forms an equilibrium mixture with nitrogen dioxide.\nN₂O₄(g) ⇌ 2NO₂(g)\nThe graph shows how the concentrations change after pure N₂O₄ is placed in a sealed container. A change is made to the system at 30 s.\n(a) Which curve, A or B, represents N₂O₄? Explain your choice. (2)\n(b) State how the graph shows that equilibrium has been reached before 30 s. (1)\n(c) After 30 s the equilibrium position shifts to the right. State one change that could cause this if the forward reaction is endothermic. (1)\n(d) Show that the changes in concentration after 30 s are consistent with the equation. (1)","points":[{"t":"(a) A: it starts at the initial concentration and falls (N₂O₄ is used up), while B starts at zero and rises","m":1},{"t":"B is NO₂ because 2 mol NO₂ form for each mol of N₂O₄ used","m":1},{"t":"(b) The concentrations are constant (horizontal lines) from about 25 s to 30 s","m":1},{"t":"(c) Increase in temperature (the equilibrium shifts in the endothermic direction)","m":1},{"t":"(d) A falls by 0.06 mol l⁻¹ while B rises by 0.12 mol l⁻¹: a 1 : 2 ratio, as in the equation","m":1}],"model":"(a) Curve A starts at 0.40 mol l⁻¹ and falls, so it is N₂O₄, the reactant. Curve B starts at zero and rises, so it is the product NO₂. (b) Both curves are horizontal between about 25 s and 30 s: the concentrations are constant, which means the rates of the forward and reverse reactions are equal. (c) Raising the temperature moves the equilibrium in the endothermic direction, which is to the right. (d) After 30 s A falls from 0.20 to 0.14 mol l⁻¹ (a fall of 0.06) while B rises from 0.40 to 0.52 mol l⁻¹ (a rise of 0.12). The ratio is 1 : 2, matching N₂O₄ ⇌ 2NO₂.","figure":{"src":"img/higher-equil-conc.svg","alt":"Line graph of concentration in moles per litre against time in seconds for two substances A and B. A falls from 0.40 and levels off near 0.20 while B rises from zero and levels off near 0.40. At 30 seconds both curves change slope again and settle at new values.","caption":"Concentration against time"}},
 // batch higher nc and rc additions
 {"id":"systematic-w01","topic":"systematic","type":"written","marks":3,"q":"Name the following compounds.\n(a) CH₃CH(CH₃)CH₂CH₃ (1)\n(b) CH₃CH=CHCH₂CH₃ (1)\n(c) CH₃CH₂CH(Cl)CH₃ (1)","points":[{"t":"(a) 2-methylbutane","m":1},{"t":"(b) pent-2-ene","m":1},{"t":"(c) 2-chlorobutane","m":1}],"model":"(a) The longest chain has four carbons (butane) with a methyl branch on carbon 2: 2-methylbutane. (b) A five-carbon chain with the double bond starting at carbon 2: pent-2-ene. (c) A four-carbon chain with chlorine on carbon 2: 2-chlorobutane."},
 {"id":"systematic-w02","topic":"systematic","type":"written","marks":2,"q":"Draw the structural formula of 2,3-dimethylbutane and state its molecular formula.","points":[{"t":"(CH₃)₂CH–CH(CH₃)₂ : a four-carbon chain with a methyl group on each of carbons 2 and 3","m":1},{"t":"Molecular formula is C₆H₁₄","m":1}],"model":"2,3-Dimethylbutane is CH₃CH(CH₃)CH(CH₃)CH₃: butane with a methyl group on each of carbons 2 and 3. It has six carbon atoms and, as an alkane, 2n+2 = 14 hydrogen atoms: C₆H₁₄."},
 {"id":"systematic-w03","topic":"systematic","type":"written","marks":3,"q":"Hex-1-ene reacts with bromine, with hydrogen and with water in the presence of an acid catalyst.\nName the type of reaction and the organic product for each reaction.","points":[{"t":"With bromine: addition (bromination), giving 1,2-dibromohexane","m":1},{"t":"With hydrogen: addition (hydrogenation), giving hexane","m":1},{"t":"With water: addition (hydration), giving hexan-2-ol (major) / an alcohol","m":1}],"model":"In each case the C=C bond breaks and two atoms or groups add across it. Bromine gives 1,2-dibromohexane, hydrogen gives hexane and water (acid catalyst) gives an alcohol, mainly hexan-2-ol."},
 {"id":"systematic-w04","topic":"systematic","type":"written","marks":2,"q":"Cyclohexene decolourises bromine solution quickly but cyclohexane does not. Explain this difference.","points":[{"t":"Cyclohexene is unsaturated: it contains a C=C double bond which bromine can add across","m":1},{"t":"Cyclohexane is saturated, with only single bonds, so there is no addition reaction and the bromine stays orange","m":1}],"model":"Cyclohexene has a carbon-to-carbon double bond, so bromine adds across it and the orange colour disappears. Cyclohexane is saturated and has no double bond for bromine to add to, so no rapid colour change occurs."},
 {"id":"systematic-w05","topic":"systematic","type":"written","marks":3,"q":"There are four structural isomers of formula C₄H₉Br.\nDraw (using full names or structural formulae) any three of them and name each.","points":[{"t":"1-bromobutane, CH₃CH₂CH₂CH₂Br","m":1},{"t":"2-bromobutane, CH₃CH₂CHBrCH₃","m":1},{"t":"1-bromo-2-methylpropane, (CH₃)₂CHCH₂Br (or 2-bromo-2-methylpropane, (CH₃)₃CBr)","m":1}],"model":"The four isomers are 1-bromobutane, 2-bromobutane, 1-bromo-2-methylpropane and 2-bromo-2-methylpropane. Isomers have the same molecular formula but different structural formulae."},
 {"id":"systematic-w06","topic":"systematic","type":"written","marks":3,"q":"A hydrocarbon has the formula C₅H₁₀ and decolourises bromine solution.\n(a) What does the decolourisation show about the structure? (1)\n(b) Name two possible structural isomers. (2)","points":[{"t":"(a) The molecule contains a C=C double bond (it is an alkene)","m":1},{"t":"(b) pent-1-ene","m":1},{"t":"pent-2-ene (also accept 2-methylbut-1-ene, 3-methylbut-1-ene or 2-methylbut-2-ene)","m":1}],"model":"(a) Alkenes contain a C=C bond and add bromine, so the bromine water is decolourised. (b) C₅H₁₀ fits the alkene formula CₙH₂ₙ. Possible isomers include pent-1-ene, pent-2-ene, 2-methylbut-1-ene, 3-methylbut-1-ene and 2-methylbut-2-ene."},
 {"id":"systematic-x01","topic":"systematic","q":"What is the name of CH₃CH₂CH(CH₃)CH(CH₃)CH₃?","options":["2-ethyl-3-methylbutane","3,4-dimethylpentane","2,3-dimethylhexane","2,3-dimethylpentane"],"answer":3,"explanation":"The longest continuous chain has five carbons. Numbering from the end giving the lowest numbers puts the two methyl groups on carbons 2 and 3."},
 {"id":"systematic-x02","topic":"systematic","q":"What is the molecular formula of cyclohexane?","options":["C₆H₁₄","C₆H₁₂","C₆H₁₀","C₆H₆"],"answer":1,"explanation":"A ring of six carbons has two hydrogens on each carbon, giving C₆H₁₂, two fewer hydrogens than the straight-chain alkane C₆H₁₄."},
 {"id":"systematic-x03","topic":"systematic","q":"Which pair of compounds are structural isomers?","options":["Ethanol and ethanoic acid","Propane and propene","Pentane and cyclopentane","Butan-1-ol and butan-2-ol"],"answer":3,"explanation":"Butan-1-ol and butan-2-ol both have the formula C₄H₁₀O but a different position for the hydroxyl group, so they are structural isomers."},
 {"id":"systematic-x04","topic":"systematic","q":"Which compound is formed when propene reacts with hydrogen bromide?","options":["Propane","2-bromopropane","Propan-2-ol","1,2-dibromopropane"],"answer":1,"explanation":"Hydrogen bromide adds across the C=C bond of propene to give a bromopropane; the other options need different reagents."},
 {"id":"systematic-x05","topic":"systematic","q":"Which statement about the addition of bromine to but-2-ene is correct?","options":["The product is 2-bromobutane","The product is 1,4-dibromobutane","A hydrogen atom is substituted by bromine","The product is 2,3-dibromobutane"],"answer":3,"explanation":"Bromine adds across the double bond between carbons 2 and 3, giving 2,3-dibromobutane. It is addition, not substitution."},
 {"id":"systematic-x06","topic":"systematic","q":"What is the general formula of the alkenes?","options":["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₂ₙ₋₂","CₙHₙ"],"answer":1,"explanation":"Alkenes with one double bond have two fewer hydrogens than the alkane with the same carbon number, giving CₙH₂ₙ."},
 {"id":"systematic-x07","topic":"systematic","q":"A compound has the structure CH₃CH₂C(CH₃)₂CH₂CH₃. How many carbon atoms are in its longest chain?","options":["4","6","7","5"],"answer":3,"explanation":"The longest continuous chain contains five carbon atoms (pentane) with two methyl branches on carbon 3: 3,3-dimethylpentane."},
 {"id":"alcohols-w01","topic":"alcohols","type":"written","marks":3,"q":"Butan-1-ol, butan-2-ol and 2-methylpropan-2-ol are three isomeric alcohols.\n(a) Classify each as primary, secondary or tertiary. (1)\n(b) Name the type of compound produced when each is oxidised, if oxidation occurs. (2)","points":[{"t":"(a) Butan-1-ol: primary; butan-2-ol: secondary; 2-methylpropan-2-ol: tertiary","m":1},{"t":"(b) Butan-1-ol is oxidised to an aldehyde (butanal), then to a carboxylic acid (butanoic acid)","m":1},{"t":"Butan-2-ol is oxidised to a ketone (butanone); 2-methylpropan-2-ol is not oxidised","m":1}],"model":"(a) The classification depends on the number of carbon atoms attached to the carbon bearing the –OH group. (b) Primary alcohols oxidise to aldehydes and then carboxylic acids, secondary alcohols oxidise to ketones, and tertiary alcohols are not oxidised."},
 {"id":"alcohols-w02","topic":"alcohols","type":"written","marks":3,"q":"Describe a chemical test, with the result in each case, that would distinguish between propanal and propanone.","points":[{"t":"Add Fehling's solution (or Benedict's) to each and warm","m":1},{"t":"Propanal (an aldehyde) is oxidised: the blue solution turns brick-red / orange precipitate","m":1},{"t":"Propanone (a ketone) is not oxidised: the solution stays blue","m":1}],"model":"Aldehydes are oxidised by warm Fehling's solution so the copper(II) is reduced and the blue solution forms a brick-red precipitate of copper(I) oxide. Ketones are not oxidised, so the solution stays blue. Tollens' reagent (silver mirror for the aldehyde only) would also work."},
 {"id":"alcohols-w03","topic":"alcohols","type":"written","marks":3,"q":"Pentan-2-ol is warmed with acidified potassium dichromate solution.\n(a) State the colour change seen. (1)\n(b) Name the organic product. (1)\n(c) What is the change in the oxidation state of chromium? (1)","points":[{"t":"(a) Orange to green (blue-green)","m":1},{"t":"(b) Pentan-2-one (a ketone)","m":1},{"t":"(c) Cr is reduced from +6 (in Cr₂O₇²⁻) to +3 (Cr³⁺)","m":1}],"model":"The dichromate ion (orange) is reduced to Cr³⁺ (green) while the secondary alcohol is oxidised to the ketone pentan-2-one. Chromium goes from +6 to +3."},
 {"id":"alcohols-w04","topic":"alcohols","type":"written","marks":2,"q":"Describe what happens in terms of the movement of electrons when an alcohol is oxidised by hot copper(II) oxide.","points":[{"t":"The alcohol loses hydrogen (and electrons): it is oxidised","m":1},{"t":"Copper(II) oxide gains electrons: it is reduced, black copper(II) oxide turning to brown copper","m":1}],"model":"Oxidation of an alcohol involves loss of hydrogen. Copper(II) oxide is the oxidising agent and is itself reduced to copper metal, a colour change from black to brown/pink."},
 {"id":"alcohols-w05","topic":"alcohols","type":"written","marks":3,"q":"Ethanol can be made from ethene or by fermentation of glucose.\n(a) Write the balanced equation for fermentation of glucose to ethanol. (1)\n(b) Calculate the mass of ethanol obtained from 90 g of glucose if the yield is 80 %. (2)","points":[{"t":"(a) C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂","m":1},{"t":"(b) 90 g = 0.50 mol glucose gives 1.0 mol ethanol = 46 g theoretically","m":1},{"t":"Actual mass = 80 % × 46 = 36.8 g","m":1}],"model":"(a) C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. (b) Moles of glucose = 90 ÷ 180 = 0.50 mol, which would give 1.0 mol of ethanol = 46 g. At 80 % yield the mass = 0.80 × 46 = 36.8 g."},
 {"id":"alcohols-w06","topic":"alcohols","type":"written","marks":2,"q":"Explain why ethanol has a much higher boiling point than ethane although their molecules have similar sizes.","points":[{"t":"Ethanol molecules form hydrogen bonds between –OH groups (stronger than the London dispersion forces in ethane)","m":1},{"t":"More energy is needed to separate ethanol molecules","m":1}],"model":"Ethanol has a polar O–H group and forms hydrogen bonds, which are stronger than the London dispersion forces between ethane molecules. More energy is therefore needed to separate the molecules and the boiling point is higher."},
 {"id":"alcohols-x01","topic":"alcohols","q":"Which compound is formed by the oxidation of propan-1-ol using excess acidified dichromate?","options":["Propanone","Propanoic acid","Propanal","Propene"],"answer":1,"explanation":"A primary alcohol is oxidised first to an aldehyde and then, with excess oxidising agent, to the carboxylic acid, propanoic acid."},
 {"id":"alcohols-x02","topic":"alcohols","q":"An unknown alcohol is not oxidised by acidified dichromate. What type of alcohol is it?","options":["Primary","Secondary","Aromatic","Tertiary"],"answer":3,"explanation":"Tertiary alcohols have no hydrogen on the carbon bearing the –OH group, so they cannot be oxidised under these conditions."},
 {"id":"alcohols-x03","topic":"alcohols","q":"With Tollens' reagent, which compound forms a silver mirror?","options":["Ethanol","Ethanal","Propanone","Ethane"],"answer":1,"explanation":"Aldehydes are oxidised by Tollens' reagent to carboxylic acids while silver ions are reduced to silver metal, forming the mirror."},
 {"id":"alcohols-x04","topic":"alcohols","q":"Which type of reaction converts ethene into ethanol?","options":["Substitution","Condensation","Oxidation","Addition (hydration)"],"answer":3,"explanation":"Water adds across the double bond in the presence of an acid catalyst, giving ethanol."},
 {"id":"alcohols-x05","topic":"alcohols","q":"How many different alcohols (including all positional isomers) have the molecular formula C₄H₁₀O?","options":["2","4","3","5"],"answer":1,"explanation":"Butan-1-ol, butan-2-ol, 2-methylpropan-1-ol and 2-methylpropan-2-ol are the four isomeric alcohols of formula C₄H₁₀O."},
 {"id":"acids-c-w01","topic":"acids-c","type":"written","marks":3,"q":"Ethanoic acid reacts with magnesium, with sodium hydroxide and with sodium carbonate.\nWrite the names of the salt formed and the other product, if any, in each case.","points":[{"t":"Magnesium: magnesium ethanoate and hydrogen","m":1},{"t":"Sodium hydroxide: sodium ethanoate and water","m":1},{"t":"Sodium carbonate: sodium ethanoate, water and carbon dioxide","m":1}],"model":"Ethanoic acid shows typical acid reactions. A metal gives a salt and hydrogen, a base (hydroxide) gives a salt and water, and a carbonate gives a salt, water and carbon dioxide."},
 {"id":"acids-c-w02","topic":"acids-c","type":"written","marks":2,"q":"Calculate the mass of sodium ethanoate formed when 3.0 g of ethanoic acid is neutralised completely with sodium hydroxide. (GFM ethanoic acid = 60; sodium ethanoate = 82)","points":[{"t":"3.0 ÷ 60 = 0.050 mol of ethanoic acid, which gives 0.050 mol of salt","m":1},{"t":"Mass = 0.050 × 82 = 4.1 g","m":1}],"model":"CH₃COOH + NaOH → CH₃COONa + H₂O, so the mole ratio is 1 : 1. Moles = 3.0 ÷ 60 = 0.050 mol and mass of sodium ethanoate = 0.050 × 82 = 4.1 g."},
 {"id":"acids-c-w03","topic":"acids-c","type":"written","marks":2,"q":"Explain why ethanoic acid is a weak acid but hydrochloric acid of the same concentration is a strong acid.","points":[{"t":"Hydrochloric acid ionises completely in water, whereas ethanoic acid is only partly ionised (an equilibrium)","m":1},{"t":"So ethanoic acid has a lower hydrogen ion concentration (a higher pH)","m":1}],"model":"Hydrochloric acid is fully ionised, giving a high concentration of H⁺ ions. Ethanoic acid is only slightly ionised (CH₃COOH ⇌ CH₃COO⁻ + H⁺), so its solution has a lower H⁺ concentration and a higher pH."},
 {"id":"acids-c-w04","topic":"acids-c","type":"written","marks":2,"q":"Explain why carboxylic acids generally have higher boiling points than alcohols of similar molecular mass.","points":[{"t":"Carboxylic acid molecules form stronger / more extensive hydrogen bonds (pairs of molecules, dimers)","m":1},{"t":"More energy is needed to overcome the forces between acid molecules","m":1}],"model":"Carboxylic acids contain both a C=O and an O–H group and can form strong hydrogen bonds, often joining in pairs. The intermolecular forces are stronger than in alcohols of similar mass, so the boiling points are higher."},
 {"id":"acids-c-x01","topic":"acids-c","q":"Which is the formula of the salt formed when methanoic acid reacts with potassium hydroxide?","options":["CH₃COOK","HCOOH","KCOOH₂","HCOOK"],"answer":3,"explanation":"Methanoic acid, HCOOH, loses its acidic hydrogen to form potassium methanoate, HCOOK, and water."},
 {"id":"acids-c-x02","topic":"acids-c","q":"What is the name of CH₃CH₂CH(CH₃)COOH?","options":["3-methylbutanoic acid","2-methylbutanoic acid","2-ethylpropanoic acid","pentanoic acid"],"answer":1,"explanation":"The carboxyl carbon is carbon 1; the longest chain including it has four carbons, with a methyl group on carbon 2."},
 {"id":"acids-c-x03","topic":"acids-c","q":"Which gas is released when a carboxylic acid reacts with sodium carbonate?","options":["Hydrogen","Oxygen","Carbon monoxide","Carbon dioxide"],"answer":3,"explanation":"Carbonates react with acids to give a salt, water and carbon dioxide, which turns limewater milky."},
 {"id":"acids-c-x04","topic":"acids-c","q":"What is the pH of a 0.001 mol l⁻¹ solution of nitric acid, a strong monoprotic acid?","options":["1","3","0.001","11"],"answer":1,"explanation":"Nitric acid is fully ionised so [H⁺] = 0.001 = 10⁻³ mol l⁻¹, giving pH = −log(0.001) = 3."},
 {"id":"acids-c-x05","topic":"acids-c","q":"Which statement about 0.1 mol l⁻¹ ethanoic acid and 0.1 mol l⁻¹ hydrochloric acid is true?","options":["They have the same pH","Ethanoic acid has the lower pH","They have the same conductivity","The hydrochloric acid has the lower pH"],"answer":3,"explanation":"Both have the same concentration, but hydrochloric acid is fully ionised giving a higher [H⁺] and lower pH."},
 {"id":"esters-w01","topic":"esters","type":"written","marks":3,"q":"Butanoic acid reacts with methanol in the presence of concentrated sulfuric acid.\n(a) Name the type of reaction. (1)\n(b) Name the ester formed. (1)\n(c) What is the function of the concentrated sulfuric acid? (1)","points":[{"t":"(a) Condensation (esterification)","m":1},{"t":"(b) Methyl butanoate","m":1},{"t":"(c) It acts as a catalyst (it also removes water)","m":1}],"model":"(a) The acid and alcohol join with the loss of a water molecule, so it is a condensation reaction. (b) The ester is named alkyl (from the alcohol) + alkanoate (from the acid): methyl butanoate. (c) Concentrated sulfuric acid is the catalyst."},
 {"id":"esters-w02","topic":"esters","type":"written","marks":3,"q":"An ester has the structure CH₃CH₂COOCH₂CH₂CH₃.\n(a) Name the ester. (1)\n(b) Name the alcohol and the carboxylic acid that would be formed by hydrolysis. (2)","points":[{"t":"(a) Propyl propanoate","m":1},{"t":"(b) Propan-1-ol","m":1},{"t":"Propanoic acid","m":1}],"model":"The ester link –COO– joins the acid part (CH₃CH₂CO–, from propanoic acid) with the alcohol part (–CH₂CH₂CH₃, from propan-1-ol). The name is propyl propanoate; hydrolysis gives the acid and the alcohol back."},
 {"id":"esters-w03","topic":"esters","type":"written","marks":3,"q":"4.6 g of ethanol is reacted with an excess of ethanoic acid to make ethyl ethanoate. The actual mass of ester obtained was 6.6 g.\nCalculate the percentage yield. (GFM ethanol = 46; ethyl ethanoate = 88)","points":[{"t":"Moles of ethanol = 4.6 ÷ 46 = 0.10 mol","m":1},{"t":"Theoretical mass of ester = 0.10 × 88 = 8.8 g","m":1},{"t":"Percentage yield = 6.6 ÷ 8.8 × 100 = 75 %","m":1}],"model":"CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O, giving 1 mol ester per mol ethanol. Theoretical yield = 0.10 × 88 = 8.8 g, so % yield = 6.6 ÷ 8.8 × 100 = 75 %."},
 {"id":"esters-w04","topic":"esters","type":"written","marks":2,"q":"Esters such as ethyl ethanoate are widely used as solvents and flavourings. Explain why esters are suitable as flavourings.","points":[{"t":"Esters are volatile (low boiling points) and so can be smelled","m":1},{"t":"Many esters have pleasant fruity smells","m":1}],"model":"Esters are volatile because they cannot form hydrogen bonds with each other, so their molecules readily escape as vapour and are detected by smell. Many have pleasant, fruity odours."},
 {"id":"esters-w05","topic":"esters","type":"written","marks":2,"q":"Explain why esters have lower boiling points than carboxylic acids of similar molecular mass.","points":[{"t":"Esters have no –OH group so cannot form hydrogen bonds between their molecules","m":1},{"t":"Only weaker (dipole–dipole / dispersion) forces must be overcome","m":1}],"model":"Carboxylic acids form strong hydrogen bonds, but esters have no O–H and so only weaker forces act between their molecules. Less energy is needed to boil an ester."},
 {"id":"esters-x01","topic":"esters","q":"Which pair of compounds is used to make methyl ethanoate?","options":["Methanoic acid and ethanol","Ethanol and methanol","Ethanoic acid and ethanol","Ethanoic acid and methanol"],"answer":3,"explanation":"The name alkyl alkanoate means methyl from methanol and ethanoate from ethanoic acid."},
 {"id":"esters-x02","topic":"esters","q":"What is the functional group of an ester?","options":["–CO–","–COO–","–OH","–CHO"],"answer":1,"explanation":"An ester contains the ester link, a carbonyl carbon bonded to a second oxygen that is joined to an alkyl group, –COO–."},
 {"id":"esters-x03","topic":"esters","q":"How many water molecules are produced when one molecule of propane-1,2,3-triol reacts fully with three ethanoic acid molecules?","options":["1","2","6","3"],"answer":3,"explanation":"Each of the three –OH groups forms an ester link with one acid molecule, releasing one water per link."},
 {"id":"esters-x04","topic":"esters","q":"Alkaline hydrolysis of an ester with sodium hydroxide gives which products?","options":["A carboxylic acid and an alcohol","An alcohol and the sodium salt of the carboxylic acid","An aldehyde and water","Two alcohols"],"answer":1,"explanation":"With sodium hydroxide, the carboxylic acid formed is neutralised, so the sodium carboxylate salt is obtained along with the alcohol."},
 {"id":"fats-w01","topic":"fats","type":"written","marks":3,"q":"A triglyceride in a fat is formed from propane-1,2,3-triol and fatty acids.\n(a) How many ester links are in one triglyceride molecule? (1)\n(b) Why do vegetable oils generally have lower melting points than animal fats? (2)","points":[{"t":"(a) Three ester links","m":1},{"t":"(b) Oils contain more unsaturated (C=C) fatty acid chains, which are kinked and cannot pack closely together","m":1},{"t":"So the intermolecular (London dispersion) forces are weaker and less energy is needed to melt them","m":1}],"model":"(a) Glycerol has three –OH groups, each forming an ester link with a fatty acid. (b) The C=C bonds in unsaturated chains cause bends, so the molecules cannot pack tightly. This gives weaker London dispersion forces and a lower melting point."},
 {"id":"fats-w02","topic":"fats","type":"written","marks":3,"q":"Glyceryl trioleate (triolein) has the formula C₅₇H₁₀₄O₆ (GFM = 884) and contains three C=C bonds.\nCalculate the volume of hydrogen, in cm³, needed to hydrogenate 8.84 g completely. (1 mol of gas occupies 24 l)","points":[{"t":"Moles of triolein = 8.84 ÷ 884 = 0.0100 mol","m":1},{"t":"3 mol H₂ are needed per mole: 0.0300 mol H₂","m":1},{"t":"Volume = 0.0300 × 24 = 0.72 l = 720 cm³","m":1}],"model":"Each of the three C=C bonds adds one H₂. Moles of fat = 8.84 ÷ 884 = 0.0100 mol so moles of H₂ = 0.0300 mol. Volume = 0.0300 × 24 = 0.72 l = 720 cm³."},
 {"id":"fats-w03","topic":"fats","type":"written","marks":2,"q":"Linoleic acid (C₁₇H₃₁COOH, GFM = 280) contains two C=C bonds. Calculate the mass of iodine (I₂ = 254) that would react with 28.0 g of linoleic acid.","points":[{"t":"Moles of acid = 28.0 ÷ 280 = 0.100 mol, which reacts with 0.200 mol I₂","m":1},{"t":"Mass of iodine = 0.200 × 254 = 50.8 g","m":1}],"model":"Each C=C bond reacts with one I₂ molecule, so 0.100 mol of linoleic acid reacts with 0.200 mol I₂. Mass = 0.200 × 254 = 50.8 g."},
 {"id":"fats-w04","topic":"fats","type":"written","marks":2,"q":"Partial hydrogenation of vegetable oils is used in making margarine. Why are the oils hydrogenated, and why only partially?","points":[{"t":"Hydrogenation reduces the number of C=C bonds, raising the melting point so the product is a solid / spreadable","m":1},{"t":"Partial: to keep it soft (spreadable) and retain some unsaturated fatty acids","m":1}],"model":"Adding hydrogen to C=C bonds makes the chains straighter so they pack more closely and the melting point rises, turning the oil into a soft solid. Complete hydrogenation would give a hard fat, so only some bonds are hydrogenated."},
 {"id":"fats-w05","topic":"fats","type":"written","marks":2,"q":"What are essential fatty acids, and why must they be obtained from the diet?","points":[{"t":"Fatty acids that are required for health (e.g. omega-3 and omega-6)","m":1},{"t":"The body cannot make them, so they must be supplied by food","m":1}],"model":"Essential fatty acids such as linoleic acid cannot be made by the human body in sufficient amounts, so they have to be included in the diet."},
 {"id":"fats-x01","topic":"fats","q":"Which statement about an oil, compared with a fat, is correct?","options":["It has stronger intermolecular forces","It contains a greater proportion of unsaturated fatty acid chains","It has no ester links","It has a higher melting point"],"answer":1,"explanation":"Oils are richer in unsaturated, kinked chains. These pack less well, giving weaker forces and lower melting points."},
 {"id":"fats-x02","topic":"fats","q":"What products form when a fat is completely hydrolysed?","options":["Ethane-1,2-diol and fatty acids","Propan-1-ol and esters","Glucose and water","Propane-1,2,3-triol and fatty acids"],"answer":3,"explanation":"Hydrolysis of the three ester links in a triglyceride regenerates the glycerol (propane-1,2,3-triol) and three fatty acid molecules."},
 {"id":"fats-x03","topic":"fats","q":"Which of the following is a fatty acid that is unsaturated?","options":["C₁₇H₃₅COOH","C₁₇H₃₃COOH","C₁₅H₃₁COOH","C₁₃H₂₇COOH"],"answer":1,"explanation":"A saturated fatty acid with 18 carbons is C₁₇H₃₅COOH. C₁₇H₃₃COOH has two fewer hydrogens, so contains one C=C bond."},
 {"id":"fats-x04","topic":"fats","q":"What happens to the iodine number of an oil as it is partially hydrogenated?","options":["It increases","It stays the same","It becomes zero immediately","It decreases"],"answer":3,"explanation":"The iodine number measures the mass of iodine that adds across C=C bonds. Hydrogenation removes C=C bonds so less iodine reacts."},
 {"id":"soaps-w01","topic":"soaps","type":"written","marks":3,"q":"A soap is made by heating a fat with sodium hydroxide solution.\n(a) Name the type of reaction. (1)\n(b) Name the two types of product. (2)","points":[{"t":"(a) Hydrolysis (saponification)","m":1},{"t":"(b) Propane-1,2,3-triol (glycerol)","m":1},{"t":"Sodium salts of fatty acids (soap)","m":1}],"model":"(a) Alkaline hydrolysis of the ester links in the fat is called saponification. (b) The products are propane-1,2,3-triol and three sodium carboxylate salts (soap)."},
 {"id":"soaps-w02","topic":"soaps","type":"written","marks":3,"q":"Explain how a soap removes grease from a dirty plate.","points":[{"t":"The soap ion has a hydrophobic (non-polar hydrocarbon) tail that dissolves in the grease","m":1},{"t":"and a hydrophilic (ionic carboxylate) head that is attracted to water","m":1},{"t":"The grease is surrounded by soap ions forming micelles, which are lifted off and dispersed in the water","m":1}],"model":"The tails of soap ions dissolve in the grease droplet and the charged heads point outwards into the water. The grease is surrounded by negatively charged heads, forming micelles that repel one another and remain dispersed in the water so the grease is rinsed away."},
 {"id":"soaps-w03","topic":"soaps","type":"written","marks":2,"q":"Soap forms a scum in hard water but a detergent does not. Explain why.","points":[{"t":"Hard water contains Ca²⁺ / Mg²⁺ ions which react with soap ions to form an insoluble scum","m":1},{"t":"Detergent ions form soluble compounds with Ca²⁺/Mg²⁺ (no scum)","m":1}],"model":"Calcium and magnesium ions in hard water form insoluble precipitates with soap ions (scum), using up soap. Synthetic detergents form soluble salts with these ions, so lather is formed and no scum."},
 {"id":"soaps-w04","topic":"soaps","type":"written","marks":2,"q":"Explain why a soap is described as an emulsifier when used in a mixture of oil and water.","points":[{"t":"An emulsifier has a hydrophobic and a hydrophilic part","m":1},{"t":"It allows oil droplets to be dispersed throughout water without separating","m":1}],"model":"Soap ions have an oil-soluble tail and a water-soluble head, so they coat tiny oil droplets and keep them suspended in water as an emulsion."},
 {"id":"soaps-x01","topic":"soaps","q":"Which part of a soap ion is hydrophilic?","options":["The long hydrocarbon tail","The carboxylate head","The entire ion","The double bond"],"answer":1,"explanation":"The ionic –COO⁻ head is attracted to water molecules (hydrophilic), while the hydrocarbon tail is hydrophobic."},
 {"id":"soaps-x02","topic":"soaps","q":"A soap is made from stearic acid, C₁₇H₃₅COOH. What is the formula of the soap ion?","options":["C₁₇H₃₅COOH₂⁺","C₁₇H₃₅CO⁺","C₁₈H₃₇O⁻","C₁₇H₃₅COO⁻"],"answer":3,"explanation":"A soap ion forms when the carboxylic acid group loses its hydrogen ion to give the carboxylate ion C₁₇H₃₅COO⁻."},
 {"id":"soaps-x03","topic":"soaps","q":"Calculate the mass of sodium hydroxide (GFM = 40) required to react completely with 8.84 g of a triglyceride (GFM = 884).","options":["0.40 g","1.2 g","3.6 g","12 g"],"answer":1,"explanation":"Moles of fat = 0.0100; three ester links per fat means 0.0300 mol NaOH, giving 0.0300 × 40 = 1.2 g."},
 {"id":"soaps-x04","topic":"soaps","q":"What is a micelle?","options":["A single soap ion in solution","An insoluble calcium soap","A layer of oil on water","A ball of soap ions with tails pointing inwards and heads outwards"],"answer":3,"explanation":"Micelles have the hydrocarbon tails together in the middle (trapping grease) and the ionic heads on the outside in contact with water."},
 {"id":"proteins-w01","topic":"proteins","type":"written","marks":3,"q":"Glycine (H₂NCH₂COOH) and alanine (H₂NCH(CH₃)COOH) join to form a dipeptide.\n(a) Name the type of reaction. (1)\n(b) Draw or describe the peptide link formed. (1)\n(c) Calculate the GFM of the dipeptide. (GFM glycine = 75; alanine = 89) (1)","points":[{"t":"(a) Condensation (a water molecule is lost)","m":1},{"t":"(b) –CONH– (amide link between the C=O of one acid and the N–H of the other)","m":1},{"t":"(c) 75 + 89 − 18 = 146","m":1}],"model":"(a) A molecule of water is eliminated when the –COOH of one amino acid reacts with the –NH₂ of the other. (b) The new link is the peptide (amide) link, –CONH–. (c) GFM = 75 + 89 − 18 = 146."},
 {"id":"proteins-w02","topic":"proteins","type":"written","marks":3,"q":"A protein is hydrolysed completely to give amino acids.\n(a) Explain what happens to the protein during hydrolysis. (2)\n(b) How many water molecules are needed to hydrolyse a chain of 8 amino acids? (1)","points":[{"t":"(a) Water is added across the peptide links, breaking the C–N bonds","m":1},{"t":"giving the individual amino acids (each with free –NH₂ and –COOH groups)","m":1},{"t":"(b) 7 water molecules, one per peptide link","m":1}],"model":"(a) Hydrolysis breaks each peptide link with the addition of one molecule of water, producing the amino acids. (b) A chain of 8 amino acids has 7 peptide links so needs 7 water molecules."},
 {"id":"proteins-w03","topic":"proteins","type":"written","marks":3,"q":"Heating an egg white changes its appearance irreversibly.\n(a) What is the term for this change in the protein? (1)\n(b) Explain what happens to the protein structure. (2)","points":[{"t":"(a) Denaturation","m":1},{"t":"(b) The weak bonds (hydrogen bonds / interactions) holding the protein's 3-D shape are broken","m":1},{"t":"The protein unfolds, changing its shape; the peptide links are not broken","m":1}],"model":"(a) The change is called denaturation. (b) Heat breaks the hydrogen bonds and other weak interactions that hold the folded shape. The chain unfolds and shape changes, but the strong peptide links remain intact."},
 {"id":"proteins-w04","topic":"proteins","type":"written","marks":2,"q":"Enzymes are protein molecules that act as catalysts. Explain why an enzyme stops working if the temperature is too high.","points":[{"t":"The high temperature denatures the enzyme by breaking weak bonds that hold its shape","m":1},{"t":"The active site changes shape, so the substrate can no longer bind","m":1}],"model":"Enzyme action depends on a precise active site. At high temperatures the enzyme's shape is lost (denaturation), so the substrate no longer fits and the reaction is not catalysed."},
 {"id":"proteins-x01","topic":"proteins","q":"How many different tripeptides can be made from one molecule each of three different amino acids?","options":["3","6","9","27"],"answer":1,"explanation":"There are 3 × 2 × 1 = 6 different sequences possible for three different amino acids in a chain."},
 {"id":"proteins-x02","topic":"proteins","q":"What are the products of complete hydrolysis of a tripeptide?","options":["Two amino acid molecules","One amino acid molecule and water","Three water molecules","Three amino acid molecules"],"answer":3,"explanation":"Hydrolysis breaks both peptide links, releasing the three amino acids that formed the tripeptide."},
 {"id":"proteins-x03","topic":"proteins","q":"What is an essential amino acid?","options":["One that is found only in enzymes","One that cannot be made by the body and must be obtained from the diet","One that contains no carbon","One that is always acidic"],"answer":1,"explanation":"Essential amino acids have to be taken in as food because the body cannot synthesise them."},
 {"id":"proteins-x04","topic":"proteins","q":"Which functional groups are present in every amino acid?","options":["Hydroxyl and ester groups","Aldehyde and amine groups","Carbonyl and hydroxyl groups","Amine and carboxyl groups"],"answer":3,"explanation":"An amino acid has an amino (–NH₂) group and a carboxyl (–COOH) group, which form the peptide link on condensation."},
 {"id":"proteins-x05","topic":"proteins","q":"The amine of one amino acid and the carboxyl group of another react. Which small molecule is released?","options":["Ammonia","Water","Carbon dioxide","Hydrogen"],"answer":1,"explanation":"A condensation reaction forms the peptide link and releases a molecule of water."},
 {"id":"oxfood-w01","topic":"oxfood","type":"written","marks":3,"q":"Vitamin C (ascorbic acid) is used as an antioxidant in food.\n(a) Explain how an antioxidant protects a food. (1)\n(b) The ion-electron equation for ascorbic acid is C₆H₈O₆ → C₆H₆O₆ + 2H⁺ + 2e⁻. Is ascorbic acid acting as an oxidising agent or a reducing agent? Explain. (2)","points":[{"t":"(a) It is oxidised in preference to the food, so reacts with oxygen / free radicals instead of the food","m":1},{"t":"(b) Reducing agent","m":1},{"t":"It loses electrons (is oxidised), so it reduces other species","m":1}],"model":"(a) Antioxidants are more easily oxidised than the food, so they react with oxygen first. (b) Ascorbic acid loses electrons in the equation, so it is oxidised and therefore acts as a reducing agent."},
 {"id":"oxfood-w02","topic":"oxfood","type":"written","marks":4,"q":"A vitamin C tablet was dissolved and made up to 250 cm³ in a standard flask. 25.0 cm³ portions required an average of 20.0 cm³ of 0.0050 mol l⁻¹ iodine solution. The reaction is C₆H₈O₆ + I₂ → C₆H₆O₆ + 2HI.\n(a) Calculate the moles of iodine in the average titre. (1)\n(b) Calculate the mass of vitamin C (GFM = 176) in the tablet. (3)","points":[{"t":"(a) n = 0.0050 × 0.0200 = 1.0 × 10⁻⁴ mol","m":1},{"t":"(b) 1 : 1 ratio, so 1.0 × 10⁻⁴ mol vitamin C in 25.0 cm³","m":1},{"t":"In 250 cm³: 1.0 × 10⁻³ mol","m":1},{"t":"Mass = 1.0 × 10⁻³ × 176 = 0.176 g","m":1}],"model":"(a) n(I₂) = c × V = 0.0050 × 0.0200 = 1.0 × 10⁻⁴ mol. (b) The ratio is 1 : 1, so there is 1.0 × 10⁻⁴ mol of vitamin C in each 25.0 cm³ portion. The whole 250 cm³ contains ten times as much, 1.0 × 10⁻³ mol, so mass = 1.0 × 10⁻³ × 176 = 0.176 g."},
 {"id":"oxfood-w03","topic":"oxfood","type":"written","marks":2,"q":"Ethanol can be oxidised to ethanal and then to ethanoic acid. Suggest why wine goes sour when left open to the air.","points":[{"t":"Oxygen in the air oxidises the ethanol in the wine","m":1},{"t":"forming ethanoic acid (vinegar), which tastes sour","m":1}],"model":"Ethanol is oxidised by oxygen from the air (assisted by bacteria) first to ethanal and then to ethanoic acid, which gives the sour taste."},
 {"id":"oxfood-x01","topic":"oxfood","q":"Which of these is the main reason that antioxidants are added to foods containing oils?","options":["They increase the melting point of the oil","They prevent the oils becoming rancid by oxidation","They make the food taste sweet","They hydrolyse the fats"],"answer":1,"explanation":"Oxidation of unsaturated fats gives rancid smells and tastes. Antioxidants are oxidised in preference to the food."},
 {"id":"oxfood-x02","topic":"oxfood","q":"In the equation Fe³⁺ + e⁻ → Fe²⁺, what happens to the iron(III) ion?","options":["It is oxidised","It is neutralised","It loses a proton","It is reduced"],"answer":3,"explanation":"Gain of electrons is reduction, so the Fe³⁺ ion is reduced to Fe²⁺."},
 {"id":"oxfood-x03","topic":"oxfood","q":"Which functional group is formed when a secondary alcohol is oxidised?","options":["Carboxyl group","Carbonyl group in a ketone","Ester link","Aldehyde group"],"answer":1,"explanation":"A secondary alcohol is oxidised to a ketone, which has a C=O group between two carbon atoms."},
 {"id":"oxfood-x04","topic":"oxfood","q":"How would the concentration of an antioxidant in a sample of fruit juice typically change as it is stored in air?","options":["It increases","It stays the same","It increases then decreases","It decreases"],"answer":3,"explanation":"The antioxidant is gradually oxidised by oxygen, so its concentration falls with time."},
 {"id":"fragrances-w01","topic":"fragrances","type":"written","marks":3,"q":"Limonene, a terpene found in orange peel, has the molecular formula C₁₀H₁₆ and contains two C=C bonds.\n(a) How many isoprene units are in a limonene molecule? (1)\n(b) Calculate the mass of bromine, Br₂ (GFM = 160), that reacts with 1.36 g of limonene (GFM = 136). (2)","points":[{"t":"(a) 2 (each isoprene unit contains 5 carbon atoms)","m":1},{"t":"(b) Moles of limonene = 1.36 ÷ 136 = 0.0100 mol, which reacts with 0.0200 mol Br₂","m":1},{"t":"Mass of Br₂ = 0.0200 × 160 = 3.2 g","m":1}],"model":"(a) Terpenes are built from isoprene units (C₅H₈), so C₁₀H₁₆ contains two. (b) Each C=C reacts with one Br₂, so 0.0100 mol limonene needs 0.0200 mol Br₂ = 0.0200 × 160 = 3.2 g."},
 {"id":"fragrances-w02","topic":"fragrances","type":"written","marks":3,"q":"Essential oils can be extracted from plants by steam distillation.\n(a) Describe how steam distillation separates an essential oil from plant material. (2)\n(b) Why is steam distillation preferred over simple heating? (1)","points":[{"t":"(a) Steam passes through the plant material and carries the volatile oils with it","m":1},{"t":"The mixture of steam and oil is condensed and the oil separated from the water","m":1},{"t":"(b) The oils would decompose at their normal boiling points; steam distillation works at a lower temperature (around 100 °C)","m":1}],"model":"(a) Steam is passed through the plant material; the volatile oils evaporate with the steam. The vapour is condensed to a mixture of water and oil that separates into layers. (b) Many essential oils decompose at high temperatures, so steam distillation avoids this."},
 {"id":"fragrances-w03","topic":"fragrances","type":"written","marks":2,"q":"Explain why essential oils do not dissolve in water but dissolve in non-polar solvents.","points":[{"t":"Essential oils are mainly non-polar hydrocarbons / have only weak London dispersion forces","m":1},{"t":"Water molecules are strongly hydrogen bonded and do not interact with non-polar molecules, whereas non-polar solvents do","m":1}],"model":"Essential oils are non-polar and cannot form hydrogen bonds with water, which is strongly hydrogen-bonded to itself. They mix with non-polar solvents because the attractions between the molecules are similar."},
 {"id":"fragrances-x01","topic":"fragrances","q":"Which structure is the isoprene (2-methylbuta-1,3-diene) unit?","options":["CH₃–CH=CH–CH₃","CH₂=CH–CH₂–CH₃","CH₃–C(CH₃)=CH₂","CH₂=C(CH₃)–CH=CH₂"],"answer":3,"explanation":"Isoprene has a four-carbon chain with two C=C bonds (buta-1,3-diene) and a methyl group on carbon 2."},
 {"id":"fragrances-x02","topic":"fragrances","q":"A terpene contains 15 carbon atoms. How many isoprene units are joined?","options":["2","3","4","5"],"answer":1,"explanation":"Each isoprene unit has five carbon atoms, so 15 ÷ 5 = 3 units."},
 {"id":"fragrances-x03","topic":"fragrances","q":"Which property of essential oils makes them useful in perfumes?","options":["They are soluble in water","They are ionic","They are solid at room temperature","They are volatile"],"answer":3,"explanation":"Volatile compounds vaporise easily at skin temperature so that the scent reaches the nose."},
 {"id":"fragrances-x04","topic":"fragrances","q":"When a terpene is oxidised, which functional groups may be formed?","options":["Ester links","Aldehyde and ketone groups","Peptide links","Halogen groups"],"answer":1,"explanation":"Oxidation of terpene alcohols gives aldehydes and ketones, which often have distinct fragrances."},
 {"id":"skin-w01","topic":"skin","type":"written","marks":3,"q":"Sun protection products contain compounds that absorb UV radiation.\n(a) What happens to a covalent bond when it absorbs UV radiation of enough energy? (1)\n(b) Name the type of species formed. (1)\n(c) Explain why this species is harmful to skin. (1)","points":[{"t":"(a) The bond breaks (homolytic fission) with one electron going to each atom","m":1},{"t":"(b) Free radicals","m":1},{"t":"(c) Free radicals are very reactive and start chain reactions that damage skin cells (cause damage to molecules)","m":1}],"model":"(a) UV photons carry enough energy to break covalent bonds, giving one electron to each fragment. (b) The fragments have an unpaired electron and are free radicals. (c) They are highly reactive and begin chain reactions that damage molecules in skin cells."},
 {"id":"skin-w02","topic":"skin","type":"written","marks":3,"q":"Methane reacts with chlorine in the presence of UV light.\n(a) Write an equation for the initiation step. (1)\n(b) Write equations for two propagation steps. (2)","points":[{"t":"(a) Cl₂ → 2Cl•","m":1},{"t":"(b) Cl• + CH₄ → HCl + •CH₃","m":1},{"t":"•CH₃ + Cl₂ → CH₃Cl + Cl•","m":1}],"model":"(a) UV light splits the chlorine molecule: Cl₂ → 2Cl•. (b) Propagation steps each use up one radical and produce another: Cl• + CH₄ → HCl + •CH₃ and •CH₃ + Cl₂ → CH₃Cl + Cl•."},
 {"id":"skin-w03","topic":"skin","type":"written","marks":2,"q":"Write two equations to show two possible termination steps in the chlorination of methane.","points":[{"t":"Cl• + Cl• → Cl₂","m":1},{"t":"•CH₃ + Cl• → CH₃Cl (or •CH₃ + •CH₃ → C₂H₆)","m":1}],"model":"In termination steps two radicals combine so no new radical is produced: for example Cl• + Cl• → Cl₂, •CH₃ + Cl• → CH₃Cl or •CH₃ + •CH₃ → C₂H₆."},
 {"id":"skin-w04","topic":"skin","type":"written","marks":2,"q":"Explain how a free radical scavenger protects the skin from damage.","points":[{"t":"It reacts with free radicals to form stable (less reactive) molecules","m":1},{"t":"This breaks the chain reaction (terminates the radicals before they damage skin)","m":1}],"model":"Radical scavengers combine with free radicals to form stable molecules, removing the radicals and stopping the chain reaction from continuing."},
 {"id":"skin-x01","topic":"skin","q":"What is the name for a chain-reaction step where one radical is used and another is formed?","options":["Initiation","Termination","Hydrolysis","Propagation"],"answer":3,"explanation":"In propagation a radical reacts with a molecule and generates a new radical, so the chain continues."},
 {"id":"skin-x02","topic":"skin","q":"In which type of reaction are two radicals joined, ending the chain?","options":["Propagation","Termination","Initiation","Substitution"],"answer":1,"explanation":"Termination removes radicals when two combine into a molecule with all electrons paired."},
 {"id":"skin-x03","topic":"skin","q":"What produces free radicals during initiation of a chain reaction?","options":["Heterolytic fission","Transfer of a proton","Loss of a neutron","Homolytic fission of a covalent bond"],"answer":3,"explanation":"Absorption of UV photons splits the bond so that each atom takes one electron, forming two free radicals."},
 {"id":"skin-x04","topic":"skin","q":"What is a free radical?","options":["A negatively charged ion","A species with an unpaired electron","A molecule with a double bond","A compound with no electrons"],"answer":1,"explanation":"A free radical has an unpaired electron, making it very reactive."},
 {"id":"apparatus-w01","topic":"apparatus","type":"written","marks":4,"q":"A student prepares 250 cm³ of a standard solution of sodium carbonate, Na₂CO₃ (GFM = 106), of concentration 0.100 mol l⁻¹.\n(a) Calculate the mass of sodium carbonate required. (2)\n(b) Describe how the solution should be made up. (1)\n(c) Why is the solution described as a standard solution? (1)","points":[{"t":"(a) Moles = 0.100 × 0.250 = 0.0250 mol","m":1},{"t":"Mass = 0.0250 × 106 = 2.65 g","m":1},{"t":"(b) Dissolve the solid in a little deionised water, transfer with rinsings to a 250 cm³ standard flask and make up to the mark","m":1},{"t":"(c) It is a solution of accurately known concentration","m":1}],"model":"(a) n = c × V = 0.100 × 0.250 = 0.0250 mol; mass = 0.0250 × 106 = 2.65 g. (b) Dissolve the solid in a little deionised water, wash the beaker into a 250 cm³ standard flask, add water to the mark and mix. (c) A standard solution has an accurately known concentration."},
 {"id":"apparatus-w02","topic":"apparatus","type":"written","marks":3,"q":"A student uses a pipette to transfer 25.0 cm³ of acid into a conical flask.\n(a) Which liquid should be used to rinse the pipette before use? (1)\n(b) Why is the conical flask rinsed with deionised water but not with the solution? (2)","points":[{"t":"(a) The solution that the pipette will deliver (the acid)","m":1},{"t":"(b) Deionised water does not change the number of moles of acid in the flask","m":1},{"t":"Rinsing with the solution would leave extra acid, increasing the moles in the flask","m":1}],"model":"(a) The pipette is rinsed with the solution it will deliver so that its concentration is not changed by water. (b) Water left in the flask does not change the moles of acid already added, but traces of acid would increase it, altering the titre."},
 {"id":"apparatus-w03","topic":"apparatus","type":"written","marks":2,"q":"Suggest two reasons why a pipette is a better choice than a measuring cylinder for measuring 25.0 cm³ of a solution in a titration.","points":[{"t":"A pipette measures a fixed volume with greater accuracy (smaller uncertainty)","m":1},{"t":"Its single calibration mark reduces reading errors","m":1}],"model":"A pipette is calibrated to deliver exactly one volume and has a smaller percentage uncertainty than a measuring cylinder, giving more accurate results."},
 {"id":"apparatus-x01","topic":"apparatus","q":"Which piece of apparatus gives the most accurate way to measure out 25.0 cm³ of solution?","options":["Beaker","Pipette","Measuring cylinder","Conical flask"],"answer":1,"explanation":"A pipette is calibrated for accuracy to a single volume. A beaker and conical flask are only approximate."},
 {"id":"apparatus-x02","topic":"apparatus","q":"A student reads a burette at the top of the meniscus. What effect does this have on the reading?","options":["It improves precision only","The reading is unaffected because the meniscus is flat","It is a random error that cancels when readings are averaged","A systematic error, because every reading is shifted the same way"],"answer":3,"explanation":"Reading from the wrong point causes an error; if done consistently it produces a systematic error. Always read at the bottom of the meniscus at eye level."},
 {"id":"apparatus-x03","topic":"apparatus","q":"What must be done to a burette immediately before filling it with a solution for a titration?","options":["Rinse with distilled water only","Rinse with a little of the solution to be used","Dry with a paper towel","Rinse with the other reactant"],"answer":1,"explanation":"Rinsing with a small volume of the solution removes water, which would dilute the solution and change its concentration."},
 {"id":"apparatus-x04","topic":"apparatus","q":"A 250 cm³ standard flask has a mark at the neck. What is its purpose?","options":["To show the maximum capacity of the glass","To mark the position of the stopper","To measure approximate volumes","To show the exact volume when the bottom of the meniscus touches the mark"],"answer":3,"explanation":"The mark on the neck is the calibration mark. The solution is made up so that the meniscus sits on it."},
 {"id":"techniques-w01","topic":"techniques","type":"written","marks":3,"q":"In a titration, the following titres were obtained: 24.6, 23.9, 24.1 and 24.0 cm³.\n(a) Which result(s) would be used to calculate the average? Explain. (2)\n(b) Calculate the average titre. (1)","points":[{"t":"(a) 23.9, 24.1 and 24.0 cm³: these are concordant (within 0.2 cm³)","m":1},{"t":"The first (rough) result 24.6 is not concordant so is excluded","m":1},{"t":"(b) Average = (23.9 + 24.1 + 24.0) ÷ 3 = 24.0 cm³","m":1}],"model":"(a) Only concordant values are used, those within 0.2 cm³ of each other. The 24.6 cm³ result differs by more than this, so it is excluded. (b) Average = (23.9 + 24.1 + 24.0) ÷ 3 = 24.0 cm³."},
 {"id":"techniques-w02","topic":"techniques","type":"written","marks":3,"q":"20.0 cm³ portions of sodium hydroxide solution are neutralised by an average of 25.0 cm³ of 0.100 mol l⁻¹ hydrochloric acid (HCl + NaOH → NaCl + H₂O).\nCalculate the concentration of the sodium hydroxide solution.","points":[{"t":"Moles of HCl = 0.100 × 0.0250 = 2.50 × 10⁻³ mol","m":1},{"t":"Ratio is 1 : 1 so moles NaOH = 2.50 × 10⁻³ mol","m":1},{"t":"Concentration = 2.50 × 10⁻³ ÷ 0.0200 = 0.125 mol l⁻¹","m":1}],"model":"n(HCl) = c × V = 0.100 × 0.0250 = 2.50 × 10⁻³ mol. From the 1 : 1 ratio n(NaOH) is the same, so c = n ÷ V = 2.50 × 10⁻³ ÷ 0.0200 = 0.125 mol l⁻¹."},
 {"id":"techniques-w03","topic":"techniques","type":"written","marks":2,"q":"Explain why an indicator should be added to the conical flask rather than to the burette in a titration.","points":[{"t":"The indicator is needed in the reaction mixture to show the end-point","m":1},{"t":"Adding it to the burette would add it to the titrant and alter the amounts / waste the indicator (the colour change would not be seen at the right point)","m":1}],"model":"The indicator must be in the solution being titrated so that the colour change at the end-point is seen in the flask. Adding it to the burette would not reveal the end point."},
 {"id":"techniques-x01","topic":"techniques","q":"Why is a white tile placed under the conical flask during a titration?","options":["To insulate the flask","To increase the reaction rate","To prevent the flask from slipping","To make the colour change easier to see"],"answer":3,"explanation":"A white background shows the first permanent colour change clearly so the end-point is judged more precisely."},
 {"id":"techniques-x02","topic":"techniques","q":"What is the purpose of a rough titration?","options":["To provide the final result","To find the approximate volume so that later titrations can be done carefully","To check the concentration of the indicator","To clean the burette"],"answer":1,"explanation":"The rough titre gives a guide to the end-point volume, so the accurate runs can be done dropwise near it."},
 {"id":"techniques-x03","topic":"techniques","q":"What does the term concordant mean for titration results?","options":["Results that differ by 1 cm³","The first result in a series","Results that are all identical","Results that agree within 0.2 cm³"],"answer":3,"explanation":"Concordant titres are close to each other, normally within 0.2 cm³, showing reliable technique."},
 {"id":"techniques-x04","topic":"techniques","q":"A student heats a reaction mixture under reflux. What is the purpose of the condenser?","options":["To remove products as they form","To return vapours to the flask as liquid","To cool the reaction","To measure the temperature"],"answer":1,"explanation":"The vertical condenser condenses vapours that rise, so the volatile reactants and products are not lost while the mixture is heated."},
 {"id":"reporting-w01","topic":"reporting","type":"written","marks":3,"q":"A student investigates the effect of temperature on the rate of reaction between sodium thiosulfate and hydrochloric acid by timing the appearance of sulfur.\n(a) Name the independent variable and the dependent variable. (2)\n(b) State one variable that must be kept constant. (1)","points":[{"t":"(a) Independent variable: temperature","m":1},{"t":"Dependent variable: time taken for the sulfur to obscure a mark (or rate)","m":1},{"t":"(b) Any one of: concentration/volume of thiosulfate, concentration/volume of acid, same size of mark and flask","m":1}],"model":"(a) The independent variable is the one deliberately changed, the temperature. The dependent variable is the one measured, the time for the mark to disappear. (b) Concentrations and volumes of both solutions must be controlled for a fair test."},
 {"id":"reporting-w02","topic":"reporting","type":"written","marks":3,"q":"A student's results for the mass of copper(II) oxide produced in repeated experiments were 1.52 g, 1.54 g, 1.53 g and 1.80 g.\n(a) Suggest which result is an outlier. (1)\n(b) Calculate the mean of the remaining results. (1)\n(c) Suggest one reason why repeating the experiment improves reliability. (1)","points":[{"t":"(a) 1.80 g","m":1},{"t":"(b) (1.52 + 1.54 + 1.53) ÷ 3 = 1.53 g","m":1},{"t":"(c) Repeats allow anomalies to be identified and an average to be calculated, reducing the effect of random errors","m":1}],"model":"(a) 1.80 g is far from the other results. (b) Mean = (1.52 + 1.54 + 1.53) ÷ 3 = 1.53 g. (c) Repeating identifies anomalous results and averaging reduces random error, so the data are more reliable."},
 {"id":"reporting-w03","topic":"reporting","type":"written","marks":2,"q":"When plotting a line graph of volume of gas against time, what should be shown on each axis and what should be done with the points?","points":[{"t":"Independent variable (time) on the x-axis and dependent variable (volume) on the y-axis, with labels and units","m":1},{"t":"Plot points accurately and draw a smooth best-fit line (not joining dot-to-dot)","m":1}],"model":"The x-axis shows the variable that is changed or time, the y-axis the measured quantity. Both axes are labelled with units and have even scales. A best-fit line is drawn through the points."},
 {"id":"reporting-x01","topic":"reporting","q":"What is the purpose of a control experiment?","options":["To increase the reaction rate","To provide a comparison to show the effect of the variable under test","To use up the reactants","To measure the temperature"],"answer":1,"explanation":"A control keeps all conditions the same except for the factor being investigated, so any difference can be attributed to it."},
 {"id":"reporting-x02","topic":"reporting","q":"Which is the best description of a conclusion in an experimental report?","options":["A list of apparatus","A repeat of the method","A prediction of the results","A statement supported by the results that answers the aim"],"answer":3,"explanation":"The conclusion links the results to the aim and says what the data show."},
 {"id":"reporting-x03","topic":"reporting","q":"A thermometer has a scale marked in 1 °C divisions. What is the reading uncertainty typically estimated as?","options":["±1 °C","±0.5 °C","±5 °C","±0.01 °C"],"answer":1,"explanation":"Reading uncertainty is usually taken as half of the smallest division on the scale, here ±0.5 °C."},
 {"id":"reporting-x04","topic":"reporting","q":"Which type of graph is most suitable for showing how the rate of a reaction varies continuously with temperature?","options":["Pie chart","Bar chart with unlabelled bars","Table with no graph","Line graph"],"answer":3,"explanation":"Both variables are continuous, so a line graph with a best-fit line shows the trend most clearly."},
 // batch higher nature chemistry additions 2
 {"id":"fats-w06","topic":"fats","type":"written","marks":4,"q":"Glyceryl tristearate is formed from propane-1,2,3-triol (GFM = 92) and three molecules of stearic acid, C₁₇H₃₅COOH (GFM = 284).\n(a) Name the type of reaction. (1)\n(b) How many molecules of water are released per molecule of fat? (1)\n(c) Calculate the GFM of glyceryl tristearate. (2)","points":[{"t":"(a) Condensation (esterification)","m":1},{"t":"(b) Three water molecules (one for each ester link)","m":1},{"t":"(c) 92 + 3 × 284 − 3 × 18","m":1},{"t":"= 92 + 852 − 54 = 890","m":1}],"model":"(a) Condensation. (b) Each of the three –OH groups forms an ester link with release of one water. (c) GFM = 92 + (3 × 284) − (3 × 18) = 92 + 852 − 54 = 890."},
 {"id":"fats-w07","topic":"fats","type":"written","marks":2,"q":"Oleic acid, C₁₇H₃₃COOH (GFM = 282), contains one C=C bond. Calculate the mass of iodine (I₂ = 254) that reacts with 100 g of oleic acid.","points":[{"t":"Moles of oleic acid = 100 ÷ 282 = 0.355 mol, which reacts with 0.355 mol I₂ (1 : 1)","m":1},{"t":"Mass of I₂ = 0.355 × 254 = 90.1 g","m":1}],"model":"One I₂ adds to each C=C bond. n = 100 ÷ 282 = 0.355 mol, so mass of iodine = 0.355 × 254 = 90.1 g (the iodine number of oleic acid)."},
 {"id":"fats-w08","topic":"fats","type":"written","marks":3,"q":"Fats and oils are important in the diet as a source of energy.\n(a) Explain why fats and oils provide more energy per gram than carbohydrates. (2)\n(b) State what is meant by an essential fatty acid. (1)","points":[{"t":"(a) Fats/oils have long hydrocarbon chains with a lower proportion of oxygen","m":1},{"t":"so they are more reduced / have more C–H bonds that release energy when oxidised","m":1},{"t":"(b) A fatty acid the body cannot make that must be obtained from the diet","m":1}],"model":"(a) Fatty acid chains contain many C–H bonds and little oxygen, so oxidation releases more energy per gram than in carbohydrates that already contain much oxygen. (b) Essential fatty acids cannot be synthesised in the body."},
 {"id":"fats-w09","topic":"fats","type":"written","marks":3,"q":"Fats and oils can be hydrolysed in two ways. Compare hydrolysis using an acid catalyst with hydrolysis using hot sodium hydroxide solution, stating the products in each case.","points":[{"t":"Acid hydrolysis: propane-1,2,3-triol and three fatty acids (carboxylic acids)","m":1},{"t":"Alkaline hydrolysis with NaOH: propane-1,2,3-triol and the sodium salts of the fatty acids (soap)","m":1},{"t":"The ester links are broken in both cases","m":1}],"model":"In acid hydrolysis the ester links are broken by water to give glycerol and fatty acids. With sodium hydroxide the acids formed are neutralised, so the products are glycerol and sodium carboxylates, which are soaps."},
 {"id":"soaps-w05","topic":"soaps","type":"written","marks":3,"q":"8.90 g of glyceryl tristearate (GFM = 890) is heated with excess sodium hydroxide to make soap, sodium stearate (C₁₇H₃₅COONa, GFM = 306).\nCalculate the mass of sodium stearate formed, assuming 100 % yield.","points":[{"t":"Moles of fat = 8.90 ÷ 890 = 0.0100 mol","m":1},{"t":"Each mole of fat gives 3 mol of soap: 0.0300 mol","m":1},{"t":"Mass = 0.0300 × 306 = 9.18 g","m":1}],"model":"The equation fat + 3NaOH → glycerol + 3 sodium stearate shows a 1 : 3 ratio. Moles of fat = 0.0100, so soap = 0.0300 mol and mass = 0.0300 × 306 = 9.18 g."},
 {"id":"soaps-w06","topic":"soaps","type":"written","marks":3,"q":"Describe and explain how a detergent differs from a soap and why detergents are more useful in hard water areas.","points":[{"t":"Detergents are synthetic compounds with a hydrophilic head (e.g. sulfonate) and a hydrophobic tail","m":1},{"t":"Soaps are sodium/potassium salts of fatty acids","m":1},{"t":"In hard water the Ca²⁺ and Mg²⁺ ions precipitate soap ions as scum but form soluble compounds with detergent ions, so detergents still lather and clean","m":1}],"model":"Soaps are salts of natural fatty acids; detergents are synthetic. Calcium and magnesium ions in hard water form insoluble scum with soap, but the calcium and magnesium salts of detergents are soluble, so detergents remain effective."},
 {"id":"esters-w06","topic":"esters","type":"written","marks":3,"q":"Ethyl ethanoate is hydrolysed using dilute sulfuric acid.\n(a) Name the two products. (1)\n(b) Give the name of the catalyst. (1)\n(c) Why is the reaction described as reversible? (1)","points":[{"t":"(a) Ethanol and ethanoic acid","m":1},{"t":"(b) Dilute sulfuric acid (H⁺ ions)","m":1},{"t":"(c) The products can react together to form the ester and water again (equilibrium)","m":1}],"model":"(a) Hydrolysis splits the ester link: ethanol and ethanoic acid. (b) The acid (H⁺) catalyses the reaction. (c) Esterification and hydrolysis are the forward and reverse reactions, so an equilibrium forms."},
 {"id":"esters-w07","topic":"esters","type":"written","marks":3,"q":"Pentan-1-ol and ethanoic acid react to make pentyl ethanoate, which smells of bananas.\n(a) Write the structural formula of pentyl ethanoate. (1)\n(b) State two ways of increasing the yield of ester. (2)","points":[{"t":"(a) CH₃COOCH₂CH₂CH₂CH₂CH₃","m":1},{"t":"(b) Use an excess of one reactant (e.g. the cheaper alcohol or acid)","m":1},{"t":"Remove water (or the ester) as it forms, shifting the equilibrium to the right","m":1}],"model":"(a) The acid part CH₃CO– is joined through oxygen to the pentyl group. (b) Esterification is reversible, so using an excess of a reactant or removing water as formed pushes the equilibrium towards the ester."},
 {"id":"esters-w08","topic":"esters","type":"written","marks":3,"q":"Three esters, A, B and C, are listed with their boiling points: methyl methanoate 32 °C, ethyl ethanoate 77 °C, pentyl ethanoate 149 °C.\n(a) Describe the trend. (1)\n(b) Explain the trend in terms of intermolecular forces. (2)","points":[{"t":"(a) Boiling point increases as the molecules get larger (more carbon atoms)","m":1},{"t":"(b) Larger molecules have more electrons and a larger surface, so stronger London dispersion forces","m":1},{"t":"More energy is needed to separate the molecules","m":1}],"model":"Boiling point rises with molecular size because the London dispersion forces between larger molecules are stronger, requiring more energy to separate the molecules."},
 {"id":"alcohols-w07","topic":"alcohols","type":"written","marks":3,"q":"Pent-1-ene can be converted to pentan-2-one in two steps.\n(a) Name the product of step 1, in which pent-1-ene reacts with water (acid catalyst). (1)\n(b) Name the type of compound formed. (1)\n(c) State a reagent for step 2 and the colour change you would see. (1)","points":[{"t":"(a) Pentan-2-ol (the major product)","m":1},{"t":"(b) A ketone (pentan-2-one) is formed from the secondary alcohol","m":1},{"t":"(c) Acidified potassium dichromate solution: orange to green","m":1}],"model":"(a) Hydration of the double bond gives mainly the secondary alcohol, pentan-2-ol. (b) Oxidation of a secondary alcohol gives a ketone. (c) Acidified dichromate changes colour from orange to green as chromium(VI) is reduced to chromium(III)."},
 {"id":"alcohols-w08","topic":"alcohols","type":"written","marks":3,"q":"In the oxidation of propan-1-ol by acidified dichromate, the ion-electron equations are:\nCH₃CH₂CH₂OH → CH₃CH₂CHO + 2H⁺ + 2e⁻\nCr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O\nCombine them to give the redox equation.","points":[{"t":"Multiply the first equation by 3 so that electrons balance (6e⁻)","m":1},{"t":"Add: 3CH₃CH₂CH₂OH + Cr₂O₇²⁻ + 14H⁺ + 6H⁺ + 6e⁻ → 3CH₃CH₂CHO + 6H⁺ + 6e⁻ + 2Cr³⁺ + 7H₂O","m":1},{"t":"Cancel to get: 3CH₃CH₂CH₂OH + Cr₂O₇²⁻ + 8H⁺ → 3CH₃CH₂CHO + 2Cr³⁺ + 7H₂O","m":1}],"model":"The electrons must cancel, so the first half-equation is multiplied by 3. Adding gives 14H⁺ on the left and 6H⁺ on the right, so net 8H⁺: 3CH₃CH₂CH₂OH + Cr₂O₇²⁻ + 8H⁺ → 3CH₃CH₂CHO + 2Cr³⁺ + 7H₂O."},
 {"id":"alcohols-w09","topic":"alcohols","type":"written","marks":2,"q":"Explain why propan-1-ol has a higher boiling point than propanal although both have similar molecular masses.","points":[{"t":"Propan-1-ol molecules form hydrogen bonds (via the –OH group)","m":1},{"t":"Propanal has only permanent dipole–dipole and London forces, which are weaker, so less energy is needed to boil it","m":1}],"model":"Propan-1-ol can form hydrogen bonds between molecules, which are stronger than the dipole–dipole forces in propanal, so it has the higher boiling point."},
 {"id":"alcohols-w10","topic":"alcohols","type":"written","marks":3,"q":"Compounds P, Q and R have the formula C₄H₁₀O. P is oxidised to an aldehyde, Q is oxidised to a ketone, and R is not oxidised by acidified dichromate.\nIdentify P, Q and R by name or structure.","points":[{"t":"P is butan-1-ol (or 2-methylpropan-1-ol), a primary alcohol","m":1},{"t":"Q is butan-2-ol, a secondary alcohol","m":1},{"t":"R is 2-methylpropan-2-ol, a tertiary alcohol","m":1}],"model":"Primary alcohols oxidise to aldehydes, secondary alcohols to ketones and tertiary alcohols do not oxidise. Matching C₄H₁₀O isomers gives P = butan-1-ol, Q = butan-2-ol and R = 2-methylpropan-2-ol."},
 {"id":"proteins-w05","topic":"proteins","type":"written","marks":3,"q":"A tripeptide is formed from glycine (GFM = 75), alanine (GFM = 89) and serine (GFM = 105).\n(a) How many peptide links are in the tripeptide? (1)\n(b) Calculate the GFM of the tripeptide. (2)","points":[{"t":"(a) Two peptide links","m":1},{"t":"(b) 75 + 89 + 105 = 269","m":1},{"t":"Subtract two water molecules: 269 − 36 = 233","m":1}],"model":"(a) A chain of three amino acids contains two peptide links. (b) Each link forms by loss of one water, so GFM = 75 + 89 + 105 − (2 × 18) = 233."},
 {"id":"proteins-w06","topic":"proteins","type":"written","marks":3,"q":"Proteins have different roles in the body. Explain why different proteins have different shapes and how this relates to their function in enzymes.","points":[{"t":"The sequence of amino acids (primary structure) is different in each protein","m":1},{"t":"The chain folds because of interactions between side-chains (hydrogen bonds etc.) into a specific 3-D shape","m":1},{"t":"An enzyme's shape gives it an active site that fits only particular substrate molecules","m":1}],"model":"The order of the amino acids determines how the chain folds. The resulting shape provides an active site that binds only specific substrates, giving enzymes their selectivity."},
 {"id":"proteins-w07","topic":"proteins","type":"written","marks":2,"q":"Proteins in the diet are digested to amino acids. Explain why this is necessary and name the type of reaction.","points":[{"t":"Hydrolysis breaks down the large protein into small amino acid molecules","m":1},{"t":"which can be absorbed and then used to build the body's own proteins","m":1}],"model":"Digestion hydrolyses protein into amino acids that can pass into the blood and be rebuilt into the body's own proteins."},
 {"id":"oxfood-w04","topic":"oxfood","type":"written","marks":3,"q":"Ascorbic acid is oxidised to dehydroascorbic acid by iodine solution.\n(a) Write the ion-electron equation for iodine in this reaction: I₂ + 2e⁻ → 2I⁻. State whether iodine is oxidised or reduced. (1)\n(b) 25.0 cm³ of fruit juice needs 12.5 cm³ of 0.0100 mol l⁻¹ iodine solution. Calculate the moles of vitamin C in the portion (1 : 1 reaction). (2)","points":[{"t":"(a) Iodine is reduced (gains electrons)","m":1},{"t":"(b) n(I₂) = 0.0100 × 0.0125 = 1.25 × 10⁻⁴ mol","m":1},{"t":"n(vitamin C) = 1.25 × 10⁻⁴ mol (1 : 1)","m":1}],"model":"(a) Gain of electrons is reduction. (b) n = c × V = 0.0100 × 0.0125 = 1.25 × 10⁻⁴ mol of iodine, so 1.25 × 10⁻⁴ mol of vitamin C."},
 {"id":"oxfood-w05","topic":"oxfood","type":"written","marks":3,"q":"Rancidity is the oxidation of fats and oils. Explain why unsaturated oils become rancid more quickly than saturated fats.","points":[{"t":"Unsaturated oils contain C=C double bonds","m":1},{"t":"These are more susceptible to attack by oxygen / free radicals","m":1},{"t":"The oxidation forms aldehydes, ketones and acids that give a rancid smell and taste","m":1}],"model":"The C=C bonds in unsaturated oils are readily attacked by oxygen, forming breakdown products such as aldehydes and carboxylic acids with unpleasant smells; saturated fats have no such bonds."},
 {"id":"fragrances-w04","topic":"fragrances","type":"written","marks":3,"q":"Citral is a fragrant compound found in lemon grass. Its molecules contain an aldehyde group and two C=C bonds.\n(a) Describe a chemical test that shows citral is an aldehyde. (2)\n(b) Describe a test for the C=C bond. (1)","points":[{"t":"(a) Warm with Fehling's (or Benedict's) solution: blue solution turns brick red","m":1},{"t":"or Tollens' reagent: silver mirror forms","m":1},{"t":"(b) Add bromine solution: it is decolourised","m":1}],"model":"(a) Aldehydes are oxidised by warm Fehling's solution (blue → brick-red precipitate) or Tollens' reagent (silver mirror). (b) The C=C bonds decolourise bromine."},
 {"id":"fragrances-w05","topic":"fragrances","type":"written","marks":3,"q":"Compare steam distillation and solvent extraction as methods of obtaining an essential oil from a plant.","points":[{"t":"Steam distillation: oil carried over with steam then condensed and separated; no solvent residue","m":1},{"t":"Solvent extraction: oil dissolves in a non-polar solvent which is then evaporated off","m":1},{"t":"Solvent extraction is used for oils that would decompose in steam; the solvent must be removed completely","m":1}],"model":"In steam distillation the oils are carried over with steam and condensed. In solvent extraction the oils are dissolved in a solvent that is later removed, which suits heat-sensitive compounds."},
 {"id":"skin-w05","topic":"skin","type":"written","marks":3,"q":"Sunscreens often contain molecules that absorb UV radiation.\n(a) Why does UV radiation cause damage to skin cells? (1)\n(b) Explain how a sunscreen protects skin. (2)","points":[{"t":"(a) UV has enough energy to break covalent bonds, forming free radicals that damage cell molecules","m":1},{"t":"(b) The sunscreen molecules absorb the UV radiation so less reaches the skin","m":1},{"t":"Energy is released as heat harmlessly, instead of breaking bonds in skin molecules","m":1}],"model":"(a) UV photons have enough energy to break bonds and produce free radicals. (b) Sunscreen molecules absorb UV radiation and dissipate the energy safely, so fewer bonds in the skin are broken."},
 {"id":"systematic-x08","topic":"systematic","q":"Which is the name of the major product when but-1-ene reacts with water in the presence of an acid catalyst?","options":["Butan-2-ol","Butan-1-ol","Butanal","Butanone"],"answer":0,"explanation":"Water adds across the double bond so that the –OH is mainly attached to the carbon with fewer hydrogens, giving the secondary alcohol butan-2-ol."},
 {"id":"systematic-x09","topic":"systematic","q":"What is the name of CH₃C(CH₃)=CHCH₃?","options":["3-methylbut-2-ene","2-methylbut-1-ene","2-methylbut-2-ene","pent-2-ene"],"answer":2,"explanation":"A four-carbon chain with the double bond starting at carbon 2 and a methyl group on carbon 2."},
 {"id":"systematic-x10","topic":"systematic","q":"How many carbon atoms does cyclohexane have in its ring?","options":["6","5","7","12"],"answer":0,"explanation":"The prefix hex- means six carbons, arranged in a ring in cyclohexane (C₆H₁₂)."},
 {"id":"systematic-x11","topic":"systematic","q":"What type of reaction converts an alkene into an alkane?","options":["Substitution","Condensation","Addition","Hydrolysis"],"answer":2,"explanation":"Hydrogen adds across the C=C double bond, saturating the molecule."},
 {"id":"alcohols-x06","topic":"alcohols","q":"Which compound is formed when pentan-3-ol is oxidised?","options":["Pentan-3-one","Pentanal","Pentanoic acid","Pentane"],"answer":0,"explanation":"Pentan-3-ol is a secondary alcohol, which is oxidised to the ketone pentan-3-one."},
 {"id":"alcohols-x07","topic":"alcohols","q":"What colour change is seen when acidified dichromate oxidises an alcohol?","options":["Green to orange","Colourless to pink","Orange to green","Blue to red"],"answer":2,"explanation":"Cr₂O₇²⁻ (orange) is reduced to Cr³⁺ (green)."},
 {"id":"alcohols-x08","topic":"alcohols","q":"Which alcohol is secondary?","options":["Butan-2-ol","Butan-1-ol","2-methylpropan-2-ol","Ethanol"],"answer":0,"explanation":"In butan-2-ol the carbon carrying the –OH group is bonded to two other carbon atoms."},
 {"id":"alcohols-x09","topic":"alcohols","q":"What change in oxidation state occurs for chromium when dichromate oxidises ethanol?","options":["+3 to +6","+7 to +2","+6 to +3","+6 to +4"],"answer":2,"explanation":"Cr in Cr₂O₇²⁻ is +6; it is reduced to Cr³⁺, which is +3."},
 {"id":"acids-c-x06","topic":"acids-c","q":"Which of these would have the highest boiling point?","options":["Butanoic acid","Butan-1-ol","Butanal","Butane"],"answer":0,"explanation":"Carboxylic acids form the strongest hydrogen bonding of the group, so have the highest boiling point."},
 {"id":"acids-c-x07","topic":"acids-c","q":"What is the name of the salt formed when propanoic acid reacts with calcium hydroxide?","options":["Calcium propane","Calcium propanol","Calcium propanoate","Propyl calcium"],"answer":2,"explanation":"The salt of a carboxylic acid is named metal + alkanoate, so calcium propanoate."},
 {"id":"acids-c-x08","topic":"acids-c","q":"Which gas is formed when ethanoic acid reacts with magnesium?","options":["Hydrogen","Carbon dioxide","Oxygen","Methane"],"answer":0,"explanation":"Acids react with reactive metals to give a salt and hydrogen."},
 {"id":"esters-x05","topic":"esters","q":"What is the formula of ethyl methanoate?","options":["CH₃COOCH₃","HCOOCH₃","HCOOCH₂CH₃","CH₃CH₂COOH"],"answer":2,"explanation":"Methanoate comes from methanoic acid (HCOO–) and ethyl from ethanol (–C₂H₅)."},
 {"id":"esters-x06","topic":"esters","q":"Which of these is a use of esters?","options":["Flavourings and solvents","Making soap by hydrolysis only","Producing metals","Fertilisers"],"answer":0,"explanation":"Esters are volatile with pleasant smells, used in flavourings, perfumes and as solvents."},
 {"id":"esters-x07","topic":"esters","q":"Which type of reaction forms the ester link?","options":["Addition","Hydrolysis","Condensation","Oxidation"],"answer":2,"explanation":"Two molecules join with loss of a small molecule (water), a condensation reaction."},
 {"id":"fats-x05","topic":"fats","q":"Which statement about saturated fatty acid chains is correct?","options":["They contain only C–C single bonds in the chain","They contain at least one C=C","They are always liquids","They are shorter than unsaturated acids"],"answer":0,"explanation":"Saturated chains have no double bonds, so they are straight and pack closely."},
 {"id":"fats-x06","topic":"fats","q":"Which test shows that an oil is unsaturated?","options":["It turns limewater milky","It turns universal indicator red","It decolourises bromine solution","It dissolves in water"],"answer":2,"explanation":"C=C bonds add bromine, removing its orange colour."},
 {"id":"soaps-x05","topic":"soaps","q":"What is the other product when a fat is hydrolysed with sodium hydroxide to make soap?","options":["Propane-1,2,3-triol","Ethanol","Carbon dioxide","Glucose"],"answer":0,"explanation":"The glycerol part of the triglyceride is released as propane-1,2,3-triol."},
 {"id":"soaps-x06","topic":"soaps","q":"Which statement about soap micelles is correct?","options":["The tails are in contact with water","The micelle has no charge on its surface","The ionic heads are in contact with water","Micelles contain only water"],"answer":2,"explanation":"The hydrophilic carboxylate heads face outwards into water while the tails are inside, holding the grease."},
 {"id":"proteins-x06","topic":"proteins","q":"Which bond joins amino acids in a protein?","options":["Peptide (amide) link","Ester link","Ionic bond","Glycosidic link"],"answer":0,"explanation":"The –CONH– peptide link forms between the carboxyl group of one amino acid and the amino group of the next."},
 {"id":"proteins-x07","topic":"proteins","q":"What happens to the protein in an egg when it is boiled?","options":["Peptide links are hydrolysed","It becomes a fat","The 3-D structure changes (denaturation)","It becomes an acid"],"answer":2,"explanation":"Heat breaks weak bonds that hold the folded shape, so the protein is denatured."},
 {"id":"oxfood-x05","topic":"oxfood","q":"Which species is a reducing agent?","options":["One that loses electrons","One that gains electrons","One that is neutral in charge","One that is reduced"],"answer":0,"explanation":"A reducing agent donates electrons, being oxidised itself."},
 {"id":"oxfood-x06","topic":"oxfood","q":"Why is a food's use-by date shorter when stored in air?","options":["Air increases protein content","Oxygen adds antioxidants","Oxidation by oxygen spoils fats and oils","Air lowers the temperature"],"answer":2,"explanation":"Oxygen in air oxidises fats, producing rancid products."},
 {"id":"fragrances-x05","topic":"fragrances","q":"What is a terpene?","options":["A compound built from isoprene units","A compound built from amino acids","A polyester","A type of soap"],"answer":0,"explanation":"Terpenes are formed by joining isoprene (C₅H₈) units."},
 {"id":"fragrances-x06","topic":"fragrances","q":"A terpene molecule has the formula C₂₀H₃₂. How many isoprene units does it contain?","options":["2","3","4","5"],"answer":2,"explanation":"Each isoprene unit has five carbon atoms; 20 ÷ 5 = 4 units."},
 {"id":"skin-x05","topic":"skin","q":"Which radiation causes sunburn?","options":["Ultraviolet","Infrared","Radio waves","Microwaves"],"answer":0,"explanation":"UV radiation carries enough energy to damage skin cells."},
 {"id":"skin-x06","topic":"skin","q":"What does a free radical scavenger do?","options":["Produces new radicals","Absorbs infrared","Reacts with radicals to form stable molecules","Neutralises acids"],"answer":2,"explanation":"Scavengers remove free radicals and stop chain reactions."},
 // batch higher calculations
 {"id":"reactants-w14","topic":"reactants","type":"written","marks":3,"q":"In the blast furnace, iron(III) oxide is reduced: Fe₂O₃ + 3CO → 2Fe + 3CO₂.\n(a) Calculate the atom economy for the production of iron. (GFM: Fe₂O₃ = 160; CO = 28; Fe = 56) (2)\n(b) Suggest why this value does not show how efficient the process is in practice. (1)","points":[{"t":"(a) Mass of desired product = 2 × 56 = 112","m":1},{"t":"Atom economy = 112 ÷ (160 + 3 × 28) × 100 = 112 ÷ 244 × 100 = 45.9 %","m":1},{"t":"(b) Atom economy ignores the actual yield, reaction conditions, energy use and whether the CO₂ is useful","m":1}],"model":"(a) Total mass of reactants = 160 + 84 = 244; mass of iron wanted = 112, so atom economy = 45.9 %. (b) It considers only the equation; it says nothing about the percentage yield or the energy needed."},
 {"id":"reactants-w15","topic":"reactants","type":"written","marks":4,"q":"2.4 g of magnesium is added to 100 cm³ of 0.50 mol l⁻¹ hydrochloric acid. Mg + 2HCl → MgCl₂ + H₂.\n(a) Show by calculation which reactant is in excess. (2)\n(b) Calculate the volume of hydrogen formed, in cm³. (Molar volume = 24 l mol⁻¹) (2)","points":[{"t":"(a) Moles Mg = 2.4 ÷ 24 = 0.10 mol, which needs 0.20 mol HCl","m":1},{"t":"Moles HCl = 0.50 × 0.100 = 0.050 mol, so HCl is the limiting reactant and Mg is in excess","m":1},{"t":"(b) 2 mol HCl gives 1 mol H₂, so 0.050 mol HCl gives 0.025 mol H₂","m":1},{"t":"Volume = 0.025 × 24 = 0.60 l = 600 cm³","m":1}],"model":"(a) Mg is 0.10 mol and would need 0.20 mol of acid but only 0.050 mol HCl is present, so magnesium is in excess. (b) The acid limits the product: 0.025 mol H₂ × 24 l mol⁻¹ = 0.60 l = 600 cm³."},
 {"id":"reactants-w16","topic":"reactants","type":"written","marks":3,"q":"A compound contains 52.2 % carbon, 13.0 % hydrogen and 34.8 % oxygen by mass. (C = 12, H = 1, O = 16)\nCalculate its empirical formula.","points":[{"t":"Moles: C = 52.2 ÷ 12 = 4.35; H = 13.0 ÷ 1 = 13.0; O = 34.8 ÷ 16 = 2.175","m":1},{"t":"Divide by the smallest (2.175): C = 2.0, H = 6.0, O = 1.0","m":1},{"t":"Empirical formula = C₂H₆O","m":1}],"model":"Divide each percentage by the relative atomic mass, then divide by the smallest value to find the simplest whole-number ratio: C : H : O = 2 : 6 : 1, so C₂H₆O."},
 {"id":"reactants-w17","topic":"reactants","type":"written","marks":3,"q":"25.0 cm³ of 0.20 mol l⁻¹ sodium chloride solution is mixed with 75.0 cm³ of 0.10 mol l⁻¹ sodium chloride solution.\nCalculate the concentration of the final solution.","points":[{"t":"Moles in first = 0.20 × 0.0250 = 0.00500 mol","m":1},{"t":"Moles in second = 0.10 × 0.0750 = 0.00750 mol; total 0.0125 mol","m":1},{"t":"Concentration = 0.0125 ÷ 0.100 = 0.125 mol l⁻¹","m":1}],"model":"Add the moles from each solution (0.00500 + 0.00750 = 0.0125 mol) and divide by the total volume (0.100 l): 0.125 mol l⁻¹."},
 {"id":"reactants-w18","topic":"reactants","type":"written","marks":3,"q":"10 cm³ of methane is burned in 50 cm³ of oxygen: CH₄ + 2O₂ → CO₂ + 2H₂O(l). All volumes are measured at the same temperature and pressure, and the final mixture is cooled to room temperature.\nCalculate the total volume of gas remaining.","points":[{"t":"10 cm³ CH₄ needs 20 cm³ O₂, so O₂ is in excess by 30 cm³","m":1},{"t":"10 cm³ of CO₂ is formed (1 : 1 by volume) and water is liquid","m":1},{"t":"Total gas = 30 + 10 = 40 cm³","m":1}],"model":"The volume ratio CH₄ : O₂ : CO₂ is 1 : 2 : 1. 20 cm³ of oxygen reacts, leaving 30 cm³ unused, and 10 cm³ of carbon dioxide forms. Water condenses so the total gas is 40 cm³."},
 {"id":"energy-w13","topic":"energy","type":"written","marks":4,"q":"The enthalpies of combustion are: carbon −394, hydrogen −286 and ethene (C₂H₄) −1411 kJ mol⁻¹.\nUse Hess's law to calculate the enthalpy of formation of ethene, 2C(s) + 2H₂(g) → C₂H₄(g).","points":[{"t":"2C + 2O₂ → 2CO₂: 2 × (−394) = −788 kJ","m":1},{"t":"2H₂ + O₂ → 2H₂O: 2 × (−286) = −572 kJ","m":1},{"t":"Reverse the combustion of ethene: +1411 kJ","m":1},{"t":"ΔH = −788 − 572 + 1411 = +51 kJ mol⁻¹","m":1}],"model":"Formation = Σ(ΔHc of reactants) − ΔHc of product: (2 × −394) + (2 × −286) − (−1411) = −788 − 572 + 1411 = +51 kJ mol⁻¹."},
 {"id":"energy-w14","topic":"energy","type":"written","marks":4,"q":"50.0 cm³ of 1.0 mol l⁻¹ hydrochloric acid is mixed with 50.0 cm³ of 1.0 mol l⁻¹ sodium hydroxide. The temperature rises by 6.7 °C. (c = 4.18 kJ kg⁻¹ °C⁻¹; assume 1 cm³ of solution = 1 g)\n(a) Calculate the energy released. (2)\n(b) Calculate the enthalpy of neutralisation in kJ mol⁻¹. (2)","points":[{"t":"(a) Mass of solution = 100 g = 0.100 kg","m":1},{"t":"Eh = 4.18 × 0.100 × 6.7 = 2.80 kJ","m":1},{"t":"(b) Moles of water formed = 1.0 × 0.0500 = 0.050 mol","m":1},{"t":"ΔH = −56 kJ mol⁻¹ (about −56)","m":1}],"model":"(a) Eh = c m ΔT = 4.18 × 0.100 × 6.7 = 2.80 kJ. (b) 0.050 mol of water formed, so ΔH = −2.80 ÷ 0.050 = −56 kJ mol⁻¹."},
 {"id":"reactants-x06","topic":"reactants","q":"Which has the greatest atom economy for making ethanol?","options":["Fermentation of glucose","Reaction of bromoethane with hydroxide","Reduction of ethanoic acid with a hydride","Addition of water to ethene (C₂H₄ + H₂O → C₂H₅OH)"],"answer":3,"explanation":"In the hydration of ethene all the atoms of the reactants end up in the product, giving a 100 % atom economy."},
 {"id":"reactants-x07","topic":"reactants","q":"What is the percentage yield if 6.0 g is obtained when the theoretical yield is 8.0 g?","options":["60 %","75 %","133 %","25 %"],"answer":1,"explanation":"Percentage yield = actual ÷ theoretical × 100 = 6.0 ÷ 8.0 × 100 = 75 %."}
 ]};